import Stats from 'stats.js'
import * as THREE from 'three'
import { WebGLRenderer } from 'three'
import { VRButton } from 'three/examples/jsm/webxr/VRButton.js'
import { WebGPURenderer } from 'three/webgpu'

import { RendererCore } from '..'
import FrameRateMonitor from '../../utils/FrameRateMonitor'
import { createRenderer, isWebGPUSupported } from '../../utils/ThreeUtils'

export class RendererWrapper {
  public core: RendererCore
  public scene: THREE.Scene
  public renderer: WebGLRenderer | WebGPURenderer | undefined = undefined

  public canvas: HTMLCanvasElement | undefined = undefined

  public divRenderingStatus: HTMLDivElement | undefined = undefined
  public debuggerModeLog: boolean = false

  private loadingDiv: HTMLDivElement | undefined = undefined

  private _stats: Stats | undefined = undefined
  private _initPost: boolean = true
  private _antialias: boolean = true

  private _adaptiveRendering: boolean = false
  private _keepRendering: boolean = true
  private _forceRenderActive: boolean = false
  private _isRendering: boolean = false
  private _isPageVisible: boolean = true
  private _isLoopActive: boolean = false

  private idleTime: number = 0
  private _pixelRatio: number
  private _currentPixelRatio: number
  private _initFrame: number = 0

  private fpsMonitor: FrameRateMonitor
  private readonly MAX_IDLE_SECONDS: number = 2.5
  private readonly TARGET_FPS: number

  constructor(
    threeCore: RendererCore,
    enableAdaptiveRendering: boolean = true,
    frameRate: number = 30,
    pixelRatio: number = Math.min(window.devicePixelRatio, 2)
  ) {
    this.core = threeCore
    THREE.Object3D.DEFAULT_UP.copy(this.core.upVector)

    this.fpsMonitor = new FrameRateMonitor(frameRate)

    this.TARGET_FPS = frameRate
    this._pixelRatio = this.core.isPerformanceMode ? 1 : pixelRatio
    this._currentPixelRatio = this._pixelRatio

    this.keepRendering = true
    this.adaptiveRendering = enableAdaptiveRendering
  }
  public async init(): Promise<void> {
    try {
      this.appendLoading()
      this.canvas = document.createElement('canvas')

      this.scene = new THREE.Scene()
      this.scene.background = new THREE.Color(0xffffff)
      this.scene.castShadow = true
      this.scene.receiveShadow = true

      const webGPUSupported = await isWebGPUSupported()
      this.core.useWebGPU = this.core.useWebGPU && webGPUSupported

      this.renderer = await createRenderer({
        canvas: this.canvas,
        alpha: !this.core.isPerformanceMode,
        antialias: this._antialias,
        performanceMode: this.core.isPerformanceMode,
        useWebGPU: this.core.useWebGPU,
        powerPreference: 'high-performance'
      })

      if (!this.renderer) throw new Error('Failed to create renderer')

      this.renderer.setPixelRatio(this._currentPixelRatio)

      this.renderer.shadowMap.enabled = true
      this.renderer.shadowMap.type = THREE.PCFSoftShadowMap
      this.renderer.toneMapping = THREE.ACESFilmicToneMapping
      this.renderer.toneMappingExposure = 0.85
      this.renderer.outputColorSpace = THREE.SRGBColorSpace
      this.renderer.localClippingEnabled = true

      if (this.renderer instanceof WebGLRenderer) {
        this.renderer.sortObjects = false
        this.renderer.info.autoReset = false
      }

      this.renderer.domElement.id = 'hypercube-renderer'
      this.core.host.appendChild(this.renderer.domElement)

      if (this.core.vrMode) {
        await this.initXR()
        this.core.host.appendChild(VRButton.createButton(this.renderer))
      }

      window.addEventListener('resize', this.resizeHandler)
      window.addEventListener('fullscreenchange', this.resizeHandler)
      document.addEventListener('visibilitychange', this.visibilityHandler)

      this.resizeHandler()

      this.initBinding()
    } catch (error) {
      console.error('Initialization failed:', error)
      throw error
    }
  }
  public enableCastReceiveShadow(castShadow: boolean, receiveShadow: boolean) {
    this.renderer.shadowMap.enabled = castShadow

    this.scene.traverse((obj) => {
      if (obj.isLight) {
        obj.castShadow = castShadow
      }
      if (obj.isMesh) {
        obj.castShadow = castShadow
        obj.receiveShadow = receiveShadow
      }
    })
  }
  public async initXR() {
    this.renderer.xr.enabled = true
  }
  private setPixelRatio(value: number) {
    this._currentPixelRatio = value
    this.renderer?.setPixelRatio(this._currentPixelRatio)
  }
  private initBinding(): void {
    this.core.scene = this.scene
    this.core.renderer = this.renderer
  }
  public toggleAdaptiveRendering(): void {
    this.adaptiveRendering = !this.adaptiveRendering
  }
  public get adaptiveRendering(): boolean {
    return this._adaptiveRendering
  }
  public set adaptiveRendering(value: boolean) {
    if (this._adaptiveRendering === value) return
    this._adaptiveRendering = value
    this.keepRendering = !value
    this.idleTime = 0
    this.startLoop()
  }
  public get deltaTime() {
    return this.fpsMonitor.getDeltaTime()
  }
  public get keepRendering(): boolean {
    return this._keepRendering
  }
  public set keepRendering(value: boolean) {
    if (this._keepRendering === value) return
    this._keepRendering = value
    this.startLoop()
  }
  public renderForce(): void {
    if (this._isRendering) {
      this.idleTime = 0
      return
    }

    this._forceRenderActive = true
    this._keepRendering = true
    this.idleTime = 0

    this.fpsMonitor.reset()
    this.startLoop()
  }
  private visibilityHandler = (): void => {
    this._isPageVisible = !document.hidden

    if (this._isPageVisible) {
      this.fpsMonitor.reset()
      this.idleTime = 0
      this._initFrame = 0
      this.startLoop()
    } else {
      this.stopLoop()
    }
  }
  private startLoop(): void {
    if (this._isLoopActive) return

    if (!this.renderer || !this._isPageVisible) return

    this._isLoopActive = true
    this.renderer.setAnimationLoop(this.loop)
  }
  private stopLoop(): void {
    if (!this.renderer || !this._isLoopActive) return

    this._isLoopActive = false
    this.renderer.setAnimationLoop(null)
    this._isRendering = false
    this.updateRenderingStatus(false)
  }
  public start(): void {
    this.removeLoadingGIFDom()

    if (this.core.debuggerMode && !this.core.isProduction) {
      this._stats = new Stats()
      this._stats.showPanel(0)
      Object.assign(this._stats.dom.style, {
        position: 'absolute',
        top: '15px',
        right: '15px',
        left: ''
      })
      this.core.host.appendChild(this._stats.dom)

      this.divRenderingStatus = document.createElement('div')
      Object.assign(this.divRenderingStatus.style, {
        fontSize: '11px',
        color: '#181835',
        fontWeight: '300'
      })
      this._stats.dom.appendChild(this.divRenderingStatus)
    }
    this._initPost = false
    this.startLoop()
  }
  private loop = (): void => {
    if (!this.renderer || !this.canvas || !this.core) {
      if (!this.core?.isProduction) {
        console.warn('Renderer or core not initialized, skipping loop')
      }
      return
    }

    if (!this._isPageVisible) {
      this.stopLoop()
      return
    }

    if (!this.fpsMonitor.shouldRenderFrame()) {
      return
    }

    if (this._initFrame < 100) {
      this._initFrame += 1
    }

    this.renderFrame()
    this.fpsMonitor.update()

    this.adjustPixelRatio()
  }
  private renderFrame(): void {
    if (!this.core) return

    if (
      this._adaptiveRendering &&
      !this._keepRendering &&
      this.idleTime >= this.MAX_IDLE_SECONDS
    ) {
      this.updateRenderingStatus(false)
      this._isRendering = false
      this.stopLoop()
      return
    }

    if (!this.core.isProduction) {
      this.fpsMonitor.frameStart()
    }

    this.updateRenderingStatus(true)

    if (!this.core.ready || !this.core.readyBinding()) return

    if (this._initPost) this.start()

    this._stats?.begin()

    this._isRendering = true

    this.core.cameraWrapper.update()
    const sceneUpdated = this.core.update()

    if (
      sceneUpdated ||
      !this._adaptiveRendering ||
      this._keepRendering ||
      this._forceRenderActive
    ) {
      this.idleTime = 0
    } else {
      this.idleTime += this.deltaTime
    }

    if (this.core.useWebGPU || this.core.isPerformanceMode) {
      this.renderer.render(this.scene, this.core.cameraWrapper.camera)
    } else {
      this.core.postProcessingWrapper?.render()
    }

    if (this._forceRenderActive) {
      this._forceRenderActive = false
      if (this._adaptiveRendering) {
        this._keepRendering = false
      }
    }

    if (!this.core.isProduction) {
      this._stats?.end()
      this.fpsMonitor.frameEnd()

      if (
        this.fpsMonitor.getFrameCount() % this.TARGET_FPS === 0 &&
        this.renderer instanceof WebGLRenderer
      ) {
        this.renderer.info.reset()
      }

      if (this.fpsMonitor.getFrameCount() % (this.TARGET_FPS * 300) === 0) {
        this.fpsMonitor.trimHistory(30)
      }

      if (this.debuggerModeLog) {
        this.logFrameMetrics()
      }
    }
  }
  private adjustPixelRatio(): void {
    if (
      this._initFrame < 90 ||
      this.fpsMonitor.getFrameCount() % (this.TARGET_FPS * 2) !== 0
    ) {
      return
    }

    const avgFps = this.fpsMonitor.getStats().currentFPS

    if (avgFps < 20 && this._currentPixelRatio > 1) {
      this._currentPixelRatio = Math.max(1, this._currentPixelRatio - 0.5)
      this.renderer?.setPixelRatio(this._currentPixelRatio)

      if (!this.core.isProduction) {
        console.log(
          `[PixelRatio] FPS too low (${avgFps.toFixed(1)}), reducing to ${this._currentPixelRatio}`
        )
      }
    }
    else if (avgFps > 50 && this._currentPixelRatio < this._pixelRatio) {
      this._currentPixelRatio = Math.min(
        this._pixelRatio,
        this._currentPixelRatio + 0.5
      )
      this.renderer?.setPixelRatio(this._currentPixelRatio)

      if (!this.core.isProduction) {
        console.log(
          `[PixelRatio] FPS good (${avgFps.toFixed(1)}), increasing to ${this._currentPixelRatio}`
        )
      }
    }
  }
  private updateRenderingStatus(isRendering: boolean): void {
    if (this.core.isProduction || !this.divRenderingStatus) return

    const stats = this.fpsMonitor.getStats()
    const memory = this.getLogMemoryStats().replace(/\s*\|\s*/g, '<br>')
    const mode = this.core.isPerformanceMode ? 'Perf' : 'Quality'
    const visibility = this._isPageVisible ? 'Vis' : 'Hidden'
    const perfLevel = this.fpsMonitor.getPerformanceLevel()

    this.divRenderingStatus.innerHTML = isRendering
      ? `Web${this.core.useWebGPU ? 'GPU' : 'GL'} ${mode}<br>Page: ${visibility}<br>Loop: ${this._isLoopActive ? 'ON' : 'OFF'}<br>Perf: ${perfLevel}<br>Target: ${this.TARGET_FPS} FPS<br>Actual: ${stats.currentFPS} FPS<br>Avg: ${stats.averageFrameTime.toFixed(1)}ms<br>Delta: ${this.deltaTime.toFixed(3)}s<br>Ratio: ${this._currentPixelRatio.toFixed(1)}/${this._pixelRatio.toFixed(1)}<br>${memory}`
      : `Web${this.core.useWebGPU ? 'GPU' : 'GL'} ${mode}<br>Page: ${visibility}<br>Loop: ${this._isLoopActive ? 'ON' : 'OFF'}<br>STOPPED<br>Avg: ${stats.averageFrameTime.toFixed(1)}ms<br>Ratio: ${this._currentPixelRatio.toFixed(1)}/${this._pixelRatio.toFixed(1)}<br>${memory}`
  }
  private logFrameMetrics(): void {
    const stats = this.fpsMonitor.getStats()
    const frameCount = this.fpsMonitor.getFrameCount()
    const lastFrameTime = this.fpsMonitor.getLastFrameTime()
    const mode = this.core.isPerformanceMode ? 'Performance' : 'Quality'
    const perfLevel = this.fpsMonitor.getPerformanceLevel()

    console.debug(
      `[Frame ${frameCount}] ${lastFrameTime.toFixed(2)}ms | ` +
        `${mode} | Perf: ${perfLevel} | FPS: ${stats.currentFPS} (Target: ${this.TARGET_FPS}) | ` +
        `Delta: ${this.deltaTime.toFixed(3)}s | Idle: ${this.idleTime.toFixed(2)}s | ` +
        `Ratio: ${this._currentPixelRatio}/${this._pixelRatio} | ` +
        `Loop: ${this._isLoopActive} | Visible: ${this._isPageVisible}`
    )
  }
  private removeLoadingGIFDom(): void {
    if (this.loadingDiv && this.core?.host.contains(this.loadingDiv)) {
      this.core.host.removeChild(this.loadingDiv)
      this.loadingDiv = undefined
    }
  }
  public appendLoading(): void {
    const loadingDiv = document.createElement('div')
    loadingDiv.id = 'loading'
    Object.assign(loadingDiv.style, {
      position: 'relative',
      top: '50%',
      left: '50%',
      transform: 'translate(-50%, -50%)',
      zIndex: '9999',
      backgroundColor: 'transparent',
      padding: '10px',
      borderRadius: '8px'
    })

    const path = '/hypercube-asset/image/loadingTransparent.gif'
    const loadingImg = document.createElement('img')
    Object.assign(loadingImg, {
      src: path,
      style: { backgroundColor: 'transparent' },
      alt: 'Loading...',
      width: 40
    })
    loadingDiv.appendChild(loadingImg)
    loadingDiv.style.position = 'absolute'
    this.loadingDiv = loadingDiv
    this.core.host.appendChild(loadingDiv)
  }
  public resizeHandler = (): void => {
    if (!this.renderer || !this.core) return

    const rect = this.core.host.getBoundingClientRect()

    const width = rect.width
    const height = rect.height

    this.renderer.setPixelRatio(this._currentPixelRatio)
    this.renderer.setSize(width, height)

    if (this.core.cameraWrapper?.camera instanceof THREE.PerspectiveCamera) {
      this.core.cameraWrapper.camera.aspect = width / height
      this.core.cameraWrapper.camera.updateProjectionMatrix()
    }

    this.renderForce()
  }
  private getLogMemoryStats(): string {
    if (!this.renderer) return 'N/A'

    const gpu = this.renderer.info.memory
    const heapSize = performance.memory?.usedJSHeapSize

    return `Heap: ${heapSize ? (heapSize / 1024 / 1024).toFixed(1) : '?'}MB | Geo: ${gpu.geometries} | Tex: ${gpu.textures}`
  }
  public disposeScene(): void {
    this.stopLoop()

    window.removeEventListener('resize', this.resizeHandler)
    window.removeEventListener('fullscreenchange', this.resizeHandler)
    document.removeEventListener('visibilitychange', this.visibilityHandler)

    if (this._stats && this.core?.host.contains(this._stats.dom)) {
      this.core.host.removeChild(this._stats.dom)
      this._stats = undefined
    }

    this.scene.traverse((object: THREE.Object3D) => {
      const mesh = object as THREE.Mesh

      if (mesh.geometry && typeof mesh.geometry.dispose === 'function') {
        mesh.geometry.dispose()
      }

      const material = mesh.material as
        | THREE.Material
        | THREE.Material[]
        | undefined

      if (material) {
        const disposeTexture = (tex: THREE.Texture | null): void => {
          if (tex && typeof tex.dispose === 'function') {
            tex.dispose()
          }
        }

        const disposeMaterial = (m: THREE.Material): void => {
          disposeTexture(m.map)
          disposeTexture(m.normalMap)
          disposeTexture(m.roughnessMap)
          disposeTexture(m.metalnessMap)
          disposeTexture(m.bumpMap)
          disposeTexture(m.alphaMap)
          disposeTexture(m.emissiveMap)
          disposeTexture(m.aoMap)
          disposeTexture(m.displacementMap)
          disposeTexture(m.lightMap)
          disposeTexture(m.specularMap)

          if (typeof m.dispose === 'function') {
            m.dispose()
          }
        }

        if (Array.isArray(material)) {
          material.forEach(disposeMaterial)
        } else {
          disposeMaterial(material)
        }
      }
    })

    const disposeEnvTexture = (
      tex: THREE.Texture | THREE.Color | null
    ): void => {
      if (tex && 'dispose' in tex && typeof tex.dispose === 'function') {
        tex.dispose()
      }
    }
    disposeEnvTexture(this.scene.background)
    disposeEnvTexture(this.scene.environment)

    this.scene.background = null
    this.scene.environment = null

    const lights: THREE.Light[] = []
    this.scene.traverse((obj: THREE.Object3D) => {
      if (obj instanceof THREE.Light) {
        lights.push(obj)
      }
    })
    lights.forEach((light) => this.scene.remove(light))

    this.scene.clear()

    if (this.renderer) {
      this.renderer.dispose()
      if (
        this.renderer.domElement &&
        this.core?.host.contains(this.renderer.domElement)
      ) {
        this.core.host.removeChild(this.renderer.domElement)
      }
      this.renderer = undefined
    }

    this.canvas = undefined
    this.removeLoadingGIFDom()
  }
}
