import { Mesh } from 'three'

import { Configurator } from '..'
import { easeInOut } from '../../../../utils/ThreeUtils'

export class AnimationController {
  public configurator: Configurator

  private fovAnimationId: number | null = null
  private clippingAnimationId: number | null = null
  private isDroneAni = false

  private disposed = false

  constructor(configurator: Configurator) {
    this.configurator = configurator
  }
  public onFocus(mesh: Mesh, distance = 8) {
    this.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      mesh,
      distance
    )
  }
  public clippingAnimation(axis: string, target: number, duration = 2000) {
    if (this.clippingAnimationId !== null) {
      cancelAnimationFrame(this.clippingAnimationId)
      this.clippingAnimationId = null
    }
    const startTime = performance.now()
    const planes = this.configurator.clippingController.clippingPlanes
    let startValue = 0
    switch (axis.toLowerCase()) {
      case 'x':
        startValue = planes[1].constant
        break
      case 'y':
        startValue = planes[0].constant
        break
      case 'z':
        startValue = planes[2].constant
        break
    }
    const animate = (now: number) => {
      const elapsed = now - startTime
      const progress = Math.min(elapsed / duration, 1)
      const value = startValue + (target - startValue) * progress
      switch (axis.toLowerCase()) {
        case 'x':
          this.configurator.clippingController.updateXClipping(value)
          break
        case 'y':
          this.configurator.clippingController.updateYClipping(value)
          break
        case 'z':
          this.configurator.clippingController.updateZClipping(value)
          break
      }
      if (progress < 1) {
        this.clippingAnimationId = requestAnimationFrame(animate)
      } else {
        this.clippingAnimationId = null
      }
    }
    this.clippingAnimationId = requestAnimationFrame(animate)
  }

  public toggleActivateDroneNest() {
    if (this.isDroneAni) return
    this.isDroneAni = true

    this.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      this.configurator.hypercubeParametric.nubbin.cantileverDrone?.mesh
    )

    const time = [4000, 3300, 3300, 3300, 4000, 4000, 3000]
    setTimeout(() => {
      this.configurator.hypercubeParametric.nubbin.cantileverDrone?.openNest()
    }, 1000)

    setTimeout(() => {
      let count = 0
      const moveDrone = () => {
        if (count >= 7) return
        this.configurator.hypercubeParametric.nubbin.droneReadyNet?.moveToNextPosition()
        count++
        setTimeout(moveDrone, time[count])

        this.configurator.sceneWrapper.appCore.common.renderForce()
      }

      moveDrone()
    }, 2000)

    setTimeout(
      () => {
        this.configurator.hypercubeParametric.nubbin.cantileverDrone?.closeNest()
        this.isDroneAni = false
      },
      time.reduce((acc, cur) => acc + cur, 0) - 2000
    )
  }
  public animatingFOV(targetValue: number, duration: number = 1000) {
    if (this.disposed) return

    const camera =
      this.configurator.sceneWrapper.appCore.rendererCore.cameraWrapper.camera

    if (this.fovAnimationId !== null) {
      cancelAnimationFrame(this.fovAnimationId)
      this.fovAnimationId = null
    }

    const startFov = camera.fov
    const startTime = performance.now()

    const animate = (now: number) => {
      if (this.disposed) return

      const elapsed = now - startTime
      const t = Math.min(elapsed / duration, 1)
      const eased = easeInOut(t)

      camera.fov = startFov + (targetValue - startFov) * eased
      camera.updateProjectionMatrix()

      if (t < 1) {
        this.fovAnimationId = requestAnimationFrame(animate)
      } else {
        this.fovAnimationId = null
      }
    }

    this.fovAnimationId = requestAnimationFrame(animate)
  }

  public dispose() {
    this.disposed = true

    if (this.fovAnimationId !== null) {
      cancelAnimationFrame(this.fovAnimationId)
      this.fovAnimationId = null
    }

    if (this.clippingAnimationId !== null) {
      cancelAnimationFrame(this.clippingAnimationId)
      this.clippingAnimationId = null
    }
  }
}
