import * as THREE from 'three'

import { Nubbin } from '.'
import { NubbinBase } from './Base/NubbinBase'
import { loadFBX, loadFBXWithMat } from '../../../../../utils/ThreeUtils'

export class Cellular extends NubbinBase {
  public mesh: THREE.Group

  private offset = -3

  constructor(addon: Nubbin) {
    super(addon)

    this.mesh = new THREE.Group()
    this.mesh.name = 'Cellular'

    this.loadModel(
      [
        // addon.hypercubeParametric.configurator.BASE_URL + 'Cellular.fbx',
        '/hypercube-asset/model/cellularNubbins.fbx'
      ],
      0.1
    )
    // this.loadModel([process.env.PUBLIC_URL + '/static/data/LaserDevice-.fbx'], 0.01);
  }
  private loadModel = async (files: string[], scale: number) => {
    // console.log(files, scale);
    try {
      const loadPromises = files.map((file) =>
        // loadFBX(
        // 	file,
        // 	scale,
        // 	this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.rendererCore.useWebGPU,
        // 	this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.isPerformanceMode,
        // 	this.addon.hypercubeParametric.configurator.materials.clippingPlanes
        // )
        loadFBXWithMat(
          file,
          scale,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .rendererCore.useWebGPU,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .isPerformanceMode,
          this.nubbin.hypercubeParametric.configurator.materials.clippingPlanes,
          this.nubbin.hypercubeParametric.configurator.materials.MaterialClass,
          this.nubbin.hypercubeParametric.configurator.materials.nubbinMaterial
        )
      )

      const fbxModels = await Promise.all(loadPromises)
      fbxModels[0].rotation.y = -Math.PI * 0.5
      this.mesh = fbxModels[0]
      this.mesh.children[1].material =
        this.nubbin.hypercubeParametric.configurator.materials.aluminumMaterial

      this.mesh.children[0].material.color = new THREE.Color(0xd9d9d9)
      this.mesh.children[2].material.color = new THREE.Color(0xd9d9d9)
      this.syncSizes()

      this.mesh.userData.onClick = () => this.onClick()

      this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.add(
        this.mesh
      )
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  public setHight(_value: number) {
    this.syncSizes()
  }
  public syncSizes() {
    if (this.mesh) {
      this.mesh.position.y =
        this.nubbin.hypercubeParametric.params.height +
        this.nubbin.hypercubeParametric.params.groundY +
        this.nubbin.disco.params.height +
        this.offset
    }
  }
  public toggleVisibility() {
    this.mesh.visible = !this.mesh.visible
  }
  public update(): boolean {
    throw new Error('Method not implemented.')
  }
  public onClick() {
    this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      this.mesh,
      1
    )
    this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.actionStateProcessor.emitAction(
      'cellular@'
    )
  }
}
