import * as THREE from 'three'

import { SceneWrapper } from '../'
import { AnimationAssembly } from './Helper/AnimationAssembly'
import { HypercubeParametric } from './HypercubeParametric'
import { Materials } from '../../Asset/Materials'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'
import { AnimationController } from './Helper/AnimationController'
import { ClippingController } from './Helper/ClippingController'
import { GizmoController } from './Helper/GizmoController'
import { XrayViewController } from './Helper/XrayViewController'

export class Configurator extends MeshWrapperCommon {
  public hypercubeParametric!: HypercubeParametric
  public meshSphere!: THREE.Mesh

  public materials: Materials
  public gizmoController!: GizmoController
  public xrayViewController!: XrayViewController
  public clippingController!: ClippingController

  public animationController!: AnimationController
  public animationAssembly!: AnimationAssembly

  public BASE_URL =
    'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/cube/'

  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)
    this.materials = this.sceneWrapper.appCore.asset.materials
    this.init()
  }
  public init() {
    this.hypercubeParametric = new HypercubeParametric(this)

    this.animationController = new AnimationController(this)
    this.animationAssembly = new AnimationAssembly(this)

    this.clippingController = new ClippingController(this)
    this.xrayViewController = new XrayViewController(this)
    this.gizmoController = new GizmoController(this)
    this.gizmoController.isActivated = false
    this.gizmoController.renderForce = () => {
      this.sceneWrapper.appCore.common.renderForce()
    }

    // this.ready = true
    // console.log(this.ready)

    // TODO: After the demo, resolve the code
    setTimeout(() => {
      this.ready = true
    }, 2000)
  }
  public initPost() {
    this.xrayViewController.initPost()
    this.hypercubeParametric.initPost()

    this.animationAssembly.initPost()
  }
  public showNubbin(show: boolean) {
    this.hypercubeParametric.nubbin.show(show)
  }
  public toggleGizmo() {
    this.gizmoController.isActivated = !this.gizmoController.isActivated
  }
  public toggleXrayParametricModel(v: boolean) {
    this.xrayViewController.toggleMode(v)
  }
  public toggleClippingMode(value: boolean) {
    this.clippingController.toggleMode()
  }
  public updateXrayView() {
    this.xrayViewController.update()
  }
  public updateClipping(value: number) {
    // this.globalClippingPlane.constant = value;
  }
  public add(): void {
    this.sceneWrapper.add(this)
  }

  public update(): boolean {
    return this.hypercubeParametric.update()
  }

  public show(value: boolean) {
    // TODO
  }
  public showServer(Show: boolean) {
    return this.hypercubeParametric.server.show(Show)
  }
  public showFoundation(Show: boolean) {
    return this.hypercubeParametric.foundationBase.show(Show)
  }
  public getParameter() {
    return this.hypercubeParametric.getParameter()
  }
  public destroy(): void {
    this.gizmoController?.dispose()
    this.xrayViewController?.dispose()
    this.animationController?.dispose()
    this.animationDecomposed?.dispose()
  }
}
