/* eslint-disable no-restricted-imports */
import { runOptimization } from '../../Helper/HCGeneticAlgorithm'

class Domain {
  public min: number = 0
  public max: number = 0
  constructor(min: number, max: number) {
    this.min = min
    this.max = max
  }
}
class Constraint {
  public width: Domain = new Domain(0, 1)
  public length: Domain = new Domain(0, 1)
  public height: Domain = new Domain(0, 1)
}
class WallUnit {
  public height: number = 0.5
  public heightGap: number = 0.5
  public thickness: number = 0.8
}

export class Parameters {
  public thickness = 3.5
  public radiusCamera = 0.8

  public groundY = -9

  public unitScale = 1

  public epsilon = 0.005

  public constraint = new Constraint()

  public WallUnit = new WallUnit()

  private _width: number = 37
  private _length: number = 37
  private _height: number = 36

  private _volumeTarget: number = 10000

  constructor() {
    this.constraint.width = new Domain(20, 50)
    this.constraint.length = new Domain(20, 50)
    this.constraint.height = new Domain(20, 50)

    this.WallUnit.height = 0.5
    this.WallUnit.heightGap = 0.2
    this.WallUnit.thickness = 0.2
  }

  public setSize(width: number, height: number, length: number) {
    this.width = width
    this.height = height
    this.length = length
  }
  public get width() {
    return this._width
  }
  public set width(value: number) {
    this._width = Math.min(
      Math.max(value, this.constraint.width.min),
      this.constraint.width.max
    )
  }
  public get height() {
    return this._height
  }
  public set height(value: number) {
    this._height = Math.min(
      Math.max(value, this.constraint.height.min),
      this.constraint.height.max
    )
  }
  public get length() {
    return this._length
  }
  public set length(value: number) {
    this._length = Math.min(
      Math.max(value, this.constraint.length.min),
      this.constraint.length.max
    )
  }
  public setThickness(value: number) {
    this.thickness = value
    if (this.radiusCamera * 2.0 + 0.2 > this.thickness) {
      this.radiusCamera = this.thickness * 0.5 - 0.2
    }
  }
  public setCameraSize(value: number) {
    if (value * 2.0 + 0.2 > this.thickness) return
    this.radiusCamera = value
  }
  public setHeightRollingPanel(value: number) {
    this.WallUnit.height = value
  }
  public setGapRollingPanel(value: number) {
    this.WallUnit.heightGap = value
  }
  public getLog(digits: number = 2) {
    return `
			Width: ${this._width.toFixed(digits)}, 
			Length: ${this._length.toFixed(digits)}, 
			Height: ${this._height.toFixed(digits)}, 
			Thickness: ${this.thickness.toFixed(digits)}, 
			Camera Radius: ${this.radiusCamera.toFixed(digits)},
			Volume approximation: ${this.getVolumeApproximate()}
			`
  }
  public getVolumeApproximate(digits: number = 2) {
    const offset = this.thickness * 2.0
    const height = this._height - offset
    const width = this._width - offset
    const length = this._length - offset
    return (height * width * length * this.unitScale).toFixed(digits)
  }
  set volumeTarget(value: number) {
    this._volumeTarget = value
  }
  public runOptimization() {
    return runOptimization(this._volumeTarget, this)
  }
}
