import * as THREE from 'three'

import { FoundationInnerCooling } from './FoundationInnerCooling'

export class GyroidMesh {
  public mesh!: THREE.Group
  public meshPoints: THREE.Points | undefined
  public glassBox: THREE.Mesh | undefined
  public foundationInnerCooling: FoundationInnerCooling

  private heatSpeed = 8
  private time = 0
  private webGPU = false
  private hasAnimation = false

  private geometry: THREE.BufferGeometry | undefined

  constructor(foundationInnerCooling: FoundationInnerCooling) {
    this.foundationInnerCooling = foundationInnerCooling
    this.innit()
  }
  private innit() {
    this.mesh = new THREE.Group()
    const xOffset = 0
    const yOffset = -44
    const zOffset = -2

    const widthZ = 21
    const lengthX = 30
    const heightY = 25

    this.webGPU =
      this.foundationInnerCooling.foundationBase.hypercubeParametric.configurator.sceneWrapper.appCore.rendererCore.useWebGPU

    // const scene =
    //   this.foundationInnerCooling.foundationBase.hypercubeParametric
    //     .configurator.sceneWrapper.scene

    this.geometry = createGyroidGeometry(lengthX, heightY, widthZ)

    const material = this.webGPU
      ? createWebGPUMaterial()
      : createWebGLMaterial()

    this.meshPoints = new THREE.Points(this.geometry, material)
    this.meshPoints.position.set(xOffset, yOffset, zOffset)
    // scene.add(this.meshPoints)
    this.mesh.add(this.meshPoints)

    const boxGeo = new THREE.BoxGeometry(lengthX, heightY, widthZ)
    const boxMat = new THREE.MeshBasicMaterial({
      color: 0x444444,
      transparent: true,
      opacity: 0.5,
      side: THREE.BackSide
    })
    this.glassBox = new THREE.Mesh(boxGeo, boxMat)
    this.glassBox.position.set(xOffset, yOffset, zOffset)
    // scene.add(this.glassBox)
    this.mesh.add(this.glassBox)

    const edges = new THREE.EdgesGeometry(boxGeo)
    const line = new THREE.LineSegments(
      edges,
      new THREE.LineBasicMaterial({
        color: 0x666666,
        transparent: true,
        opacity: 0.2
      })
    )
    line.position.set(xOffset, yOffset, zOffset)
    // scene.add(line)
    this.mesh.add(line)
    // this.mesh.userData.onClick = () => this.onClick() // it is not working now

    this.foundationInnerCooling.foundationBase.hypercubeParametric.configurator.sceneWrapper.scene.add(
      this.mesh
    )
  }

  public update() {
    this.time += 0.005 * this.heatSpeed
    const scaleVariation = Math.sin(this.time * 0.5) * 0.3 + 0.5

    if (this.webGPU) {
      // WebGPU pipeline
      const positions = this.geometry?.getAttribute('position')
      const colors = this.geometry?.getAttribute('color')

      if (positions && colors) {
        for (let i = 0; i < positions.count; i++) {
          const x = positions.getX(i)
          const y = positions.getY(i)
          const z = positions.getZ(i)

          const n = noise3D(x, y, z, this.time * 10, scaleVariation)
          const temperature = Math.max(0, Math.min(1, n * 0.5 + 0.5))

          const r = 0.05 + (0.9 - 0.05) * temperature
          const g = 0.2 - (0.2 - 0.05) * temperature
          const b = 0.9 - (0.9 - 0.05) * temperature

          colors.setXYZ(i, r, g, b)
        }
        colors.needsUpdate = true
      }
    } else {
      // WebGL pipeline
      if (this.meshPoints?.material instanceof THREE.ShaderMaterial) {
        this.meshPoints.material.uniforms.uTime.value = this.time
        this.meshPoints.material.uniforms.uNoiseScale.value = scaleVariation
      }
    }
    return this.hasAnimation
  }
  public onClick(): void {
    this.foundationInnerCooling.foundationBase.hypercubeParametric.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      this.meshPoints,
      1
    )
    this.foundationInnerCooling.foundationBase.hypercubeParametric.configurator.sceneWrapper.appCore.actionStateProcessor.emitAction(
      'gyroidCooling@'
    )
  }
}

const noise3D = (
  x: number,
  y: number,
  z: number,
  time: number,
  scale: number
): number => {
  const sx = x * scale
  const sy = y * scale
  const sz = z * scale

  return (
    (Math.sin(sx * 1.2 + time) * Math.cos(sy * 1.5 + time * 0.8) +
      Math.sin(sz * 1.4 + time * 0.5) * Math.cos(sx * 1.1 + time) +
      Math.sin(sy * 1.3 + time * 1.2) * Math.cos(sz * 1.6 + time * 0.9)) /
    2.5
  )
}
const createGyroidGeometry = (
  lengthX = 30,
  heightY = 25,
  widthZ = 21,
  resolution = 150,
  scale = 1.3
) => {
  const vertices = []
  const colors = []

  for (let i = 0; i <= resolution; i++) {
    const x = (i / resolution - 0.5) * lengthX
    for (let j = 0; j <= resolution; j++) {
      const y = (j / resolution - 0.5) * heightY
      for (let k = 0; k <= resolution; k++) {
        const z = (k / resolution - 0.5) * widthZ
        const v =
          Math.sin(x * scale) * Math.cos(y * scale) +
          Math.sin(y * scale) * Math.cos(z * scale) +
          Math.sin(z * scale) * Math.cos(x * scale)

        if (Math.abs(v) < 0.12) {
          vertices.push(x, y, z)
          colors.push(0.05, 0.2, 0.9)
        }
      }
    }
  }

  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute(
    'position',
    new THREE.Float32BufferAttribute(vertices, 3)
  )
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3))
  return geometry
}

const createWebGLMaterial = () => {
  return new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0.0 },
      uNoiseScale: { value: 0.4 }
    },
    vertexShader: `
        varying vec3 vColor;
        uniform float uTime;
        uniform float uNoiseScale;

        float noise3D(vec3 p) {
            return (
                sin(p.x * 1.2 + uTime) * cos(p.y * 1.5 + uTime * 0.8) +
                sin(p.z * 1.4 + uTime * 0.5) * cos(p.x * 1.1 + uTime) +
                sin(p.y * 1.3 + uTime * 1.2) * cos(p.z * 1.6 + uTime * 0.9)
            ) / 2.5;
        }

        void main() {
            vec3 pos = position;
            
            float n = noise3D(pos * uNoiseScale); 
            
            float temperature = clamp(n * 0.5 + 0.5, 0.0, 1.0);

            vec3 blueWater = vec3(0.05, 0.2, 0.9);
            vec3 redWater = vec3(0.9, 0.05, 0.05);
            
            vColor = mix(blueWater, redWater, temperature);

            vec4 mvPosition = modelViewMatrix * vec4(pos, 1.0);
            gl_PointSize = 1.6 * (300.0 / -mvPosition.z); 
            gl_Position = projectionMatrix * mvPosition;
        }
      `,
    fragmentShader: `
        varying vec3 vColor;
        void main() {
            float r = distance(gl_PointCoord, vec2(0.5));
            if (r > 0.28) discard;
            gl_FragColor = vec4(vColor, 0.85);
        }
      `,
    transparent: true,
    blending: THREE.NormalBlending,
    depthWrite: true
  })
}

const createWebGPUMaterial = () => {
  return new THREE.PointsMaterial({
    size: 15,
    vertexColors: true,
    transparent: true,
    opacity: 0.9,
    sizeAttenuation: true,
    depthWrite: true
  })
}
