import * as THREE from 'three'

import { Configurator } from '..'
import {
  easeInOut,
  getFlattenMeshes,
  filterMeshesByNames,
  excludeMeshesByNames
} from '../../../../utils/ThreeUtils'

interface AnimationState {
  mesh: THREE.Mesh
  materials: THREE.Material[]
  startOpacities: number[]
  targetOpacity: number
  startTime: number
  duration: number
  frameId: number | null
}

export class XrayViewController {
  public configurator: Configurator
  public isActivated: boolean = false
  private activeAnimations = new Map<THREE.Mesh, AnimationState>()

  private meshes: THREE.Mesh[] = []

  private meshesCaseA: THREE.Mesh[] = []
  private meshesCaseB: THREE.Mesh[] = []
  private meshesCaseC: THREE.Mesh[] = []

  constructor(configurator: Configurator) {
    this.configurator = configurator
  }

  public initPost() {
    // add mesh
    const { hypercubeParametric } = this.configurator

    const serverCaseShowKeys = ['red', 'blue']
    const serverCaseHideKeys = ['RearDoor', 'Door', 'Body1']
    const serverXrayList = [
      ...filterMeshesByNames(
        getFlattenMeshes(hypercubeParametric.server.mesh),
        serverCaseHideKeys
      ),
      ...excludeMeshesByNames(
        getFlattenMeshes(hypercubeParametric.server.mesh),
        serverCaseShowKeys
      )
    ]

    const founddddKeys = ['innerCoolingWall', 'PillarFacade']
    const innerCoolingList = [
      ...filterMeshesByNames(
        getFlattenMeshes(
          hypercubeParametric.foundationBase.foundationInnerCooling.mesh
        ),
        founddddKeys
      )
    ]
    this.meshesCaseA = [
      ...hypercubeParametric.exoSkeletonMeshes.columns,
      ...hypercubeParametric.exoSkeletonMeshes.cameras,
      ...hypercubeParametric.exoSkeletonMeshes.bars,
      ...hypercubeParametric.rollingDoors.mesh,
      ...hypercubeParametric.wall.mesh
    ]

    this.meshesCaseB = [
      ...this.meshesCaseA,

      hypercubeParametric.nubbin.panel?.mesh,
      hypercubeParametric.nubbin.laserDevice?.mesh,
      ...getFlattenMeshes(hypercubeParametric.nubbin.droneReadyNet.mesh),
      ...getFlattenMeshes(hypercubeParametric.nubbin.disco.mesh),
      ...getFlattenMeshes(hypercubeParametric.nubbin.cellular.mesh),
      ...getFlattenMeshes(hypercubeParametric.nubbin.laserDevice.mesh),
      ...getFlattenMeshes(hypercubeParametric.nubbin.droneDevice.mesh),

      ...serverXrayList
    ]

    this.meshesCaseC = [
      ...this.meshesCaseB,

      ...filterMeshesByNames(
        hypercubeParametric.configurator.hypercubeParametric.foundationBase.mesh
          ?.children,
        ['Foundation']
      ),
      ...innerCoolingList,

      hypercubeParametric.configurator.sceneWrapper.studioEnv.meshFloor
    ]
  }
  public toggleXRayHypercubeSkin() {
    this.isActivated = !this.isActivated
    this.meshes = [...this.meshesCaseA]
    this.update(0.1)
  }
  public toggleXRayCoolingHC() {
    this.isActivated = !this.isActivated
    this.meshes = [...this.meshesCaseB]
    this.update(0.15)
  }
  public toggleXRayInnerCooling() {
    this.isActivated = !this.isActivated
    this.meshes = [...this.meshesCaseC]
    this.update(0.07)
  }

  public toggleMode(value: boolean) {
    this.isActivated = value
    this.meshes = [...this.meshesCaseA]
    this.update()
  }
  public update(opacity = 0.1) {
    this.activeAnimations.forEach((state) => {
      if (state.frameId !== null) {
        cancelAnimationFrame(state.frameId)
      }
    })
    this.activeAnimations.clear()

    // const { hypercubeParametric } = this.configurator
    const targetOpacity = this.isActivated ? opacity : 1.0

    this.animateMeshes(this.meshes, targetOpacity)
    // this.animateMeshes(
    //   hypercubeParametric.exoSkeletonMeshes?.columns,
    //   targetOpacity
    // )
    // this.animateMeshes(
    //   hypercubeParametric.exoSkeletonMeshes?.bars,
    //   targetOpacity
    // )
    // this.animateMeshes(hypercubeParametric.rollingDoors?.mesh, targetOpacity)
    // this.animateMeshes(hypercubeParametric.wall?.mesh, targetOpacity)
  }

  public updateOpacity(opacity: number, ms: number) {
    this.activeAnimations.forEach((state) => {
      if (state.frameId !== null) {
        cancelAnimationFrame(state.frameId)
      }
    })
    this.activeAnimations.clear()

    this.animateMeshes(this.meshes, opacity, ms)

    // const { hypercubeParametric } = this.configurator
    // this.animateMeshes(
    //   hypercubeParametric.exoSkeletonMeshes?.columns,
    //   opacity,
    //   ms
    // )
    // this.animateMeshes(hypercubeParametric.exoSkeletonMeshes?.bars, opacity, ms)
    // this.animateMeshes(hypercubeParametric.rollingDoors?.mesh, opacity, ms)
    // this.animateMeshes(hypercubeParametric.wall?.mesh, opacity, ms)
  }

  private animateMeshes(
    meshes: THREE.Mesh[] | undefined,
    targetOpacity: number,
    duration: number = 2000
  ) {
    if (!meshes) return

    meshes.forEach((mesh: THREE.Mesh) => {
      this.animateSingleMesh(mesh, targetOpacity, duration)

      if (mesh.children && mesh.children.length > 0) {
        mesh.children.forEach((child) => {
          if (child instanceof THREE.Mesh) {
            this.animateSingleMesh(child, targetOpacity, duration)
          }
        })
      }
    })
  }

  private animateSingleMesh(
    mesh: THREE.Mesh,
    targetOpacity: number,
    duration: number
  ) {
    const materials = Array.isArray(mesh.material)
      ? mesh.material
      : [mesh.material]

    if (materials.length === 0 || !materials[0]) return

    const existingState = this.activeAnimations.get(mesh)
    if (existingState && existingState.frameId !== null) {
      cancelAnimationFrame(existingState.frameId)
    }

    const startOpacities = materials.map((mat) => mat.opacity ?? 1.0)

    const state: AnimationState = {
      mesh,
      materials,
      startOpacities,
      targetOpacity,
      startTime: Date.now(),
      duration,
      frameId: null
    }

    materials.forEach((mat) => {
      mat.transparent = true
    })

    this.activeAnimations.set(mesh, state)

    this.animate(state)
  }

  private animate(state: AnimationState) {
    const elapsed = Date.now() - state.startTime
    const progress = Math.min(elapsed / state.duration, 1)
    const eased = easeInOut(progress)

    state.materials.forEach((mat, index) => {
      const startOpacity = state.startOpacities[index]
      mat.opacity = startOpacity + (state.targetOpacity - startOpacity) * eased
      mat.needsUpdate = true
    })

    if (progress < 1) {
      state.frameId = requestAnimationFrame(() => this.animate(state))
    } else {
      state.materials.forEach((mat) => {
        mat.opacity = state.targetOpacity
        mat.transparent = state.targetOpacity < 1
        mat.needsUpdate = true
      })

      this.activeAnimations.delete(state.mesh)
    }
  }

  public dispose() {
    this.activeAnimations.forEach((state) => {
      if (state.frameId !== null) {
        cancelAnimationFrame(state.frameId)
      }
    })
    this.activeAnimations.clear()
  }
}
