  private loadAllModelSubstationA = async (
    files,
    scale,
    x: number,
    y: number,
    z: number
  ) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBX(
          'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/fbx/' +
            file,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.isPerformanceMode
        )
      )
      const fbxModels = await Promise.all(loadPromises)
      fbxModels.forEach((fbxGroup: THREE.Group) => {
        // fbx.rotation.x = Math.PI / 2;
        // console.log(fbx);
        fbxGroup.receiveShadow = !this.isPerformanceMode
        fbxGroup.castShadow = true // !this.isPerformanceMode

        fbxGroup.position.set(x, y, z)
        // this.meshesSubstation.push(fbxGroup)
        // fbxGroup.children.forEach((mesh) => {
        // this.meshesSubstationShadow.push(mesh)
        // })
      })
      this.mesh.add(fbxModels[0])
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  private async loadAllModelsFence(
    files,
    scale,
    x: number,
    y: number,
    z: number
  ) {
    try {
      const instances = [
        { x: 0, y: y, z: 94, rotation: 0, scaleX: scale.x * 0.97 },
        { x: 130, y: y, z: -9, rotation: Math.PI / 2, scaleX: scale.x * 0.77 },
        { x: -130, y: y, z: -9, rotation: Math.PI / 2, scaleX: scale.x * 0.77 }
      ]

      const loadPromises = files.map((file) =>
        loadFBXFence(
          'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/fbx/' +
            file,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.isPerformanceMode
        )
      )
      const fbxModels = await Promise.all(loadPromises)

      fbxModels.forEach((originalFbx) => {
        originalFbx.position.set(x, y, z)
        originalFbx.scale.set(scale.x * 0.97, scale.y, scale.z)
        this.mesh.add(originalFbx)
        // this.sceneWrapper.appCore.rendererCore.scene.add(originalFbx)

        instances.forEach(({ x: ix, y: iy, z: iz, rotation, scaleX = 1 }) => {
          const clone = originalFbx.clone(true)
          clone.position.set(ix, iy, iz)
          clone.rotation.y = rotation
          clone.scale.set(scaleX, scale.y, scale.z)
          this.mesh.add(clone)

          // this.sceneWrapper.appCore.rendererCore.scene.add(clone)
        })
      })
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  private loadAllModelSubstationB = async (
    files: string[],
    scale: number,
    x: number,
    y: number,
    z: number
  ) => {
    try {
      const fbx = await loadFBX(
        'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/fbx/' +
          files[0],
        scale,
        this.sceneWrapper.appCore.rendererCore.useWebGPU,
        this.isPerformanceMode
      )

      const meshes: THREE.Mesh[] = []
      fbx.traverse((child) => {
        if (child.isMesh) {
          // child.rotation.x = Math.PI / 2;
          // child.position.y = -18;
          child.receiveShadow = !this.isPerformanceMode
          child.castShadow = true // !this.isPerformanceMode

          meshes.push(child)
        }
      })

      const positions = [-100, 100]
      // const group = new THREE.Group()

      meshes.forEach((mesh) => {
        const inst = new THREE.InstancedMesh(
          mesh.geometry,
          mesh.material,
          positions.length
        )
        inst.castShadow = true // !this.isPerformanceMode
        inst.receiveShadow = !this.sceneWrapper.appCore.isPerformanceMode
        const dummy = new THREE.Object3D()
        for (let i = 0; i < positions.length; i++) {
          dummy.position.set(positions[i], y, z)
          dummy.rotation.copy(mesh.rotation)
          dummy.scale.set(scale, scale, scale)
          dummy.receiveShadow = !this.sceneWrapper.appCore.isPerformanceMode
          dummy.castShadow = !this.sceneWrapper.appCore.isPerformanceMode
          dummy.updateMatrix()
          inst.setMatrixAt(i, dummy.matrix)
        }
        inst.instanceMatrix.needsUpdate = true
        this.mesh.add(inst)
        // group.add(inst)
      })
      // this.meshesSubstation.push(group)
      // this.sceneWrapper.appCore.rendererCore.scene.add(group)
    } catch (error) {
      console.error('fail to load :', error)
    }
  }

