import * as THREE from 'three'

import { SceneWrapper } from '..'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'

export class Development extends MeshWrapperCommon {
  public mesh: THREE.Mesh
  public scene: THREE.Scene
  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)

    this.scene = sceneWrapper.appCore.rendererCore.scene
    this.init()
  }
  public show(value: boolean) {
    return value
  }
  public init() {
    const geometry = new THREE.BoxGeometry(10, 10, 10)
    const material = new THREE.MeshStandardMaterial({ color: 0x00ff99 })
    this.mesh = new THREE.Mesh(geometry, material)
    this.scene.add(this.mesh)

    this.ready = true
  }
  public update() {
    this.mesh.rotation.x += 0.01
    this.mesh.rotation.y += 0.01

    return true
  }
}
