import { AppHypercube3d, ENVIRONMENT_TYPE } from '..'
import { showGraphDrone, showGraph, showCamera } from './menus/DataViz'
import { UILeftParametric } from './menus/UILeftParametric'
import { UILeftSandbox } from './menus/UILeftSandbox'

export class View {
  public solution: AppHypercube3d

  public uiLeft: UILeftSandbox | UILeftParametric

  public metadataPosition: HTMLDivElement | undefined;
  public fontSize = '11px'

  private divContainer: HTMLDivElement | undefined = undefined
  private divUI: HTMLDivElement | undefined= undefined
  private divUILeft: HTMLDivElement | undefined = undefined
  private divUIRight: HTMLDivElement | undefined = undefined

  private _color = '#333'
  private _width = '150px'
  private _showUI = false

  constructor(solution: AppHypercube3d) {
    this.solution = solution

    this.divContainer = document.createElement('div')
    this.divContainer.style.position = 'absolute'
    // this.divContainer.style.paddingTop = '10px';
    // this.divContainer.style.background = 'rgba(255, 0, 0, 0.1)';
    // this.divContainer.style.width = '500px';
    // this.divContainer.style.height = '500px';
    // this.divContainer.style.pointerEvents = 'none';
    this.solution.RendererCore.host.appendChild(this.divContainer)

    let titleText = 'Hypercube Sandbox'
    if (this.solution.environmentType === ENVIRONMENT_TYPE.Configurator) {
      titleText = 'Parametric Hypercube'
    }
    const divTitle = document.createElement('div')
    divTitle.textContent = titleText
    divTitle.style.fontSize = '34px'
    divTitle.style.fontWeight = '800'
    divTitle.style.width = '100%'
    divTitle.style.height = '100px'
    divTitle.style.position = 'absolute'
    divTitle.style.textAlign = 'center'
    divTitle.style.zIndex = '10'
    divTitle.style.pointerEvents = 'none'
    this.solution.RendererCore.host.appendChild(divTitle)

    this.divUIRight = document.createElement('div')
    this.divUIRight.style.width = '300px'
    this.divUIRight.style.height = '100px'
    this.divUIRight.style.position = 'absolute'
    this.divUIRight.style.top = '55px'
    this.divUIRight.style.right = '5px'
    this.solution.RendererCore.host.appendChild(this.divUIRight)

    const divUI = document.createElement('div')
    this.divUI = divUI
    divUI.style.width = this._width
    divUI.style.marginTop = window.innerWidth < 400 ? '65px' : '0px'
    divUI.style.padding = '5px'
    divUI.style.position = 'absolute'
    divUI.style.zIndex = '10'
    this.divContainer.appendChild(divUI)
    this.solution.RendererCore.renderer.domElement.style.position = 'absolute'

    if (this.solution.environmentType !== ENVIRONMENT_TYPE.Configurator) {
      const divBt = document.createElement('button')
      this.divUI.appendChild(divBt)
      divBt.style.width = this._width
      divBt.textContent = 'Toggle scene'
      divBt.style.fontSize = '11px'
      // divBt.style.background = '#555';
      divBt.style.marginTop = '0px'
      divBt.onclick = () => {
        this.solution.appCore.common.toggleScene()
      }
    }

    const divReady = document.createElement('div')
    this.metadataPosition = divReady
    divReady.textContent = 'INTERNAL USE ONLY © Ready 2025'
    divReady.style.fontSize = '19px'
    divReady.style.width = '100%'
    divReady.style.height = '100px'
    divReady.style.paddingTop = '40px'
    divReady.style.position = 'absolute'
    divReady.style.textAlign = 'center'
    divReady.style.zIndex = '10'
    divReady.style.pointerEvents = 'none'
    this.solution.RendererCore.host.appendChild(divReady)

    const divTitleMeta = document.createElement('div')
    this.metadataPosition = divTitleMeta
    divTitleMeta.textContent = 'Latitude: 30.23, Day: 286, Hour: 14'
    divTitleMeta.style.fontSize = '20px'
    divTitleMeta.style.width = '100%'
    divTitleMeta.style.height = '100px'
    divTitleMeta.style.paddingTop = '70px'
    divTitleMeta.style.position = 'absolute'
    divTitleMeta.style.textAlign = 'center'
    divTitleMeta.style.zIndex = '10'
    divTitleMeta.style.pointerEvents = 'none'
    this.solution.RendererCore.host.appendChild(divTitleMeta)

    let titleTextMenu = 'Controllers'
    if (this.solution.environmentType === ENVIRONMENT_TYPE.Configurator) {
      titleTextMenu = 'Parameters'
    }

    const divUITitle = document.createElement('div')
    this.divUI.appendChild(divUITitle)
    divUITitle.style.width = this._width
    divUITitle.textContent = titleTextMenu
    divUITitle.style.paddingLeft = '10px'
    divUITitle.style.fontSize = '30px'
    divUITitle.style.color = '#222'
    divUITitle.onclick = () => {
      this.toggleController()
    }

    const divUILeft = document.createElement('div')
    this.divUILeft = divUILeft
    divUILeft.style.width = this._width
    divUILeft.style.display = 'none'
    divUILeft.style.padding = '5px'
    // div.style.background = '#fefefe';
    // divUILeft.style.position = 'absolute';
    divUILeft.style.zIndex = '10'
    this.divUI.appendChild(divUILeft)
  }
  public async init() {
    if (
      this.solution.environmentType === ENVIRONMENT_TYPE.Configurator &&
      this.solution.appCore.sceneWrapper.configurator
    ) {
      this.uiLeft = new UILeftParametric(this)
      this.uiLeft.divUILeft = this.divUILeft
    } else {
      this.uiLeft = new UILeftSandbox(this)
      this.uiLeft.divUILeft = this.divUILeft
    }
    this.uiLeft.width = this._width
    this.uiLeft.color = this._color
    this.uiLeft.init()

    this.toggleController()
  }
  public toggleController() {
    this._showUI = !this._showUI
    if (this._showUI) {
      this.divUILeft.style.display = 'block'
    } else {
      this.divUILeft.style.display = 'none'
    }
  }

  public showCamera() {
    showCamera(this.divUIRight)
  }

  public showGraph() {
    showGraph(this.divUIRight)
  }

  public showGraphDrone() {
    showGraphDrone(this.divUIRight)
  }

  public destroy() {
    const elements: (HTMLElement | undefined)[] = [
      this.metadataPosition,
      this.divContainer,
      this.divUI,
      this.divUILeft,
      this.divUIRight
    ]

    for (const el of elements) {
      if (el && el.parentElement) {
        el.parentElement.removeChild(el)
      }
    }
    this.metadataPosition = undefined
    this.divContainer = undefined
    this.divUI = undefined
    this.divUILeft = undefined
    this.divUIRight = undefined
  }
}
