import * as THREE from 'three'

import { Nubbin } from './'
import { NubbinBase } from './Base/NubbinBase'
import { loadFBX, loadFBXWithMat } from '../../../../../utils/ThreeUtils'

interface parmaHeight {
  radiusTop: number
  radiusBottom: number
  height: number
  radialSegments: number
}

export class Disco extends NubbinBase {
  public params: parmaHeight

  public mesh: THREE.Group
  private meshDisco: THREE.Group
  private meshNeck: THREE.Mesh

  constructor(addon: Nubbin) {
    super(addon)
    this.mesh = new THREE.Group()
    this.mesh.name = 'Disco'
    this.mesh.userData = { obj: this }
    this.loadSolarPanel(
      [addon.hypercubeParametric.configurator.BASE_URL + 'DiscoBall.fbx'],
      0.25
    )
  }
  private loadSolarPanel = async (files, scale) => {
    // console.log(files, scale);

    this.params = {
      radiusTop: 1.35,
      radiusBottom: 1.35,
      height: 1,
      radialSegments: 48
    }

    try {
      const loadPromises = files.map((file) =>
        // loadFBX(
        // 	file,
        // 	scale,
        // 	this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.rendererCore.useWebGPU,
        // 	this.addon.hypercubeParametric.configurator.sceneWrapper.appCore.isPerformanceMode,
        // 	this.addon.hypercubeParametric.configurator.materials.clippingPlanes
        // )
        loadFBXWithMat(
          file,
          scale,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .rendererCore.useWebGPU,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .isPerformanceMode,
          this.nubbin.hypercubeParametric.configurator.materials.clippingPlanes,
          this.nubbin.hypercubeParametric.configurator.materials.MaterialClass,
          this.nubbin.hypercubeParametric.configurator.materials.nubbinMaterial
        )
      )

      const fbxModels = await Promise.all(loadPromises)
      fbxModels[0].rotation.z = -Math.PI * 0.5

      this.meshDisco = fbxModels[0]
      this.meshDisco.position.y += 5
      this.mesh.add(this.meshDisco)

      const material =
        this.meshDisco.children[0].children[0].children[0].material

      const geometry = new THREE.CylinderGeometry(
        this.params.radiusTop,
        this.params.radiusBottom,
        this.params.height,
        this.params.radialSegments,
        1
      )
      this.meshNeck = new THREE.Mesh(geometry, material)
      this.meshNeck.castShadow = true
      this.meshNeck.scale.y = this.params.height

      this.meshNeck.position.y =
        this.nubbin.hypercubeParametric.params.height +
        this.nubbin.hypercubeParametric.params.groundY -
        this.nubbin.hypercubeParametric.params.thickness * 0.25 +
        this.nubbin.hypercubeParametric.params.WallUnit.height * 0.5
      this.mesh.add(this.meshNeck)

      this.mesh.userData.onClick = () => this.onClick()

      // this.cylinder.userData.obj = this;
      this.syncSizes()

      this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.add(
        this.mesh
      )
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  public setHight(value: number) {
    this.params.height = value
    this.syncSizes()
  }
  public syncSizes() {
    const wallUnitOffset =
      this.nubbin.hypercubeParametric.params.WallUnit.height

    if (this.mesh) {
      // this.mesh.position.y = this.addon.hypercubeParametric.params.height * 0.5 - this.addon.hypercubeParametric.params.thickness * 0.5;
      this.mesh.position.y =
        this.nubbin.hypercubeParametric.params.height +
        this.nubbin.hypercubeParametric.params.groundY +
        this.params.height
    }

    if (this.meshNeck) {
      this.meshNeck.scale.y = this.params.height + wallUnitOffset

      this.meshNeck.position.y =
        // this.addon.hypercubeParametric.params.height +
        // this.addon.hypercubeParametric.params.groundY +
        // -this.addon.hypercubeParametric.params.thickness * 0.25 - this.addon.hypercubeParametric.params.WallUnit.height * 0.5 -
        -this.params.height * 0.5 - wallUnitOffset
    }
  }
  public toggleVisibility() {
    this.mesh.visible = !this.mesh.visible
  }
  public onClick() {
    this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      this.mesh,
      1.2
    )
    this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.actionStateProcessor.emitAction(
      'discoball@'
    )
  }
  public update(): boolean {
    throw new Error('Method not implemented.')
  }
}
