import * as THREE from 'three'

import { CantileverStarlink } from './CantileverStarlink'
import { degToRad } from '../../../../../utils'

export class StarLink {
  public mesh: THREE.Group | undefined = undefined

  public meshStarLink: THREE.Mesh | undefined = undefined
  public cantilever: CantileverStarlink

  constructor(cantilever: CantileverStarlink) {
    this.cantilever = cantilever
    this.init()
  }
  public init() {
    this.mesh = new THREE.Group()
    this.mesh.name = 'StarLink'
    const width = 3
    const length = width * 1.8
    const height = 0.25
    const geometry = new THREE.BoxGeometry(width, height, length)
    // geometry.translate(0, -height * 0.5, 0)
    // const material = new THREE.MeshStandardMaterial({ color: 0x808080 })
    const box = new THREE.Mesh(
      geometry,
      this.cantilever.nubbin.hypercubeParametric.configurator.materials.skeletonMaterial
    )
    box.castShadow = true
    box.receiveShadow = true
    this.meshStarLink = box

    this.mesh.add(this.meshStarLink)

    this.cantilever.mesh.add(this.mesh)

    const radius = 0.25
    const heightCylinder = 2.0
    const geometryCylinder = new THREE.CylinderGeometry(
      radius,
      radius,
      heightCylinder,
      16
    )
    geometryCylinder.translate(0, -heightCylinder * 0.5, 0)
    const cylinder = new THREE.Mesh(
      geometryCylinder,
      this.cantilever.nubbin.hypercubeParametric.configurator.materials.skeletonMaterial
    )
    this.mesh.add(cylinder)

    this.mesh.userData.onClick = () => this.onClick()

    this.syncSizes()
    this.rotateX(20)
  }
  public update() {
    // Update logic for StarLink can be implemented here
  }
  public rotateX(degree: number) {
    this.meshStarLink.rotation.x = degToRad(degree)
  }
  public rotateY(degree: number) {
    this.mesh.rotation.y = degToRad(degree)
  }
  public syncSizes() {
    if (this.mesh) {
      this.mesh.position.y = this.cantilever.mesh!.position.y + 1.5
      this.mesh.position.x = this.cantilever.mesh!.position.x
      this.mesh.position.z = this.cantilever.mesh!.position.z
    }
  }
  public onClick() {
    this.cantilever.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      this.mesh
    )
    this.cantilever.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.actionStateProcessor.emitAction(
      'starlink@'
    )
  }
}
