import * as THREE from 'three'

import { Asset } from './'
import { attachShaderClippedSection } from '../../utils/ThreeMaterialUtils'

export enum MatType {
  Skeleton = 'skeleton',
  Skin = 'skin',
  Glass = 'glass',
  Wall = 'wall',
  Nubbin = 'nubbin'
}

export class Materials {
  public asset: Asset

  public MaterialClass:
    | typeof THREE.MeshStandardMaterial
    | typeof THREE.MeshPhysicalMaterial
  public normalMap: THREE.Texture

  public materials: (
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
  )[] = []
  public skinMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
    | undefined
  public skeletonMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
    | undefined
  public gridFloorMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
    | undefined
  public wallMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
    | undefined

  public laserBarrelMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
    | undefined
  public nubbinMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
    | undefined

  public aluminumMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
    | undefined

  public glassMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial
    | undefined

  public clippingPlanes = []

  public valueYClipping = 300
  public valueXClipping = 300
  public valueZClipping = 300

  private skinParam: any = {}
  private skeletonParam: any = {}
  private gridFloorParam: any = {}
  private wallParam: any = {}
  private laserBarrelParam: any = {}
  private nubbinParam: any = {}
  private aluminumParam: any = {}
  private glassParam: any = {}

  private clippingProperties = {
    clippingPlanes: this.clippingPlanes,
    transparent: false,
    opacity: 1.0,
    side: THREE.DoubleSide,
    depthWrite: true
  }

  constructor(asset: Asset) {
    this.asset = asset
  }
  public async init() {
    this.clippingPlanes.push(
      new THREE.Plane(new THREE.Vector3(0, -1, 0), this.valueYClipping),
      new THREE.Plane(new THREE.Vector3(-1, 0, 0), this.valueXClipping),
      new THREE.Plane(new THREE.Vector3(0, 0, -1), this.valueZClipping)
    )

    // this.clippingPlanes[1].negate()

    const textureLoader = new THREE.TextureLoader()
    // const normalMapPath = process.env.PUBLIC_URL + '/static/data/model/map/normal-1.jpg';
    let normalMapPath =
      'https://raw.githubusercontent.com/NamjuLee/data/master/map/'

    if (this.asset.appCore.isPerformanceMode) {
      normalMapPath += 'normal-1-small.jpg'
    } else {
      normalMapPath += 'normal-1.jpg'
    }

    this.normalMap = textureLoader.load(normalMapPath, (texture) => {
      texture.wrapS = THREE.RepeatWrapping // THREE.RepeatWrapping;
      texture.wrapT = THREE.RepeatWrapping // THREE.RepeatWrapping;
      texture.repeat.set(10, 10)
    })

    if (this.asset.appCore.rendererCore.useWebGPU) {
      this.normalMap = null
    }

    this.skinParam = {
      color: new THREE.Color(0x828282),
      // color: new THREE.Color(0x828282),
      roughness: 0.2,
      metalness: 0.1,
      normalMap: this.asset.appCore.isPerformanceMode ? null : this.normalMap,
      normalScale: new THREE.Vector2(0.1, 0.1),

      ...this.clippingProperties,

      clearcoat: 0.3,
      clearcoatRoughness: 0.5
    }
    this.skeletonParam = {
      color: new THREE.Color(0xb6b6b6),
      roughness: 0.3, // 0.4 0.7 0.6
      metalness: 0.3, // 0.2 0.1 0.2
      normalMap: this.asset.appCore.isPerformanceMode ? null : this.normalMap,
      normalScale: new THREE.Vector2(0.25, 0.25),

      ...this.clippingProperties,

      clearcoat: 0.3,
      clearcoatRoughness: 0.6
    }

    this.gridFloorParam = {
      color: new THREE.Color(0xc1c1c1),
      roughness: 0.6,
      metalness: 0.2,
      normalMap: this.asset.appCore.isPerformanceMode ? null : this.normalMap,
      normalScale: new THREE.Vector2(0.25, 0.25),

      ...this.clippingProperties,

      clearcoat: 1.0,
      clearcoatRoughness: 0.05
    }

    this.wallParam = {
      color: new THREE.Color(0x2f2f2f),
      roughness: 0.25,
      metalness: 0.4,
      normalMap: this.asset.appCore.isPerformanceMode ? null : this.normalMap,
      normalScale: new THREE.Vector2(0.01, 0.01),

      ...this.clippingProperties,

      clearcoat: 0.3,
      clearcoatRoughness: 0.6
    }

    this.laserBarrelParam = {
      color: new THREE.Color(0x1f1f1f),
      roughness: 0.32,
      metalness: 0.2,
      normalMap: this.asset.appCore.isPerformanceMode ? null : this.normalMap,
      normalScale: new THREE.Vector2(0.01, 0.01),

      ...this.clippingProperties
    }

    this.nubbinParam = {
      ...this.skeletonParam,
      roughness: 0.6, // 0.4 0.7 0.6
      metalness: 0.2, // 0.2 0.1 0.2
      color: new THREE.Color(0xd9d9d9),
      ...this.clippingProperties
    }

    this.glassParam = {
      transparent: true,
      side: THREE.DoubleSide,
      depthWrite: false,
      color: '#000000',
      metalness: 0,
      roughness: 0.05,
      transmission: 0.8,
      thickness: 2.5,
      ior: 1.45,
      reflectivity: 0.8,

      opacity: 0.45,
      envMap: this.asset.appCore.rendererCore.hdriWrapper
        ? this.asset.appCore.rendererCore.hdriWrapper.envMap
        : null,
      clearcoat: 1.0,
      clearcoatRoughness: 0.1,
      envMapIntensity: 0.8,
      clippingPlanes: this.clippingPlanes
    }

    this.aluminumParam = {
      metalness: 1.0,
      roughness: 0.2,
      envMapIntensity: 1.5,
      color: new THREE.Color(0xd9d9d9),
      ...this.clippingProperties
    }

    this.buildMaterials()
  }
  public cloneMaterial(matType: MatType) {
    const MaterialClass =
      this.asset.appCore.rendererCore.useWebGPU ||
      this.asset.appCore.isPerformanceMode
        ? THREE.MeshStandardMaterial
        : THREE.MeshPhysicalMaterial

    switch (matType) {
      case MatType.Skeleton:
        return new MaterialClass({ ...this.skeletonParam })
      case MatType.Skin:
        return new MaterialClass({ ...this.skinParam })
      case MatType.Glass:
        return new MaterialClass({ ...this.glassParam })
      case MatType.Wall:
        return new MaterialClass({ ...this.wallParam })
      case MatType.Nubbin:
        return new MaterialClass({ ...this.nubbinParam })
      default:
        return undefined
    }
  }

  public buildMaterials() {
    const MaterialClass =
      this.asset.appCore.rendererCore.useWebGPU ||
      this.asset.appCore.isPerformanceMode
        ? THREE.MeshStandardMaterial
        : THREE.MeshPhysicalMaterial
    this.MaterialClass = MaterialClass
    this.skinMaterial = new MaterialClass({ ...this.skinParam })
    this.skeletonMaterial = new MaterialClass({ ...this.skeletonParam })

    this.gridFloorMaterial = new MaterialClass({ ...this.gridFloorParam })
    this.wallMaterial = new MaterialClass({ ...this.wallParam })

    this.laserBarrelMaterial = new MaterialClass({ ...this.laserBarrelParam })
    this.nubbinMaterial = new MaterialClass({ ...this.nubbinParam })

    this.aluminumMaterial = new MaterialClass({ ...this.aluminumParam })
    this.glassMaterial = new MaterialClass({ ...this.glassParam })

    this.materialsList = [
      this.skinMaterial,
      this.skeletonMaterial,
      this.gridFloorMaterial,
      this.wallMaterial,
      this.aluminumMaterial,
      this.glassMaterial,
      this.nubbinMaterial
    ]
    this.materials.forEach((mat) => {
      attachShaderClippedSection(mat)
    })
  }
}
