import * as THREE from 'three'

import { HypercubeParametric } from '..'
import {
  createInstancedFBX,
  loadFBXWithMat
} from '../../../../../utils/ThreeUtils'

export class Server {
  public hypercubeParametric: HypercubeParametric

  public mesh: THREE.Group = new THREE.Group()

  private paths: string[] = [
    '/hypercube-asset/model/serverCaseLow.fbx',
    '/hypercube-asset/model/serverDeckLow.fbx'
  ]

  constructor(hypercubeParametric: HypercubeParametric) {
    this.hypercubeParametric = hypercubeParametric

    this.init()
  }
  public init() {
    this.loadModel(this.paths, 0.25)
  }
  private loadModel = async (files: string[], scale: number) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBXWithMat(
          file,
          scale,
          this.hypercubeParametric.configurator.sceneWrapper.appCore
            .rendererCore.useWebGPU,
          this.hypercubeParametric.configurator.sceneWrapper.appCore
            .isPerformanceMode,
          this.hypercubeParametric.configurator.materials.clippingPlanes,
          this.hypercubeParametric.configurator.materials.MaterialClass,
          this.hypercubeParametric.configurator.materials.nubbinMaterial
        )
      )

      const fbxModels = await Promise.all(loadPromises)

      const mesh = new THREE.Group()
      mesh.add(fbxModels[0])

      const serverDecks = createInstancedFBX(fbxModels[1], 6, 10.8)
      serverDecks.scale.setScalar(0.25)
      serverDecks.position.x = 0
      serverDecks.position.y = 5.25
      serverDecks.position.z = -2.75

      mesh.add(serverDecks)

      const yPosition = -17
      const xPosition = -10
      const zPosition = -10
      const offsetZ = 6.8

      mesh.rotation.y = -Math.PI * 0.5
      mesh.position.y = yPosition
      mesh.position.x = xPosition
      mesh.position.z = zPosition

      for (let i = 0; i < 4; ++i) {
        const clonedGroup = mesh.clone(true)
        clonedGroup.name = mesh.name
        clonedGroup.position.set(xPosition, yPosition, zPosition + i * offsetZ)
        this.mesh.add(clonedGroup)

        const clonedGroupOpposite = mesh.clone(true)
        clonedGroupOpposite.name = mesh.name
        clonedGroupOpposite.rotation.y = Math.PI * 0.5
        clonedGroupOpposite.position.set(
          xPosition + 20,
          yPosition,
          zPosition + i * offsetZ
        )

        this.mesh.add(clonedGroupOpposite)
      }
      // this.mesh.visible = false
      this.mesh.castShadow = false
      this.mesh.receiveShadow = false

      this.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh)

      // console.log(this.mesh)
      // this.hideBackServer(true)
      this.mesh.userData.onClick = () => this.onClick()
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  public onClick() {
    // TODO:
  }
  public hideBackSideServer(value: boolean) {
    this.mesh.children.forEach((obj, i) => {
      if (i % 2 === 1) {
        obj.visible = !value
      }
    })
  }
  public show(value: boolean) {
    // console.log(value)
    if (this.mesh) this.mesh.visible = value
  }
}
