import { HypercubeParametric } from '../'
import { CantileverDrone } from './CantileverDrone'
import { CantileverStarlink } from './CantileverStarlink'
import { Cellular } from './Cellular'
import { Disco } from './Disco'
import { DroneDevice } from './DroneDevice'
import { DroneReadyNet } from './DroneReadyNet'
import { LaserDevice } from './LaserDevice'
import { PAPanel } from './PAPanel'

export class Nubbin {
  public hypercubeParametric: HypercubeParametric

  public panel!: PAPanel | undefined
  public cellular: Cellular | undefined
  public disco: Disco | undefined

  public droneDevice: DroneDevice | undefined
  public laserDevice: LaserDevice | undefined

  public cantileverStarlink: CantileverStarlink | undefined

  public droneReadyNet: DroneReadyNet | undefined
  public cantileverDrone: CantileverDrone | undefined

  constructor(hypercubeParametric: HypercubeParametric) {
    this.hypercubeParametric = hypercubeParametric

    this.init()
  }
  public init() {
    // console.log('Initializing Addons...')
    this.panel = new PAPanel(this)
    this.cellular = new Cellular(this)
    this.disco = new Disco(this)

    this.droneDevice = new DroneDevice(this)
    this.laserDevice = new LaserDevice(this)

    this.cantileverStarlink = new CantileverStarlink(this)

    this.droneReadyNet = new DroneReadyNet(this)

    this.cantileverDrone = new CantileverDrone(this)
  }
  public syncSizes() {
    this.disco?.syncSizes()
    this.cellular?.syncSizes()

    this.droneDevice?.syncSizes()
    this.laserDevice?.syncSizes()

    this.cantileverStarlink?.syncSizes()
  }
  public toggleVisibility() {
    this.disco?.toggleVisibility()

    this.droneDevice?.toggleVisibility()
    this.laserDevice?.toggleVisibility()

    this.cantileverStarlink?.toggleVisibility()
  }
  public show(show: boolean) {
    this.panel?.show(show)
    this.cellular?.show(show)
    this.disco?.show(show)
    this.droneDevice?.show(show)
    this.laserDevice?.show(show)
    this.cantileverStarlink?.show(show)
    this.droneReadyNet?.show(show)
    this.cantileverDrone?.show(show)
  }
  public update() {
    const results = [
      this.cantileverDrone,
      this.laserDevice,
      this.droneReadyNet
    ].map((obj) => obj?.update() ?? false)

    return results.some(Boolean)
  }
}
