import * as THREE from 'three'
import { OrbitControls } from 'three-orbitcontrols-ts'

import { SceneWrapper } from '..'
import { CLICK_TYPE } from '../../../utils/const'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'

export class HypercubeArranger extends MeshWrapperCommon {
  public t: number = 0.0
  public camera: THREE.PerspectiveCamera
  public scene: THREE.Scene
  public renderer: THREE.WebGLRenderer
  public controls: OrbitControls

  public gridSize = 10
  public cellSize = 1
  public groundPlane: THREE.Mesh

  public isDragging = false
  public dragStart: { x: number; z: number } | null = null
  public dragEnd: { x: number; z: number } | null = null
  public boxes = new Map() // key: "x,z", value: {mesh, height}

  public selectedBox: THREE.Group | null = null
  public dragStartY = 0
  public initialHeight = 0
  public raycaster = new THREE.Raycaster()
  public mouse = new THREE.Vector2()
  public hoverBox: THREE.Mesh | null = null
  public hoveredGridCell: { x: number; z: number } | null = null
  public dragPreviewBoxes: THREE.Mesh[] = []
  public dragPath: { x: number; z: number }[] = []
  private isTopView = false
  private clickedOnBox = false

  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)

    this.scene = this.sceneWrapper.scene
    this.camera = this.sceneWrapper.appCore.rendererCore.cameraWrapper.camera
    this.renderer = this.sceneWrapper.appCore.rendererCore.renderer
    this.controls =
      this.sceneWrapper.appCore.rendererCore.cameraWrapper.controls

    this.sceneWrapper.appCore.rendererCore.eventWrapper.mouseEventArray.push(
      this.eventListener
    )

    this.init()

    this.ready = true

    setTimeout(() => {
      this.sceneWrapper.appCore.common.commonServiceMode.toggleShadow()
      this.toggleView()
    }, 200)
  }

  public eventListener = (e: MouseEvent, type: CLICK_TYPE) => {
    // Safety check
    if (!this.sceneWrapper?.appCore?.common) {
      return
    }

    this.sceneWrapper.appCore.common.renderForce()

    this.getMousePosition(e)
    this.raycaster.setFromCamera(this.mouse, this.camera)

    switch (type) {
      case CLICK_TYPE.DOWN:
        this.handleMouseDown(e)
        break
      case CLICK_TYPE.MOVE:
      case CLICK_TYPE.DRAG:
        this.handleMouseMove(e)
        break
      case CLICK_TYPE.UP:
        this.handleMouseUp(e)
        break
      case CLICK_TYPE.LEFT:
        this.handleClick(e)
        break
      default:
        break
    }
  }

  public init() {
    const gridHelper = new THREE.GridHelper(
      this.gridSize,
      this.gridSize,
      0x444444,
      0x222222
    )
    this.scene.add(gridHelper)

    // Ground plane for raycasting
    const groundGeometry = new THREE.PlaneGeometry(this.gridSize, this.gridSize)
    const groundMaterial = new THREE.MeshBasicMaterial({
      visible: false,
      side: THREE.DoubleSide
    })
    this.groundPlane = new THREE.Mesh(groundGeometry, groundMaterial)
    this.groundPlane.rotation.x = -Math.PI / 2
    this.groundPlane.name = 'ground'
    this.scene.add(this.groundPlane)

    const blacklisted: number[][] = []
    for (let i = 0; i < 4; i++) {
      for (let j = 2; j < 4; j++) {
        blacklisted.push([i, j])
      }
    }
    this.setBlacklistedCells(blacklisted)
  }

  public setBlacklistedCells(cells: [number, number][]) {
    // Safety check - ensure blacklistedCells is initialized
    if (!this.blacklistedCells) {
      this.blacklistedCells = new Set()
    }
    if (!this.blacklistMarkers) {
      this.blacklistMarkers = []
    }

    // Clear existing blacklist
    this.blacklistedCells.clear()
    this.clearBlacklistMarkers()

    // Add new blacklisted cells
    cells.forEach(([x, z]) => {
      const key = `${x},${z}`
      this.blacklistedCells.add(key)
      this.createBlacklistMarker(x, z)
    })
  }

  private createBlacklistMarker(x: number, z: number) {
    const geometry = new THREE.BoxGeometry(
      this.cellSize * 0.98,
      0.05,
      this.cellSize * 0.98
    )
    const material = new THREE.MeshBasicMaterial({
      color: 0x000000,
      transparent: true,
      opacity: 0.7
    })
    const marker = new THREE.Mesh(geometry, material)

    const worldX = x - this.gridSize / 2 + 0.5
    const worldZ = z - this.gridSize / 2 + 0.5

    marker.position.set(worldX, 0.03, worldZ)
    marker.userData.isBlacklistMarker = true

    this.scene.add(marker)
    this.blacklistMarkers.push(marker)
  }

  private clearBlacklistMarkers() {
    if (!this.blacklistMarkers) {
      this.blacklistMarkers = []
      return
    }

    this.blacklistMarkers.forEach((marker) => {
      this.scene.remove(marker)
      marker.geometry.dispose()
      ;(marker.material as THREE.Material).dispose()
    })
    this.blacklistMarkers = []
  }

  private isBlacklisted(x: number, z: number): boolean {
    if (!this.blacklistedCells) {
      return false
    }
    const key = `${x},${z}`
    return this.blacklistedCells.has(key)
  }

  public toggleView() {
    this.sceneWrapper.appCore.common.renderForce()
    this.isTopView = !this.isTopView

    if (this.isTopView) {
      // Top view
      this.camera.position.set(0, 50, 0)
      this.camera.setFocalLength(100)
      this.camera.lookAt(0, 0, 0)

      if (this.controls) {
        this.controls.enabled = false
      }
    } else {
      // Perspective view
      this.camera.position.set(-8, 8, 8)
      this.camera.lookAt(0, 0, 0)
      this.camera.setFocalLength(28)

      if (this.controls) {
        this.controls.enabled = true
      }
    }
  }

  private createHoverBox(x: number, z: number) {
    if (this.hoverBox) {
      this.scene.remove(this.hoverBox)
      this.hoverBox.geometry.dispose()
      ;(this.hoverBox.material as THREE.Material).dispose()
    }

    const geometry = new THREE.BoxGeometry(
      this.cellSize * 0.98,
      0.1,
      this.cellSize * 0.98
    )
    const material = new THREE.MeshBasicMaterial({
      color: 0x00ff00,
      transparent: true,
      opacity: 0.3
    })
    this.hoverBox = new THREE.Mesh(geometry, material)

    const worldX = x - this.gridSize / 2 + 0.5
    const worldZ = z - this.gridSize / 2 + 0.5

    this.hoverBox.position.set(worldX, 0.05, worldZ)
    this.scene.add(this.hoverBox)
  }

  private removeHoverBox() {
    if (this.hoverBox) {
      this.scene.remove(this.hoverBox)
      this.hoverBox.geometry.dispose()
      ;(this.hoverBox.material as THREE.Material).dispose()
      this.hoverBox = null
    }
    this.hoveredGridCell = null
  }

  private getMousePosition(event: MouseEvent) {
    const rect = this.renderer.domElement.getBoundingClientRect()
    this.mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
    this.mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1
  }

  private getGridPosition(point: THREE.Vector3) {
    const x = Math.floor(point.x + this.gridSize / 2)
    const z = Math.floor(point.z + this.gridSize / 2)
    return { x, z }
  }

  private createBox(x: number, z: number, height = 1) {
    const key = `${x},${z}`

    if (this.boxes.has(key)) {
      return this.boxes.get(key)
    }

    const boxGroup = new THREE.Group()
    const frameThickness = 0.08
    const cellSize = this.cellSize * 0.98

    const frameMaterial = new THREE.MeshStandardMaterial({
      color: 0xfafafa,
      roughness: 0.5,
      metalness: 0.2
    })

    // Bottom frame (4 edges)
    const bottomEdges = [
      {
        size: [cellSize, frameThickness, frameThickness],
        pos: [0, frameThickness / 2, cellSize / 2 - frameThickness / 2]
      },
      {
        size: [cellSize, frameThickness, frameThickness],
        pos: [0, frameThickness / 2, -cellSize / 2 + frameThickness / 2]
      },
      {
        size: [frameThickness, frameThickness, cellSize - frameThickness * 2],
        pos: [cellSize / 2 - frameThickness / 2, frameThickness / 2, 0]
      },
      {
        size: [frameThickness, frameThickness, cellSize - frameThickness * 2],
        pos: [-cellSize / 2 + frameThickness / 2, frameThickness / 2, 0]
      }
    ]

    // Top frame (4 edges)
    const topEdges = [
      {
        size: [cellSize, frameThickness, frameThickness],
        pos: [0, height - frameThickness / 2, cellSize / 2 - frameThickness / 2]
      },
      {
        size: [cellSize, frameThickness, frameThickness],
        pos: [
          0,
          height - frameThickness / 2,
          -cellSize / 2 + frameThickness / 2
        ]
      },
      {
        size: [frameThickness, frameThickness, cellSize - frameThickness * 2],
        pos: [cellSize / 2 - frameThickness / 2, height - frameThickness / 2, 0]
      },
      {
        size: [frameThickness, frameThickness, cellSize - frameThickness * 2],
        pos: [
          -cellSize / 2 + frameThickness / 2,
          height - frameThickness / 2,
          0
        ]
      }
    ]

    // Vertical edges (4 corners)
    const verticalEdges = [
      {
        size: [frameThickness, height - frameThickness * 2, frameThickness],
        pos: [
          cellSize / 2 - frameThickness / 2,
          height / 2,
          cellSize / 2 - frameThickness / 2
        ]
      },
      {
        size: [frameThickness, height - frameThickness * 2, frameThickness],
        pos: [
          -cellSize / 2 + frameThickness / 2,
          height / 2,
          cellSize / 2 - frameThickness / 2
        ]
      },
      {
        size: [frameThickness, height - frameThickness * 2, frameThickness],
        pos: [
          cellSize / 2 - frameThickness / 2,
          height / 2,
          -cellSize / 2 + frameThickness / 2
        ]
      },
      {
        size: [frameThickness, height - frameThickness * 2, frameThickness],
        pos: [
          -cellSize / 2 + frameThickness / 2,
          height / 2,
          -cellSize / 2 + frameThickness / 2
        ]
      }
    ]

    // Create all frame pieces
    ;[...bottomEdges, ...topEdges, ...verticalEdges].forEach((edge) => {
      const geometry = new THREE.BoxGeometry(
        edge.size[0],
        edge.size[1],
        edge.size[2]
      )
      const mesh = new THREE.Mesh(geometry, frameMaterial)
      mesh.position.set(edge.pos[0], edge.pos[1], edge.pos[2])
      mesh.castShadow = true
      mesh.receiveShadow = true
      boxGroup.add(mesh)
    })

    // Create inner walls (6 walls including top and bottom)
    const wallThickness = 0.05
    const innerSize = cellSize - frameThickness * 2
    const wallHeight = height - frameThickness * 2

    const wallMaterial = new THREE.MeshStandardMaterial({
      color: 0xa3a3a3,
      roughness: 0.6,
      metalness: 0.1,
      side: THREE.DoubleSide
    })

    const walls = [
      // Side walls
      {
        size: [innerSize, wallHeight, wallThickness],
        pos: [0, height / 2, innerSize / 2]
      },
      {
        size: [innerSize, wallHeight, wallThickness],
        pos: [0, height / 2, -innerSize / 2]
      },
      {
        size: [wallThickness, wallHeight, innerSize],
        pos: [innerSize / 2, height / 2, 0]
      },
      {
        size: [wallThickness, wallHeight, innerSize],
        pos: [-innerSize / 2, height / 2, 0]
      },
      // Top and bottom walls
      {
        size: [innerSize, wallThickness, innerSize],
        pos: [0, height - frameThickness - wallThickness / 2, 0]
      },
      {
        size: [innerSize, wallThickness, innerSize],
        pos: [0, frameThickness + wallThickness / 2, 0]
      }
    ]

    walls.forEach((wall) => {
      const geometry = new THREE.BoxGeometry(
        wall.size[0],
        wall.size[1],
        wall.size[2]
      )
      const mesh = new THREE.Mesh(geometry, wallMaterial)
      mesh.position.set(wall.pos[0], wall.pos[1], wall.pos[2])
      mesh.castShadow = true
      mesh.receiveShadow = true
      boxGroup.add(mesh)
    })

    // Position the entire group
    const worldX = x - this.gridSize / 2 + 0.5
    const worldZ = z - this.gridSize / 2 + 0.5
    boxGroup.position.set(worldX, 0, worldZ)
    boxGroup.userData = { gridX: x, gridZ: z, key }

    this.scene.add(boxGroup)
    this.boxes.set(key, { mesh: boxGroup, height })

    return { mesh: boxGroup, height }
  }

  private updateBoxHeight(key: string, newHeight: number) {
    if (!this.boxes.has(key)) return

    const boxData = this.boxes.get(key)
    const { mesh } = boxData

    if (newHeight <= 0) {
      this.scene.remove(mesh)
      mesh.children.forEach((child: THREE.Mesh) => {
        child.geometry.dispose()
        if (Array.isArray(child.material)) {
          child.material.forEach((mat) => mat.dispose())
        } else {
          child.material.dispose()
        }
      })
      this.boxes.delete(key)
      return
    }

    // Remove old group
    this.scene.remove(mesh)
    mesh.children.forEach((child: THREE.Mesh) => {
      child.geometry.dispose()
      if (Array.isArray(child.material)) {
        child.material.forEach((mat) => mat.dispose())
      } else {
        child.material.dispose()
      }
    })

    // Create new box with updated height
    const gridX = mesh.userData.gridX
    const gridZ = mesh.userData.gridZ
    this.boxes.delete(key)
    this.createBox(gridX, gridZ, newHeight)
  }

  private createDragPreview(cells: { x: number; z: number }[]) {
    // Remove existing preview boxes
    this.removeDragPreview()

    this.dragPreviewBoxes = []

    cells.forEach((cell) => {
      const key = `${cell.x},${cell.z}`
      // Don't show preview on blacklisted cells
      if (!this.boxes.has(key) && !this.isBlacklisted(cell.x, cell.z)) {
        const geometry = new THREE.BoxGeometry(
          this.cellSize * 0.98,
          0.1,
          this.cellSize * 0.98
        )
        const material = new THREE.MeshBasicMaterial({
          color: 0x00ff00,
          transparent: true,
          opacity: 0.4
        })
        const mesh = new THREE.Mesh(geometry, material)

        const worldX = cell.x - this.gridSize / 2 + 0.5
        const worldZ = cell.z - this.gridSize / 2 + 0.5

        mesh.position.set(worldX, 0.05, worldZ)
        this.scene.add(mesh)
        this.dragPreviewBoxes.push(mesh)
      }
    })
  }

  private removeDragPreview() {
    if (this.dragPreviewBoxes) {
      this.dragPreviewBoxes.forEach((mesh) => {
        this.scene.remove(mesh)
        mesh.geometry.dispose()
        ;(mesh.material as THREE.Material).dispose()
      })
      this.dragPreviewBoxes = []
    }
  }

  private addToDragPath(gridPos: { x: number; z: number }) {
    // Don't add blacklisted cells to drag path
    if (this.isBlacklisted(gridPos.x, gridPos.z)) {
      return
    }

    // Check if this cell is already in the path
    const exists = this.dragPath.some(
      (cell) => cell.x === gridPos.x && cell.z === gridPos.z
    )
    if (!exists) {
      this.dragPath.push(gridPos)
    }
  }

  private handleMouseDown(event: MouseEvent) {
    this.clickedOnBox = false // Reset flag

    if (this.isTopView) {
      // In top view, only allow drawing
      if (event.button === 0) {
        const groundIntersects = this.raycaster.intersectObject(
          this.groundPlane
        )

        if (groundIntersects.length > 0) {
          const point = groundIntersects[0].point
          const gridPos = this.getGridPosition(point)

          if (
            gridPos.x >= 0 &&
            gridPos.x < this.gridSize &&
            gridPos.z >= 0 &&
            gridPos.z < this.gridSize
          ) {
            const key = `${gridPos.x},${gridPos.z}`
            if (!this.boxes.has(key)) {
              this.isDragging = true
              this.dragStart = gridPos
              this.dragPath = [gridPos]
              this.createDragPreview(this.dragPath)
            }
          }
        }
      }
      return
    }

    // Perspective view behavior - only height adjustment and deletion
    const boxMeshes = Array.from(this.boxes.values()).map((b: any) => b.mesh)
    const boxIntersects = this.raycaster.intersectObjects(boxMeshes, true)

    if (boxIntersects.length > 0) {
      this.clickedOnBox = true // Mark that we clicked on a box

      if (event.button === 2) {
        // Right click - height adjustment
        let parentGroup: any = boxIntersects[0].object
        while (parentGroup.parent && !parentGroup.userData.key) {
          parentGroup = parentGroup.parent
        }

        this.selectedBox = parentGroup
        this.isDragging = true
        this.dragStartY = event.clientY
        this.initialHeight = this.boxes.get(
          this.selectedBox.userData.key
        ).height
        this.renderer.domElement.style.cursor = 'ns-resize'
      }
      return
    }
  }

  private handleMouseMove(event: MouseEvent) {
    if (this.isDragging) {
      if (this.selectedBox) {
        // Adjust height
        const deltaY = this.dragStartY - event.clientY
        const heightChange = deltaY * 0.01
        const newHeight = Math.max(0.1, this.initialHeight + heightChange)

        this.updateBoxHeight(this.selectedBox.userData.key, newHeight)
        return
      }

      if (this.isTopView) {
        const intersects = this.raycaster.intersectObject(this.groundPlane)

        if (intersects.length > 0) {
          const point = intersects[0].point
          const gridPos = this.getGridPosition(point)

          if (
            gridPos.x >= 0 &&
            gridPos.x < this.gridSize &&
            gridPos.z >= 0 &&
            gridPos.z < this.gridSize
          ) {
            this.addToDragPath(gridPos)
            this.createDragPreview(this.dragPath)
          }
        }
      }
      return
    }

    const boxMeshes = Array.from(this.boxes.values()).map((b: any) => b.mesh)
    const boxIntersects = this.raycaster.intersectObjects(boxMeshes, true)

    if (boxIntersects.length > 0) {
      let parentGroup: any = boxIntersects[0].object
      while (parentGroup.parent && !parentGroup.userData.key) {
        parentGroup = parentGroup.parent
      }

      this.removeHoverBox()
      this.renderer.domElement.style.cursor = 'pointer'

      parentGroup.children.forEach((child: THREE.Mesh) => {
        if (child.material && 'emissive' in child.material) {
          ;(child.material as THREE.MeshStandardMaterial).emissive.setHex(
            0x555555
          )
        }
      })

      boxMeshes.forEach((mesh: THREE.Group) => {
        if (mesh !== parentGroup) {
          mesh.children.forEach((child: THREE.Mesh) => {
            if (child.material && 'emissive' in child.material) {
              ;(child.material as THREE.MeshStandardMaterial).emissive.setHex(
                0x000000
              )
            }
          })
        }
      })
    } else {
      boxMeshes.forEach((mesh: THREE.Group) => {
        mesh.children.forEach((child: THREE.Mesh) => {
          if (child.material && 'emissive' in child.material) {
            ;(child.material as THREE.MeshStandardMaterial).emissive.setHex(
              0x000000
            )
          }
        })
      })

      if (this.isTopView) {
        const groundIntersects = this.raycaster.intersectObject(
          this.groundPlane
        )

        if (groundIntersects.length > 0) {
          const point = groundIntersects[0].point
          const gridPos = this.getGridPosition(point)

          if (
            gridPos.x >= 0 &&
            gridPos.x < this.gridSize &&
            gridPos.z >= 0 &&
            gridPos.z < this.gridSize
          ) {
            const key = `${gridPos.x},${gridPos.z}`
            if (!this.boxes.has(key)) {
              if (this.isBlacklisted(gridPos.x, gridPos.z)) {
                this.removeHoverBox()
                this.renderer.domElement.style.cursor = 'not-allowed'
              } else {
                // Show hover on empty cell
                if (
                  !this.hoveredGridCell ||
                  this.hoveredGridCell.x !== gridPos.x ||
                  this.hoveredGridCell.z !== gridPos.z
                ) {
                  this.hoveredGridCell = gridPos
                  this.createHoverBox(gridPos.x, gridPos.z)
                }
                this.renderer.domElement.style.cursor = 'crosshair'
              }
            } else {
              this.removeHoverBox()
              this.renderer.domElement.style.cursor = 'pointer'
            }
          } else {
            this.removeHoverBox()
            this.renderer.domElement.style.cursor = 'default'
          }
        } else {
          this.removeHoverBox()
          this.renderer.domElement.style.cursor = 'default'
        }
      } else {
        this.removeHoverBox()
        this.renderer.domElement.style.cursor = 'default'
      }
    }
  }

  private handleClick(event: MouseEvent) {
    if (!this.clickedOnBox) return

    const boxMeshes = Array.from(this.boxes.values()).map((b: any) => b.mesh)
    const boxIntersects = this.raycaster.intersectObjects(boxMeshes, true)

    if (boxIntersects.length > 0) {
      // Find the parent group
      let parentGroup: any = boxIntersects[0].object
      while (parentGroup.parent && !parentGroup.userData.key) {
        parentGroup = parentGroup.parent
      }

      const key = parentGroup.userData.key

      this.scene.remove(parentGroup)
      parentGroup.children.forEach((child: THREE.Mesh) => {
        child.geometry.dispose()
        if (Array.isArray(child.material)) {
          child.material.forEach((mat) => mat.dispose())
        } else {
          child.material.dispose()
        }
      })
      this.boxes.delete(key)
    }

    this.clickedOnBox = false
  }

  private handleMouseUp(event: MouseEvent) {
    if (!this.isDragging) return

    if (this.selectedBox) {
      this.selectedBox = null
      this.renderer.domElement.style.cursor = 'default'
    } else if (this.dragPath.length > 0 && !this.clickedOnBox) {
      this.dragPath.forEach((cell) => {
        this.createBox(cell.x, cell.z)
      })

      // Remove drag preview
      this.removeDragPreview()
      this.dragPath = []
    }

    this.isDragging = false
    this.dragStart = null
  }

  public destroy() {
    this.removeHoverBox()
    this.removeDragPreview()

    this.boxes.forEach(({ mesh }: any) => {
      if (mesh.children) {
        mesh.children.forEach((child: THREE.Mesh) => {
          child.geometry.dispose()
          if (Array.isArray(child.material)) {
            child.material.forEach((mat) => mat.dispose())
          } else {
            child.material.dispose()
          }
        })
      }
      this.scene.remove(mesh)
    })
  }

  public update() {
    return false
  }

  public show(value: boolean) {
    // this._visible = value
  }
}
