import { AppCore } from '..'
import { AppCommon } from '../AppCommon'

export class ActionStateProcessor {
  public appCore: AppCore
  private common: AppCommon
  constructor(appCore: AppCore) {
    this.appCore = appCore
    this.common = appCore.common
  }
  public emitAction(v: string) {
    this.appCore.app.emitAction(v)
  }
  public pushAction(v: string) {
    // console.log('ActionProcessor', v)
    return this.actionProcessing(v.split('@'))
  }
  public actionProcessing(params: string[]) {
    // const value = 0
    switch (params[0]) {
      //.................... Hypercube view
      case `viewPrevious`:
        return this.common.viewChangingBackward()
      case `viewNext`:
        return this.common.viewChangingForward()
      case `expandingDiscoball`:
        return this.common.setHeightDiscoBall(+params[1] * 0.1)
      case `setDegreePAPanel`:
        return this.common.setRadianPAPanel(+params[1] * 0.1)
      case `setDegreeStarlink`:
        return this.common.setDegreeStarlink(+params[1])
      case `activateDroneNest`:
        return this.common.commonServiceMode.toggleActivateDroneNest()
      case `toggleAssemblyDisassemblyHC`:
        return this.common.commonServiceMode.toggleAssemblyDisassemblyHC()
      //....................
      case 'shiftEnv':
        return this.common.commonServiceMode.shiftEnv(params[1])

      //....................
      case 'toggleTheme':
        return this.common.commonServiceMode.toggleTheme()
      case `toggleXRay`:
        return this.common.commonServiceMode.toggleXray()
      case `sliderXRay`:
        return this.common.commonServiceMode.sliderXRayView(+params[1] * 0.01)
      case `toggleXRayHypercubeSkin`:
        return this.common.commonServiceMode.toggleXRayHypercubeSkin()
      case `toggleXRayCoolingHC`:
        return this.common.commonServiceMode.toggleXRayCoolingHC()
      case `toggleXRayInnerCooling`:
        return this.common.commonServiceMode.toggleXRayInnerCooling()

      case `toggleShadow`:
        return this.common.commonServiceMode.toggleShadow()
      case `toggleOpenDoor`:
        return this.common.commonServiceMode.toggleOpenDoorMain()
      case `toggleHDRI`:
        return this.common.hdriChanging()
      case `logCamera`:
        return this.common.printCameraInfo()

      case `backToHypercubeView`:
        return this.common.commonServiceMode.backToHypercubeView()
      case `cutHypercubeX`:
        return this.common.commonServiceMode.cutHypercubeX()
      case `cutHypercubeY`:
        return this.common.commonServiceMode.cutHypercubeY()

      //....................
      case `showInnerCooling`:
        return this.common.commonServiceMode.toggleInnerCooling()

      //....................
      case `setFOV`:
        return this.common.commonServiceMode.setFOV(+params[1])

      case `sliderSectionX`:
        return this.common.commandHypercubeParametric.setClippingXParametricHC(
          +params[1]
        )
      case `sliderSectionY`:
        return this.common.commandHypercubeParametric.setClippingYParametricHC(
          +params[1]
        )
      case `sliderSectionZ`:
        return this.common.commandHypercubeParametric.setClippingZParametricHC(
          +params[1]
        )
      case `setLatSunVec`:
        return this.common.commonServiceMode.setLatSunVec(+params[1])
      case `setLonSunVec`:
        return this.common.commonServiceMode.setLonSunVec(+params[1])
      case `setHourSunVec`:
        return this.common.commonServiceMode.setHourSunVec(+params[1])
      case 'setAutoLocalTime':
        return this.common.commonServiceMode.setAutoLocalTime()

      case 'toggleViewArranger':
        return this.common.commonServiceMode.toggleViewArranger()

      //.................... parametric
      case `toggleGizmo`:
        return this.common.commandHypercubeParametric.toggleGizmo()
      case `setWidthParametricHC`:
        return this.common.commandHypercubeParametric.setWidthParametricHC(
          +params[1]
        )

      case `setLengthParametricHC`:
        return this.common.commandHypercubeParametric.setLengthParametricHC(
          +params[1]
        )
      case `setHeightParametricHC`:
        return this.common.commandHypercubeParametric.setHeightParametricHC(
          +params[1]
        )
      case `setVolumeOptimization`:
        return this.common.commandHypercubeParametric.setVolumeOptimization(
          +params[1]
        )
      // case `setSizeGapRollingPanel`:
      //   value = +params[1] * 0.1
      //   return this.common.commandHypercubeParametric.setSizeGapRollingPanel(
      //     value
      //   )
      // case `setSizeCameraHC`:
      //   value = +params[1] * 0.01
      //   return this.common.commandHypercubeParametric.setSizeCameraHC(value)
      // case `setSizeSkeletonParametricHC`:
      //   return this.common.commandHypercubeParametric.setSizeSkeletonParametricHC(
      //     +params[1]
      //   )

      default:
        return false
    }
  }
}
