import { AppHypercube3d, ENVIRONMENT_TYPE } from './AppHypercube3d';

export class Solution {
	public divHost: HTMLDivElement;

	public app: AppHypercube3d;

	constructor(id: string, param: ENVIRONMENT_TYPE) {
		// console.log(param);
		this.init(id, param.env);
	}
	public async init(id: string, env: ENVIRONMENT_TYPE) {
		this.app = await AppHypercube3d.init({
			divID: id,
			environmentType: env,
			productionMode: false,
			debuggerMode: true,
		});
	}
	public destroy() {
		this.app.destroy();
	}
}
