import * as THREE from 'three'

export const generatePlanarUV = (geometry: THREE.BufferGeometry) => {
  const pos = geometry.attributes.position
  const uvs = []

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i)
    const y = pos.getY(i)

    const u = (x + 50) / 100
    const v = (y + 50) / 100

    uvs.push(u, v)
  }

  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2))
}

export const generateBoxUV = (geometry: THREE.BufferGeometry) => {
  const pos = geometry.attributes.position
  const uvs = []

  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i)
    const y = pos.getY(i)
    const z = pos.getZ(i)

    const ax = Math.abs(x)
    const ay = Math.abs(y)
    const az = Math.abs(z)

    let u = 0,
      v = 0

    if (ax >= ay && ax >= az) {
      u = z
      v = y
    } else if (ay >= ax && ay >= az) {
      u = x
      v = z
    } else {
      u = x
      v = y
    }

    uvs.push((u + 50) / 100)
    uvs.push((v + 50) / 100)
  }

  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2))
}

export const attachShaderClippedSection = (
  material: THREE.Material,
  r = 0,
  g = 0,
  b = 0
) => {
  // @ts-ignore
  material.onBeforeCompile = (shader: THREE.Shader) => {
    shader.uniforms.clippedSectionColor = { value: new THREE.Vector3(r, g, b) }
    shader.fragmentShader =
      `
			uniform vec3 clippedSectionColor;
			` + shader.fragmentShader

    shader.fragmentShader = shader.fragmentShader.replace(
      '#include <opaque_fragment>',
      `
			if (gl_FrontFacing == false) {
			outgoingLight = clippedSectionColor; // Set clipped section to black
			}
			#include <opaque_fragment>
			`
    )
    // console.log('Modified Fragment Shader:', shader.fragmentShader);
  }
  return material
}
