import * as THREE from 'three'

import { Hypercube } from '..'
import { attachShaderClippedSection } from '../../../../utils/ThreeMaterialUtils'
export class HypercubeMaterials {
  public hypercube: Hypercube

  public normalMap: THREE.Texture

  public skinMaterial: THREE.MeshPhysicalMaterial | THREE.MeshStandardMaterial
  public skeletonMaterial:
    | THREE.MeshPhysicalMaterial
    | THREE.MeshStandardMaterial

  constructor(hypercube: Hypercube) {
    this.hypercube = hypercube
    this.init()
  }
  public init() {
    const textureLoader = new THREE.TextureLoader()
    // const normalMapPath = process.env.PUBLIC_URL + '/static/data/model/map/normal-1.jpg';
    let normalMapPath =
      'https://raw.githubusercontent.com/NamjuLee/data/master/map/'

    if (this.hypercube.sceneWrapper.appCore.isPerformanceMode) {
      normalMapPath += 'normal-1-small.jpg'
    } else {
      normalMapPath += 'normal-1.jpg'
    }

    this.normalMap = textureLoader.load(normalMapPath, (texture) => {
      texture.wrapS = THREE.RepeatWrapping
      texture.wrapT = THREE.RepeatWrapping
      texture.repeat.set(1, 1)
    })

    if (this.hypercube.sceneWrapper.appCore.rendererCore.useWebGPU) {
      this.normalMap = null
    }

    if (
      this.hypercube.sceneWrapper.appCore.rendererCore.useWebGPU ||
      this.hypercube.sceneWrapper.appCore.isPerformanceMode
    ) {
      this.skinMaterial = new THREE.MeshStandardMaterial({
        color: new THREE.Color(0x828282),
        roughness: 0.2,
        metalness: 0.1,
        normalMap: this.hypercube.sceneWrapper.appCore.isPerformanceMode
          ? null
          : this.normalMap,
        normalScale: new THREE.Vector2(0.1, 0.1),
        side: THREE.DoubleSide,

        clippingPlanes: this.hypercube.clippingPlanes,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 1,
        stencilZPass: THREE.ReplaceStencilOp
      })

      this.skeletonMaterial = new THREE.MeshStandardMaterial({
        color: new THREE.Color(0xb6b6b6),
        roughness: 0.1,
        metalness: 0.2,
        normalMap: this.hypercube.sceneWrapper.appCore.isPerformanceMode
          ? null
          : this.normalMap,
        normalScale: new THREE.Vector2(0.1, 0.1),
        side: THREE.DoubleSide,

        clippingPlanes: this.hypercube.clippingPlanes,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 1,
        stencilZPass: THREE.ReplaceStencilOp
      })
    } else {
      this.skinMaterial = new THREE.MeshPhysicalMaterial({
        color: new THREE.Color(0x828282), // 0xa2a2a2
        roughness: 0.2,
        metalness: 0.1,
        clearcoat: 0.3,
        clearcoatRoughness: 0.5,
        normalMap: this.normalMap,
        normalScale: new THREE.Vector2(0.1, 0.1),
        side: THREE.DoubleSide,

        clippingPlanes: this.hypercube.clippingPlanes,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 1,
        stencilZPass: THREE.ReplaceStencilOp
      })

      this.skeletonMaterial = new THREE.MeshPhysicalMaterial({
        color: new THREE.Color(0xb6b6b6), // 0xe1e1e1
        roughness: 0.1,
        metalness: 0.2,
        clearcoat: 1.0,
        clearcoatRoughness: 0.05,
        normalMap: this.normalMap,
        normalScale: new THREE.Vector2(0.25, 0.25),
        side: THREE.DoubleSide,

        clippingPlanes: this.hypercube.clippingPlanes,
        stencilWrite: true,
        stencilFunc: THREE.AlwaysStencilFunc,
        stencilRef: 1,
        stencilZPass: THREE.ReplaceStencilOp
      })
    }

    attachShaderClippedSection(this.skeletonMaterial, 0, 0, 0)
    attachShaderClippedSection(this.skeletonMaterial, 0, 0, 0)
  }
}
