import { SceneWrapper } from '../'
import { PebblesGround } from './PebblesGround'
import { SkyPanorama } from './SkyPanorama'
import { Substation } from './Substation'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'

export class Environment extends MeshWrapperCommon {
  public skyPanorama!: SkyPanorama
  public pebblesGround?: PebblesGround | undefined = undefined
  public substation?: Substation | undefined = undefined

  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)

    this.init()
  }

  public async init() {
    this.substation = new Substation(this.sceneWrapper)
    this.skyPanorama = new SkyPanorama(this.sceneWrapper)
    this.pebblesGround = new PebblesGround(this.sceneWrapper)
    this.ready = true
  }
  public show(value: boolean) {
    // return true
  }
  public destroy(): void {
    //
  }
}
