import * as THREE from 'three'

import { Nubbin } from '.'
import { NubbinBase } from './Base/NubbinBase'
import { StarLink } from './StarLink'

export class CantileverStarlink extends NubbinBase {
  public starLink: StarLink[] = []

  constructor(nubbin: Nubbin) {
    super(nubbin)

    this.buildMesh()
  }
  public buildMesh() {
    if (this.mesh) {
      this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.remove(
        this.mesh
      )
    }

    this.mesh = new THREE.Group()
    this.mesh.name = 'CantileverStarlink'
    const width = 15
    const length = width
    const height = 3.5
    const geometry = new THREE.BoxGeometry(width, height, length)
    geometry.translate(0, -height * 0.5, 0)
    // const material = new THREE.MeshStandardMaterial({ color: 0x808080 })
    const box = new THREE.Mesh(
      geometry,
      this.nubbin.hypercubeParametric.configurator.materials.skeletonMaterial
    )
    box.castShadow = true
    box.receiveShadow = true
    this.mesh.add(box)

    this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.add(
      this.mesh
    )

    for (let i = 0; i < 4; i++) {
      for (let j = 0; j < 2; j++) {
        if (j === 1 && i < 2) continue
        const starLink = new StarLink(this)
        starLink.mesh.position.x = this.mesh.position.x + (i - 1.5) * 4.0
        starLink.mesh.position.z = this.mesh.position.z + (j - 0.5) * 8.0
        this.starLink.push(starLink)
      }
    }
    this.syncSizes()
    // this.starLink.init()
  }
  public syncSizes() {
    if (this.mesh) {
      this.mesh.position.x =
        this.nubbin.hypercubeParametric.params.width * 0.5 +
        this.nubbin.hypercubeParametric.params.thickness * 0.5
      this.mesh.position.y = this.nubbin.hypercubeParametric.params.height * 0.5
      // this.addon.hypercubeParametric.params.groundY

      this.mesh.position.z =
        -this.nubbin.hypercubeParametric.params.length * 0.5 -
        this.nubbin.hypercubeParametric.params.thickness * 0.5
    }
  }
  public rotateX(value: number) {
    this.starLink.forEach((obj: StarLink) => {
      obj.rotateX(value)
    })
  }
  public rotateY(value: number) {
    this.starLink.forEach((obj: StarLink) => {
      obj.rotateY(value)
    })
  }
  public show(show: boolean): boolean {
    this.mesh.visible = show
    return this.mesh.visible
  }
  public toggleVisibility() {
    this.mesh.visible = !this.mesh.visible
  }
  public onClick(): void {
    throw new Error('Method not implemented.')
  }
  public update(): boolean {
    throw new Error('Method not implemented.')
  }
}
