import * as THREE from 'three'

import { Nubbin } from './'
import { loadFBXWithMat } from '../../../../../utils/ThreeUtils'

export class DroneReadyNet {
  public nubbin: Nubbin
  public mesh: THREE.Group

  public movement = [
    { x: -22, y: 28, z: -22, duration: 3000 },
    { x: 22, y: 25, z: -22, duration: 2000 },
    { x: 12, y: 25, z: 12, duration: 3000 },
    { x: -22, y: 25, z: 22, duration: 2000 },
    { x: -22, y: 36 - 15, z: -22, duration: 2000 },
    { x: -22, y: 17.5, z: -22, duration: 3000 },
    { x: -22, y: 28, z: -22, duration: 1000 }
  ]

  private currentMovementIndex = 0
  private isMoving = false
  private movementStartTime = 0
  private movementDuration = 0
  private startPosition = new THREE.Vector3()
  private targetPosition = new THREE.Vector3()

  constructor(nubbin: Nubbin) {
    this.nubbin = nubbin
    this.mesh = new THREE.Group()
    this.init()
  }

  public init() {
    this.loadModel(['/hypercube-asset/model/drone-ready.fbx'], 0.01)
  }

  private loadModel = async (files: string[], scale: number) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBXWithMat(
          file,
          scale,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .rendererCore.useWebGPU,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .isPerformanceMode,
          this.nubbin.hypercubeParametric.configurator.materials.clippingPlanes,
          this.nubbin.hypercubeParametric.configurator.materials.MaterialClass,
          this.nubbin.hypercubeParametric.configurator.materials.nubbinMaterial
        )
      )

      const fbxModels = await Promise.all(loadPromises)
      fbxModels[0].rotation.y = -Math.PI * 0.5

      this.mesh = fbxModels[0]

      this.mesh.children[1].visible = false
      this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.add(
        this.mesh
      )

      const texture = new THREE.TextureLoader().load(
        '/hypercube-asset/model/texture/readyLogoGrayBlack.jpg'
      )
      const mesh = this.mesh.children[0].children[0]
      const material = mesh.material as THREE.MeshStandardMaterial
      material[0].map = texture
      material[0].needsUpdate = true

      this.mesh.position.y = 17.5
      this.mesh.position.x = -22
      this.mesh.position.z = -22
      this.mesh.userData.onClick = () => this.onClick()
    } catch (error) {
      console.error('fail to load :', error)
    }
  }

  public update() {
    if (!this.mesh) return false

    if (this.currentMovementIndex === 0) {
      // console.log(this.currentMovementIndex)
      return false
    }

    if (
      this.currentMovementIndex > 0 &&
      this.currentMovementIndex < this.movement.length
    ) {
      this.rotation(0.01)
      this.hover()
      this.rotor()
    } else {
      this.rotor()
    }

    this.updateMovement()
    return true
  }

  public rotation(value: number) {
    this.mesh.rotation.y += value
  }

  public hover() {
    this.mesh.position.y += Math.sin(this.mesh.rotation.y * 10) * 0.05
  }

  public onClick() {
    // console.log('DroneReadyNet onClick')
    if (!this.isMoving) {
      this.moveToNextPosition()
    }
  }
  public show(show: boolean): boolean {
    this.mesh.visible = show
    return this.mesh.visible
  }
  public rotor(value: number = 1) {
    this.mesh.children[0].children[1].rotation.y += value
    this.mesh.children[0].children[2].rotation.y += value
    this.mesh.children[0].children[3].rotation.y += value
    this.mesh.children[0].children[7].rotation.y += value
  }

  public moveToNextPosition() {
    const target = this.movement[this.currentMovementIndex]
    // console.log('Moving to:', target)

    this.startPosition.copy(this.mesh.position)
    this.targetPosition.set(target.x, target.y, target.z)
    this.movementDuration = target.duration
    this.movementStartTime = Date.now()
    this.isMoving = true

    this.currentMovementIndex =
      (this.currentMovementIndex + 1) % this.movement.length
  }

  private updateMovement() {
    if (!this.isMoving) return

    const elapsed = Date.now() - this.movementStartTime
    const progress = Math.min(elapsed / this.movementDuration, 1)

    const eased =
      progress < 0.5
        ? 2 * progress * progress
        : 1 - Math.pow(-2 * progress + 2, 2) / 2

    this.mesh.position.y = THREE.MathUtils.lerp(
      this.startPosition.y,
      this.targetPosition.y,
      eased
    )
    this.mesh.position.x = THREE.MathUtils.lerp(
      this.startPosition.x,
      this.targetPosition.x,
      eased
    )
    this.mesh.position.z = THREE.MathUtils.lerp(
      this.startPosition.z,
      this.targetPosition.z,
      eased
    )

    if (progress >= 1) {
      this.isMoving = false
    }
  }
}
