class FrameRateMonitor {
  private readonly TARGET_FPS: number
  private readonly FRAME_INTERVAL: number
  private readonly MAX_HISTORY_LENGTH: number = 60
  private readonly UPDATE_INTERVAL: number = 1000

  private frames: number = 0
  private frameCount: number = 0

  private lastFrameTime: number = 0
  private lastUpdateTime: number = 0
  private frameStartTime: number = 0
  private frameEndTime: number = 0
  private lastRenderTime: number = 0

  private fps: number = 0
  private fpsHistory: number[] = []
  private frameTimeHistory: number[] = []

  private deltaTime: number = 0
  private lastDeltaTime: number = 0
  private deltaTimeHistory: number[] = []

  private isInitialized: boolean = false

  constructor(targetFPS: number = 60) {
    this.TARGET_FPS = targetFPS
    this.FRAME_INTERVAL = 1000 / this.TARGET_FPS
    this.initialize()
  }

  private initialize(): void {
    const now = performance.now()
    this.lastFrameTime = now
    this.lastUpdateTime = now
    this.lastDeltaTime = now
    this.isInitialized = true
  }

  public shouldRenderFrame(): boolean {
    if (!this.isInitialized) {
      this.initialize()
      return true
    }

    const currentTime = performance.now()
    const timeSinceLastFrame = currentTime - this.lastFrameTime

    if (timeSinceLastFrame < this.FRAME_INTERVAL) {
      return false
    }

    this.lastFrameTime =
      currentTime - (timeSinceLastFrame % this.FRAME_INTERVAL)
    return true
  }
  public frameStart(): void {
    this.frameStartTime = performance.now()

    this.deltaTime = (this.frameStartTime - this.lastDeltaTime) / 1000
    this.lastDeltaTime = this.frameStartTime

    this.deltaTimeHistory.push(this.deltaTime)
    if (this.deltaTimeHistory.length > this.MAX_HISTORY_LENGTH) {
      this.deltaTimeHistory.shift()
    }
  }
  public frameEnd(): void {
    this.frameEndTime = performance.now()
    this.lastRenderTime = this.frameEndTime - this.frameStartTime

    this.frameTimeHistory.push(this.lastRenderTime)
    if (this.frameTimeHistory.length > this.MAX_HISTORY_LENGTH) {
      this.frameTimeHistory.shift()
    }

    this.frameCount++
  }
  public update(): void {
    const currentTime = performance.now()
    this.frames++

    const elapsed = currentTime - this.lastUpdateTime

    if (elapsed >= this.UPDATE_INTERVAL) {
      this.fps = Math.round((this.frames * 1000) / elapsed)
      this.fpsHistory.push(this.fps)

      if (this.fpsHistory.length > this.MAX_HISTORY_LENGTH) {
        this.fpsHistory.shift()
      }

      this.frames = 0
      this.lastUpdateTime = currentTime
    }
  }
  public getDeltaTime(): number {
    return this.deltaTime
  }
  public getAverageDeltaTime(): number {
    if (this.deltaTimeHistory.length === 0) return 0
    const sum = this.deltaTimeHistory.reduce((a, b) => a + b, 0)
    return sum / this.deltaTimeHistory.length
  }
  public getDeltaTimeHistory(): number[] {
    return [...this.deltaTimeHistory]
  }
  public getFPS(): number {
    return this.fps
  }
  public getFrameCount(): number {
    return this.frameCount
  }
  public getLastFrameTime(): number {
    return this.lastRenderTime
  }
  public getAverageFPS(): number {
    if (this.fpsHistory.length === 0) return 0
    const sum = this.fpsHistory.reduce((a, b) => a + b, 0)
    return Math.round(sum / this.fpsHistory.length)
  }
  public getMinFPS(): number {
    if (this.fpsHistory.length === 0) return 0
    return Math.min(...this.fpsHistory)
  }
  public getMaxFPS(): number {
    if (this.fpsHistory.length === 0) return 0
    return Math.max(...this.fpsHistory)
  }
  public getAverageFrameTime(): number {
    if (this.frameTimeHistory.length === 0) return 0
    const sum = this.frameTimeHistory.reduce((a, b) => a + b, 0)
    return sum / this.frameTimeHistory.length
  }
  public getFPSHistory(): number[] {
    return [...this.fpsHistory]
  }
  public getFrameTimeHistory(): number[] {
    return [...this.frameTimeHistory]
  }
  public reset(): void {
    const now = performance.now()

    this.frames = 0
    this.frameCount = 0
    this.fps = 0
    this.deltaTime = 0
    this.lastRenderTime = 0

    this.fpsHistory = []
    this.frameTimeHistory = []
    this.deltaTimeHistory = []

    this.lastFrameTime = now
    this.lastUpdateTime = now
    this.lastDeltaTime = now
    this.frameStartTime = 0
    this.frameEndTime = 0

    this.isInitialized = true
  }
  public getStats(): {
    currentFPS: number
    averageFPS: number
    minFPS: number
    maxFPS: number
    averageFrameTime: number
    deltaTime: number
    averageDeltaTime: number
    frameCount: number
  } {
    return {
      currentFPS: this.fps,
      averageFPS: this.getAverageFPS(),
      minFPS: this.getMinFPS(),
      maxFPS: this.getMaxFPS(),
      averageFrameTime: this.getAverageFrameTime(),
      deltaTime: this.deltaTime,
      averageDeltaTime: this.getAverageDeltaTime(),
      frameCount: this.frameCount
    }
  }
  public getPerformanceLevel(): 'excellent' | 'good' | 'fair' | 'poor' {
    const avgFPS = this.getAverageFPS()
    const targetFPS = this.TARGET_FPS

    if (avgFPS >= targetFPS * 0.9) return 'excellent'
    if (avgFPS >= targetFPS * 0.7) return 'good'
    if (avgFPS >= targetFPS * 0.5) return 'fair'
    return 'poor'
  }
  public isFrameDropDetected(): boolean {
    if (this.fpsHistory.length < 3) return false

    const recentFPS = this.fpsHistory.slice(-3)
    const avgRecent = recentFPS.reduce((a, b) => a + b, 0) / recentFPS.length

    return avgRecent < this.TARGET_FPS * 0.5
  }
  public trimHistory(maxLength: number = 30): void {
    if (this.fpsHistory.length > maxLength) {
      this.fpsHistory = this.fpsHistory.slice(-maxLength)
    }
    if (this.frameTimeHistory.length > maxLength) {
      this.frameTimeHistory = this.frameTimeHistory.slice(-maxLength)
    }
    if (this.deltaTimeHistory.length > maxLength) {
      this.deltaTimeHistory = this.deltaTimeHistory.slice(-maxLength)
    }
  }
  public getDebugInfo(): string {
    const stats = this.getStats()
    const perf = this.getPerformanceLevel()

    return `FPS: ${stats.currentFPS} (Avg: ${stats.averageFPS}, Min: ${stats.minFPS}, Max: ${stats.maxFPS})
            Frame Time: ${stats.averageFrameTime.toFixed(2)}ms
            Delta: ${stats.deltaTime.toFixed(3)}s (Avg: ${stats.averageDeltaTime.toFixed(3)}s)
            Performance: ${perf}
            Total Frames: ${stats.frameCount}`
  }
}

export default FrameRateMonitor
