import { RendererCore } from '..'
import { CLICK_TYPE } from '../../utils/const'

type MouseEventHandler = (e: MouseEvent, type: CLICK_TYPE) => void

export class EventWrapper {
  public threeCore: RendererCore

  private clickTimer: number | null = null
  private preventSingleClick: boolean = false
  private clickDelay: number = 250

  private isPressed: boolean = false
  private isDragging: boolean = false
  private dragThreshold: number = 2

  private mouseDownX: number = 0
  private mouseDownY: number = 0
  private lastClickTime: number = 0
  private doubleClickThreshold: number = 400

  private eventQueue: Array<{ e: MouseEvent; type: CLICK_TYPE }> = []
  private isProcessingEvents: boolean = false
  private lastMouseMoveTime: number = 0
  private mouseMoveThrottle: number = 16 // ~60fps (1000ms/60fps)
  private lastDragTime: number = 0
  private dragThrottle: number = 16 // ~60fps

  private lastMouseX: number = 0
  private lastMouseY: number = 0
  private mouseMoveDelta: number = 0

  // RAF based event processing
  private rafId: number | null = null

  public mouseEventArray: MouseEventHandler[] = []

  constructor(threeCore: RendererCore) {
    this.threeCore = threeCore
  }
  public addMouseEvent(eventDD: MouseEventHandler) {
    this.mouseEventArray.push(eventDD)
  }
  public InitNativeMouseEvent(div: HTMLCanvasElement) {
    div.oncontextmenu = (e: MouseEvent) => {
      e.preventDefault()
      return false
    }

    div.onmousedown = (e: MouseEvent) => {
      e.preventDefault()

      this.isPressed = true
      this.isDragging = false
      this.mouseDownX = e.clientX
      this.mouseDownY = e.clientY

      this.mouseDown(e)
    }
    div.onmouseup = (e: MouseEvent) => {
      e.preventDefault()

      const wasPressed = this.isPressed
      this.isPressed = false

      if (wasPressed && !this.isDragging) {
        this.handleClick(e)
      }

      this.isDragging = false
      this.mouseUp(e)
    }

    div.onmousemove = (e: MouseEvent) => {
      const currentTime = performance.now()

      const deltaX = e.clientX - this.lastMouseX
      const deltaY = e.clientY - this.lastMouseY
      this.mouseMoveDelta = Math.sqrt(deltaX * deltaX + deltaY * deltaY)

      this.lastMouseX = e.clientX
      this.lastMouseY = e.clientY

      if (this.isPressed) {
        const dragDeltaX = Math.abs(e.clientX - this.mouseDownX)
        const dragDeltaY = Math.abs(e.clientY - this.mouseDownY)

        if (
          dragDeltaX > this.dragThreshold ||
          dragDeltaY > this.dragThreshold
        ) {
          if (!this.isDragging) {
            this.isDragging = true
            this.cancelClickTimer()
          }

          if (currentTime - this.lastDragTime >= this.dragThrottle) {
            this.lastDragTime = currentTime
            this.queueEvent(e, CLICK_TYPE.DRAG)
          }
        }
      } else {
        if (currentTime - this.lastMouseMoveTime >= this.mouseMoveThrottle) {
          this.lastMouseMoveTime = currentTime
          this.queueEvent(e, CLICK_TYPE.MOVE)
        }
      }
    }

    div.onmouseleave = (e: MouseEvent) => {
      if (this.isPressed) {
        this.isPressed = false
        this.isDragging = false
        this.mouseUp(e)
      }
      this.eventQueue = []
    }

    div.onclick = (e: MouseEvent) => {
      e.preventDefault()
    }

    div.ondblclick = (e: MouseEvent) => {
      e.preventDefault()
    }

    div.onwheel = (e: MouseEvent) => {
      this.onWhile(e)
      e.preventDefault()
    }

    // RAF based event processing
    this.startEventProcessing()
  }

  private queueEvent(e: MouseEvent, type: CLICK_TYPE) {
    const eventCopy = {
      clientX: e.clientX,
      clientY: e.clientY,
      button: e.button,
      ctrlKey: e.ctrlKey,
      shiftKey: e.shiftKey,
      altKey: e.altKey,
      metaKey: e.metaKey
    } as MouseEvent

    if (this.eventQueue.length > 10) {
      const oldEventIndex = this.eventQueue.findIndex(
        (item) => item.type === CLICK_TYPE.MOVE || item.type === CLICK_TYPE.DRAG
      )
      if (oldEventIndex !== -1) {
        this.eventQueue.splice(oldEventIndex, 1)
      }
    }
    this.eventQueue.push({ e: eventCopy, type })
  }
  private startEventProcessing() {
    const processEvents = () => {
      if (this.eventQueue.length > 0 && !this.isProcessingEvents) {
        this.isProcessingEvents = true

        const batchSize = Math.min(3, this.eventQueue.length)
        const batch = this.eventQueue.splice(0, batchSize)

        Promise.resolve().then(() => {
          batch.forEach(({ e, type }) => {
            this.processEvent(e, type)
          })
          this.isProcessingEvents = false
        })
      }

      this.rafId = requestAnimationFrame(processEvents)
    }

    this.rafId = requestAnimationFrame(processEvents)
  }
  private processEvent(e: MouseEvent, type: CLICK_TYPE) {
    switch (type) {
      case CLICK_TYPE.MOVE:
        this.onMouseEventListener(e, CLICK_TYPE.MOVE)
        break
      case CLICK_TYPE.DRAG:
        this.onMouseEventListener(e, CLICK_TYPE.DRAG)
        break
      default:
        this.onMouseEventListener(e, type)
    }
  }
  private handleClick(e: MouseEvent) {
    const currentTime = Date.now()

    if (currentTime - this.lastClickTime < this.doubleClickThreshold) {
      this.cancelClickTimer()
      this.preventSingleClick = true
      this.mouseDoubleClick(e)
      this.lastClickTime = 0
    } else {
      this.preventSingleClick = false
      this.lastClickTime = currentTime

      this.clickTimer = window.setTimeout(() => {
        if (!this.preventSingleClick) {
          this.mouseClick(e)
        }
        this.preventSingleClick = false
      }, this.clickDelay)
    }
  }
  private cancelClickTimer() {
    if (this.clickTimer !== null) {
      clearTimeout(this.clickTimer)
      this.clickTimer = null
    }
  }
  public setDoubleClickThreshold(threshold: number) {
    this.doubleClickThreshold = Math.max(100, Math.min(1000, threshold))
  }
  public isMousePressed(): boolean {
    return this.isPressed
  }
  public isMouseDragging(): boolean {
    return this.isDragging
  }
  public setClickDelay(delay: number) {
    this.clickDelay = Math.max(50, Math.min(1000, delay))
  }
  public setDragThreshold(threshold: number) {
    this.dragThreshold = Math.max(1, threshold)
  }
  public setMouseMoveThrottle(throttle: number) {
    this.mouseMoveThrottle = Math.max(8, Math.min(100, throttle))
  }
  public setDragThrottle(throttle: number) {
    this.dragThrottle = Math.max(8, Math.min(100, throttle))
  }
  public getMouseMoveDelta(): number {
    return this.mouseMoveDelta
  }
  // ................................
  public mouseMove(e: MouseEvent) {
    this.onMouseEventListener(e, CLICK_TYPE.MOVE)
  }

  public mouseDown(e: MouseEvent) {
    this.onMouseEventListener(e, CLICK_TYPE.DOWN)
  }

  public mouseUp(e: MouseEvent) {
    this.onMouseEventListener(e, CLICK_TYPE.UP)
  }

  public mouseClick(e: MouseEvent) {
    this.onMouseEventListener(e, CLICK_TYPE.LEFT)
  }

  public mouseDoubleClick(e: MouseEvent) {
    this.onMouseEventListener(e, CLICK_TYPE.DOUBLE)
  }

  public mouseDrag(e: MouseEvent) {
    const deltaX = e.clientX - this.mouseDownX
    const deltaY = e.clientY - this.mouseDownY
    this.onMouseEventListener(e, CLICK_TYPE.DRAG)
  }
  public onMouseEventListener = (e: MouseEvent, type: CLICK_TYPE) => {
    this.threeCore.onMouseEventListener(e, type)

    this.mouseEventArray.forEach((eventItem) => {
      eventItem(e, type)
    })
  }
  public onWhile = (e: any) => {
    // console.log(e.deltaY);
  }
  public destroy() {
    this.cancelClickTimer()
    this.isPressed = false
    this.isDragging = false
    this.eventQueue = []

    if (this.rafId !== null) {
      cancelAnimationFrame(this.rafId)
      this.rafId = null
    }
  }
}
