import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'

import { HypercubeParametric } from '..'
import { FoundationInnerCooling } from './FoundationInnerCooling'
import { loadFBXWithMat } from '../../../../../utils/ThreeUtils'

export class FoundationBase {
  public hypercubeParametric: HypercubeParametric

  public mesh: THREE.Group | undefined = undefined
  public foundationInnerCooling: FoundationInnerCooling

  private paths = ['/hypercube-asset/model/coolingBaseLow.fbx']
  private pathTexture = '/hypercube-asset/model/texture/concrete.jpg'

  constructor(hypercubeParametric: HypercubeParametric) {
    this.hypercubeParametric = hypercubeParametric

    this.foundationInnerCooling = new FoundationInnerCooling(this)
    this.init()
  }
  public async init() {
    this.loadModel(this.paths, 0.25)

    // TODO:
    // this.loadModelGLB(['/hypercube-asset/model/coolingBaseLow.glb'], 10)
  }
  private loadModel = async (files: string[], scale: number) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBXWithMat(
          file,
          scale,
          this.hypercubeParametric.configurator.sceneWrapper.appCore
            .rendererCore.useWebGPU,
          this.hypercubeParametric.configurator.sceneWrapper.appCore
            .isPerformanceMode,
          this.hypercubeParametric.configurator.materials.clippingPlanes,
          this.hypercubeParametric.configurator.materials.MaterialClass,
          this.hypercubeParametric.configurator.materials.nubbinMaterial
        )
      )

      const fbxModels = await Promise.all(loadPromises)
      fbxModels[0].rotation.y = -Math.PI * 0.5
      // console.log(fbxModels)
      this.mesh = fbxModels[0]
      this.mesh.position.y = -17

      const textureScale = 0.003
      const textureLoader = new THREE.TextureLoader()
      const texture = await new Promise<THREE.Texture>((resolve, reject) => {
        textureLoader.load(
          this.pathTexture,
          (tex) => {
            tex.colorSpace = THREE.SRGBColorSpace
            tex.wrapS = THREE.RepeatWrapping
            tex.wrapT = THREE.RepeatWrapping
            tex.repeat.set(textureScale, textureScale)

            resolve(tex)
          },
          undefined,
          (error) => {
            console.error('texture loading error:', error)
            reject(error)
          }
        )
      })

      const meshFoundation = this.mesh.children[4]
      const material = meshFoundation.material as THREE.MeshPhysicalMaterial

      material.map = texture
      material.color.setHex(0xcccccc)
      material.metalness = 0
      material.roughness = 0.9
      material.clearcoat = 0
      material.clearcoatRoughness = 0
      material.needsUpdate = true

      // this.hypercubeParametric.configurator.xrayViewController.push(
      //   meshFoundation
      // )

      this.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh)

      this.mesh.userData.onClick = () => this.onClick()
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  private loadModelGLB = async (files: string[], scale: number) => {
    try {
      const loader = new GLTFLoader()

      const loadPromises = files.map(
        (file) =>
          new Promise<THREE.Object3D>((resolve, reject) => {
            loader.load(
              file,
              (gltf) => {
                const model = gltf.scene
                model.scale.setScalar(scale)
                resolve(model)
              },
              undefined,
              reject
            )
          })
      )

      const models = await Promise.all(loadPromises)

      this.mesh = models[0]
      console.log(this.mesh, models[0])
      this.mesh.rotation.y = -Math.PI * 0.5
      this.mesh.position.y = -17

      const textureScale = 0.003
      const textureLoader = new THREE.TextureLoader()

      const texture = await new Promise<THREE.Texture>((resolve, reject) => {
        textureLoader.load(
          this.pathTexture,
          (tex) => {
            tex.colorSpace = THREE.SRGBColorSpace
            tex.wrapS = THREE.RepeatWrapping
            tex.wrapT = THREE.RepeatWrapping
            tex.repeat.set(textureScale, textureScale)
            resolve(tex)
          },
          undefined,
          reject
        )
      })

      let meshFoundation: THREE.Mesh | null = null

      this.mesh.traverse((obj) => {
        if ((obj as THREE.Mesh).isMesh && obj.name === 'foundation') {
          meshFoundation = obj as THREE.Mesh
        }
      })

      const material = meshFoundation.material as THREE.MeshPhysicalMaterial

      material.map = texture
      material.color.setHex(0xcccccc)
      material.metalness = 0
      material.roughness = 0.9
      material.clearcoat = 0
      material.clearcoatRoughness = 0
      material.needsUpdate = true

      this.mesh.traverse((obj) => {
        if ((obj as THREE.Mesh).isMesh) {
          obj.castShadow = true
          obj.receiveShadow = true
        }
      })

      this.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh)

      this.mesh.userData.onClick = () => this.onClick()
    } catch (error) {
      console.error('fail to load glb:', error)
    }
  }
  public onClick() {
    this.hypercubeParametric.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      this.mesh,
      1.5
    )
    this.hypercubeParametric.configurator.sceneWrapper.appCore.actionStateProcessor.emitAction(
      'foundation@'
    )
  }
  public show(show: boolean) {
    this.mesh.visible = show
    return this.mesh.visible
  }
  public update() {
    if (this.foundationInnerCooling) {
      return this.foundationInnerCooling.update()
    }
  }
}
