import { AppCore } from './AppCore'
import { ENVIRONMENT_TYPE } from './utils/const'

export class APIInterface {
  public appCore!: AppCore
  public shiftEnvironmentType(type: ENVIRONMENT_TYPE) {
    this.appCore?.common.api.shiftEnvironmentType(type)
  }
  public setFOV(value: number) {
    // console.log(this.appCore, value)
    this.appCore?.common.setFOV(value)
  }
  public moveCameraForward() {
    this.appCore?.common.viewChangingForward()
  }
  public moveCameraBackward() {
    this.appCore?.common.viewChangingBackward()
  }
  public activateAnimationA() {
    this.appCore?.common.toggleAnimationRotatingA()
  }
  public activateAnimationB() {
    this.appCore?.common.toggleAnimationRotatingB()
  }
}
