import * as THREE from 'three'

import { FoundationBase } from './FoundationBase'
import { GyroidMesh } from './GyroidMesh'
import { loadFBXWithMat } from '../../../../../utils/ThreeUtils'

export class FoundationInnerCooling {
  public foundationBase: FoundationBase

  public mesh: THREE.Group | undefined = undefined

  public gyroidMesh: GyroidMesh

  private paths = ['/hypercube-asset/model/innerCoolingFoundation.fbx']

  constructor(foundation: FoundationBase) {
    this.foundationBase = foundation

    this.init()

    this.gyroidMesh = new GyroidMesh(this)
  }
  public init() {
    this.loadModel(this.paths, 0.25)
  }
  private loadModel = async (files: string[], scale: number) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBXWithMat(
          file,
          scale,
          this.foundationBase.hypercubeParametric.configurator.sceneWrapper
            .appCore.rendererCore.useWebGPU,
          this.foundationBase.hypercubeParametric.configurator.sceneWrapper
            .appCore.isPerformanceMode,
          this.foundationBase.hypercubeParametric.configurator.materials
            .clippingPlanes,
          this.foundationBase.hypercubeParametric.configurator.materials
            .MaterialClass,
          this.foundationBase.hypercubeParametric.configurator.materials
            .nubbinMaterial
        )
      )

      const fbxModels = await Promise.all(loadPromises)
      fbxModels[0].rotation.y = -Math.PI * 0.5
      // console.log(fbxModels)
      this.mesh = fbxModels[0]
      this.mesh.position.y = -17

      this.mesh.children[3].visible = false
      this.foundationBase.hypercubeParametric.configurator.sceneWrapper.scene.add(
        this.mesh
      )
      this.mesh.userData.onClick = () => this.onClick()
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  public onClick() {
    // TODO:
  }
  public update() {
    if (this.gyroidMesh) {
      return this.gyroidMesh.update()
    }
  }
}
