import * as THREE from 'three'

import { SceneWrapper } from '../'
import { VRProjector } from './VRProjector'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'
import { Configurator } from '../Configurator'

export class VREnv extends MeshWrapperCommon {
  public mesh: THREE.Mesh
  public scene: THREE.Scene

  private vrProjector: VRProjector

  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)

    this.init()
  }
  public show(value: boolean) {
    return value
  }
  private init() {
    this.vrProjector = new VRProjector(
      this.sceneWrapper.scene,
      this.sceneWrapper.appCore.rendererCore.renderer,
      this.sceneWrapper.appCore.rendererCore.host
    )

    this.vrProjector.importMode = () => {
      this.sceneWrapper.configurator = new Configurator(this.sceneWrapper)
      this.sceneWrapper.initPost()
    }

    this.ready = true
  }

  public update() {
    this.vrProjector.update()
    return true
  }
}
