import * as THREE from 'three'

import { Hypercube } from '..'

export class DroneDevice {
  public hypercube: Hypercube
  public meshGroup: THREE.Group
  private speed = Math.random() * 1.5 + 0.5
  constructor(
    hypercube: Hypercube,
    meshGroup: THREE.Group,
    x: number,
    y: number,
    z: number
  ) {
    this.hypercube = hypercube
    this.meshGroup = meshGroup
    this.hypercube.sceneWrapper.scene.add(this.meshGroup)

    this.meshGroup.position.x = x
    this.meshGroup.position.y = y
    this.meshGroup.position.z = z
  }
  public set visible(v: boolean) {
    this.meshGroup.children.forEach((mesh) => {
      mesh.visible = v
    })
  }
  public update() {
    if (!this.meshGroup || !this.hypercube.runningDroneDevices) return false

    this.meshGroup.rotation.y += 0.01 * this.speed
    return true
  }
}
