import * as THREE from 'three'

import { AppCore } from '..'
import { HypercubePopup } from './HypercubePopup'
import { CLICK_TYPE, ENVIRONMENT_TYPE } from '../../utils/const'

export class ActiveCommand {
  public appCore: AppCore

  public selectedMesh: THREE.Object3D | undefined = undefined
  public hoverMesh: THREE.Object3D | undefined = undefined

  public popup: HypercubePopup

  private isHoverNewMesh = false

  private rayCaster: THREE.Raycaster = new THREE.Raycaster()
  private mouse: THREE.Vector2 = new THREE.Vector2()

  private cachedBox: THREE.Box3 = new THREE.Box3()
  private cachedCenter: THREE.Vector3 = new THREE.Vector3()
  private cachedProjected: THREE.Vector3 = new THREE.Vector3()

  private lastPickingTime: number = 0
  private pickingThrottle: number = 100 // ms
  private cachedPickingResult: THREE.Object3D | undefined = undefined

  private readonly interactiveMeshNames = new Set([
    'mesh11848',
    'Object991',
    'Object981',
    'Object984',
    'Object987',
    'Object996'
  ])

  constructor(appCore: AppCore, pickingThrottle: number = 200) {
    this.appCore = appCore
    this.popup = new HypercubePopup(this.appCore.rendererCore.host)

    this.rayCaster.params.Line = { threshold: 1 }
    this.rayCaster.params.Points = { threshold: 1 }

    this.setPickingThrottle(pickingThrottle)
  }

  public onMouseEventListener(e: MouseEvent, type: CLICK_TYPE) {
    // console.log('Mouse Event:', CLICK_TYPE[type], e)
    switch (type) {
      case CLICK_TYPE.LEFT:
        this.mouseLeftClickPre(e)
        this.appCore.sceneWrapper.renderForce()
        break
      case CLICK_TYPE.MIDDLE:
        this.mouseMiddleClickPre(e)
        break
      case CLICK_TYPE.DOWN_RIGHT:
        this.mouseRightClickPre(e)
        this.appCore.sceneWrapper.renderForce()
        break
      case CLICK_TYPE.DOUBLE:
        this.mouseDoubleClickPre(e)
        this.appCore.sceneWrapper.renderForce()
        break
      case CLICK_TYPE.MOVE:
        this.mouseMovePre(e)
        break
      case CLICK_TYPE.DRAG:
        this.mouseDragPre(e)
        this.appCore.sceneWrapper.renderForce()
        break
      case CLICK_TYPE.DOWN:
        this.mouseDownPre(e)
        this.appCore.sceneWrapper.renderForce()
        break
      case CLICK_TYPE.WHEEL:
        this.mouseWheelPre(e)
        this.appCore.sceneWrapper.renderForce()
        break
      case CLICK_TYPE.UP:
        this.mouseUpPre(e)
        break
    }
  }
  public mouseDown(e: MouseEvent) {
    /* */
  }
  public mouseDownPre(e: MouseEvent) {
    this.appCore.sceneWrapper.configurator?.gizmoController?.onPointerDown(
      e as PointerEvent
    )
    this.mouseDown(e)
  }

  public mouseLeftClick(e: MouseEvent) {
    const mesh = this.picking(e)

    if (!mesh) return

    this.selectedMesh = mesh
    // console.log('Selected Mesh clicked:', mesh.name)

    if (mesh.name === 'innerCoolingWall' || mesh.name === 'PillarFacade') {
      return this.appCore.sceneWrapper.configurator.hypercubeParametric.foundationBase.foundationInnerCooling.gyroidMesh.onClick()
    }

    this.callOnClickRecursive(this.selectedMesh)

    const pop = this.updatePopupPosition(this.selectedMesh)
    if (pop) {
      this.popup.updatePos(pop)
    }

    const meshName = mesh.name
    if (this.interactiveMeshNames.has(meshName)) {
      this.handleInteractiveMesh(meshName)
    }

    if (this.appCore.sceneWrapper.configurator) {
      if (meshName.includes('rolling')) {
        this.appCore.common.commandHypercubeParametric.openSelectedRollingDoor(
          meshName
        )
      } else if (meshName.includes('sliding')) {
        this.appCore.common.commandHypercubeParametric.openSelectedSlidingDoor(
          meshName
        )
      }
    }
  }
  private handleInteractiveMesh(meshName: string) {
    const hyperCube = this.appCore.sceneWrapper.hyperCube

    switch (meshName) {
      case 'mesh11848':
      case 'Object991':
        hyperCube.clickDoorInner()
        break
      case 'Object981':
        hyperCube.clickDoorOuter()
        break
      case 'Object984':
        hyperCube.showCamera()
        break
      case 'Object987':
        hyperCube.showGraph()
        break
      case 'Object996':
        hyperCube.showGraphDrone()
        break
    }
  }

  public mouseLeftClickPre(e: MouseEvent) {
    this.mouseLeftClick(e)
  }

  public MouseMiddleClick(e: MouseEvent) {
    /* */
  }

  public mouseMiddleClickPre(e: MouseEvent) {
    this.MouseMiddleClick(e)
  }

  public MouseRightClick(e: MouseEvent) {
    /* */
  }

  public mouseRightClickPre(e: MouseEvent) {
    this.MouseRightClick(e)
  }

  public mouseUp(e: MouseEvent) {
    /* */
  }

  public mouseUpPre(e: MouseEvent) {
    this.appCore.sceneWrapper.configurator?.gizmoController?.onPointerUp()
    this.mouseUp(e)
  }

  public mouseDoubleClick(e: MouseEvent) {
    /* */
  }

  public mouseDoubleClickPre(e: MouseEvent) {
    this.mouseDoubleClick(e)
  }

  public mouseMove(e: MouseEvent) {
    /* */
  }

  public mouseMovePre(e: MouseEvent) {
    this.appCore.sceneWrapper.configurator?.gizmoController?.onPointerMove(
      e as PointerEvent
    )

    if (
      this.appCore.sceneWrapper.environmentType ===
      ENVIRONMENT_TYPE.Configurator
    ) {
      const mesh = this.pickingThrottled(e)

      if (mesh) {
        if (this.hoverMesh && this.hoverMesh.name === mesh.name) {
          if (this.isHoverNewMesh) {
            this.appCore.common.updateTooltip(this.hoverMesh.name)
            this.isHoverNewMesh = false
          }
        } else {
          this.appCore.common.closeTooltip()
          this.isHoverNewMesh = true
        }

        this.hoverMesh = mesh
      }
    }

    this.mouseMove(e)
  }

  public mouseDrag(e: MouseEvent) {
    /* */
  }

  public mouseDragPre(e: MouseEvent) {
    this.appCore.sceneWrapper.configurator?.gizmoController?.onPointerMove(
      e as PointerEvent
    )

    // 성능 최적화: popup 업데이트를 RAF로 지연
    requestAnimationFrame(() => {
      this.updatePopupPos()
    })

    this.mouseDrag(e)
  }

  public mouseWheel(e: MouseEvent) {
    /* */
  }

  public mouseWheelPre(e: MouseEvent) {
    this.mouseWheel(e)
  }

  public updatePopupPos = () => {
    if (this.selectedMesh) {
      const pop = this.updatePopupPosition(this.selectedMesh)
      if (pop) {
        this.popup.updatePos(pop)
      }
    }
  }

  private pickingThrottled(event: MouseEvent): THREE.Object3D | undefined {
    const currentTime = performance.now()

    if (currentTime - this.lastPickingTime < this.pickingThrottle) {
      return this.cachedPickingResult
    }

    this.lastPickingTime = currentTime
    this.cachedPickingResult = this.picking(event)
    // console.log('Throttled Picking Executed', this.cachedPickingResult)
    return this.cachedPickingResult
  }
  private picking(event: MouseEvent): THREE.Object3D | undefined {
    const div = this.appCore.rendererCore.host
    const camera = this.appCore.rendererCore.cameraWrapper.camera
    const scene = this.appCore.rendererCore.scene

    const rect = div.getBoundingClientRect()

    this.mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
    this.mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1

    this.rayCaster.setFromCamera(this.mouse, camera)

    const intersects = this.rayCaster.intersectObjects(scene.children, true)

    if (intersects.length === 0) return undefined

    for (let i = 0; i < intersects.length; i++) {
      const obj = intersects[i].object

      if (obj.name === 'ground') continue

      if (this.isFullyVisible(obj)) {
        return obj
      }
    }

    return undefined
  }
  private isFullyVisible(object: THREE.Object3D): boolean {
    let current: THREE.Object3D | null = object
    while (current) {
      if (!current.visible) return false
      current = current.parent
    }
    return true
  }

  private callOnClickRecursive(obj?: THREE.Object3D | null): boolean {
    let current = obj
    // console.log({ current })

    while (current) {
      const onClick = current.userData?.onClick
      if (typeof onClick === 'function') {
        Promise.resolve().then(() => onClick())
        return true
      }
      current = current.parent
    }

    return false
  }

  private updatePopupPosition(
    selectedObject?: THREE.Object3D
  ): [number, number, number] | undefined {
    if (!selectedObject) return undefined

    const camera = this.appCore.rendererCore.cameraWrapper.camera
    const renderer = this.appCore.rendererCore.renderer

    this.cachedBox.setFromObject(selectedObject)
    this.cachedBox.getCenter(this.cachedCenter)

    this.cachedProjected.copy(this.cachedCenter).project(camera)

    const canvas = renderer.domElement
    const rect = canvas.getBoundingClientRect()

    const x = (this.cachedProjected.x * 0.5 + 0.5) * rect.width
    const y = (-this.cachedProjected.y * 0.5 + 0.5) * rect.height

    return [x, y, this.cachedProjected.z]
  }
  public setPickingThrottle(throttle: number) {
    this.pickingThrottle = Math.max(16, Math.min(20000, throttle))
    // console.log(this.pickingThrottle)
  }
  public destroy() {
    this.selectedMesh = undefined
    this.hoverMesh = undefined
    this.cachedPickingResult = undefined
  }
}
