import * as THREE from 'three'

import { Hypercube } from '..'

type MeshState = {
  mesh: THREE.Mesh
  originalPosition: THREE.Vector3
  active: boolean
}

export class HypercubeStatic {
  public hypercube: Hypercube
  public meshGroup: THREE.Group
  public meshes: THREE.Mesh[] = []
  private meshStates: MeshState[] = []

  private speed = (Math.random() * 0.5 + 0.5) * 0.1
  private _decompose = false
  private timer = 0
  private interval = 0.1
  private currentIndex = 0
  private animation = false

  // public clippingPlane: THREE.Plane;

  constructor(hypercube: Hypercube, meshGroup: THREE.Group) {
    this.hypercube = hypercube
    this.meshGroup = meshGroup
    this.hypercube.sceneWrapper.scene.add(this.meshGroup)

    // this.clippingPlane = new THREE.Plane(new THREE.Vector3(0, -1, 0), 1000);

    const names = [
      'Object982',
      'top-base',
      'mesh11867',
      'mesh11756',
      'Object983',
      'Object984',
      'Object981',
      'mesh11844',
      'Object980',
      'Object997',
      'mesh11870',
      'mesh11850',
      'Part_461',
      'mesh11868',
      'Part_467',
      'mesh11866',
      'mesh11847',
      'Part_471',
      'Part_472',
      'Part_468',
      'mesh11865',
      'Part_470',
      'Part_469',
      'mesh11863',
      'Part_457',
      'Part_466',
      'Part_465',
      'Part_462',
      'Part_464',
      'Part_463',
      'Part_456',
      'Part_458',
      'Part_459',
      'Part_460',
      'Part_455',
      'Part_475',
      'Part_473',
      'Part_477',
      'Part_478',
      'Part_474',
      'Part_476',
      'mesh11864'
    ]
    const namesSet = new Set(names)
    names.forEach((targetName) => {
      this.meshGroup.children.forEach((child) => {
        if (namesSet.has(child.name)) {
          child.receiveShadow = false
          child.castShadow = false
          this.meshes.push(child)
          this.meshStates.push({
            mesh: child,
            originalPosition: child.position.clone(),
            active: false
          })
        }
      })
    })

    const glassName = 'Object984'

    this.meshGroup.children.forEach((child: THREE.Mesh) => {
      if (glassName === child.name || 'Part_457' === child.name) {
        // console.log(child);
        const glassMaterial = new THREE.MeshPhysicalMaterial({
          transparent: true,
          side: THREE.DoubleSide,
          depthWrite: false,
          color: child.material.color,
          metalness: 0,
          roughness: 0.05,
          transmission: 0.8,
          thickness: 4.5,
          ior: 1.45,
          reflectivity: 0.4,
          opacity: 0.55,
          envMap:
            this.hypercube.sceneWrapper.appCore.rendererCore.hdriWrapper.envMap,
          clearcoat: 1.0,
          clearcoatRoughness: 0.1,
          envMapIntensity: 0.8,
          clippingPlanes: this.hypercube.clippingPlanes
        })
        child.material = glassMaterial
        child.castShadow = true
      }
    })

    const skeleton = 'mesh11867'

    this.meshGroup.children.forEach((child: THREE.Mesh) => {
      if (skeleton === child.name) {
        child.material = this.hypercube.materials.skeletonMaterial
        child.castShadow = true
        child.receiveShadow = true
        child.material.clippingPlanes = this.hypercube.clippingPlanes
      }
    })

    const skin = 'Object982'
    this.meshGroup.children.forEach((child: THREE.Mesh) => {
      if (skin === child.name) {
        child.material = this.hypercube.materials.skinMaterial
        child.castShadow = true
        child.material.clippingPlanes = this.hypercube.clippingPlanes
        // console.log('child.material', child.material);
      }
    })
  }
  public set visible(v: boolean) {
    this.meshGroup.children.forEach((child: THREE.Mesh) => {
      child.visible = v
    })
  }
  public decompose() {
    if (this._decompose) {
      this._decompose = false
      this.timer = 0
    } else {
      this._decompose = true
      this.timer = 0
      this.currentIndex = 0
      this.meshStates.forEach((state) => {
        state.active = false
      })
    }
    this.animation = true
  }
  public update(delta: number) {
    if (this.animation) this.updateDecompose(delta)
  }
  private updateDecompose(delta: number) {
    this.timer += 0.5
    // console.log(this.timer, this.currentIndex)

    if (this._decompose) {
      if (this.currentIndex < this.meshStates.length) {
        if (this.timer > this.interval) {
          this.meshStates[this.currentIndex].active = true
          this.currentIndex++
          this.timer = 0
        }
      }

      this.meshStates.forEach((state) => {
        if (state.active && state.mesh.visible) {
          const targetY = state.originalPosition.y + 10
          const step = this.speed
          state.mesh.position.y = Math.min(
            state.mesh.position.y + step,
            targetY
          )

          if (state.mesh.position.y >= targetY - 0.5) {
            state.mesh.visible = false
          }
        }
      })
    } else {
      let allDone = true

      this.meshStates.forEach((state) => {
        const step = this.speed * delta * 60

        if (state.mesh.position.y > state.originalPosition.y) {
          state.mesh.visible = true
          state.mesh.position.y = Math.max(
            state.mesh.position.y - step,
            state.originalPosition.y
          )
          allDone = false
        }

        if (state.mesh.position.y <= state.originalPosition.y + 0.01) {
          state.active = false
        }
      })

      if (allDone) {
        this.currentIndex = 0
        this.timer = 0
        this.animation = false
      }
    }

    return this.animation
  }
}
