import * as THREE from 'three'
import { OrbitControls } from 'three-orbitcontrols-ts'

import { ENVIRONMENT_TYPE } from '../../utils/const'
import { easeInOutCubic } from '../../utils/ThreeUtils'
import { CameraWrapper } from '../Wrapper/CameraWrapper'

export type CameraState = {
  position: THREE.Vector3
  target: THREE.Vector3
  duration: number
}

export enum CurveType {
  CENTRIPETAL = 'centripetal', // recommended(smooth)
  CHORDAL = 'chordal', // medium
  CATMULLROM = 'catmullrom' // tension (0~1)
}

export class CameraAnimator {
  public cameraWrapper: CameraWrapper
  private camera: THREE.PerspectiveCamera
  private controls: OrbitControls

  private states: CameraState[]

  private positionCurve: THREE.CatmullRomCurve3 | null = null
  private targetCurve: THREE.CatmullRomCurve3 | null = null

  private totalDuration: number = 0
  private durationSegments: number[] = []

  private clock = new THREE.Clock()
  private isAnimating = false
  private _tension = 0.1
  private _curveType: CurveType = CurveType.CENTRIPETAL

  private focusAnimationId: number | null = null
  private isSceneReady = false

  constructor(cameraWrapper: CameraWrapper) {
    this.cameraWrapper = cameraWrapper
    this.camera = cameraWrapper.camera
    this.controls = cameraWrapper.controls

    // console.log(data)
  }
  public initCameraAnimationSimulation() {
    // this.isSceneReady = true
    // this.cameraWrapper.cameraStaringTemplateAScaled()
  }
  public initCameraAnimation() {
    // console.log('dd')
    this.isSceneReady = true
    this.camera.position.set(0, 0, 300)
    const data = [
      // { camera: [0, 0, 700], target: [0.0, 0.0, 0.0], duration: 2000 },
      // { camera: [0, 0, 200], target: [0.0, 0.0, 0.0], duration: 1000 },

      { camera: [42.91, 58.36, 84.7], target: [0.0, 0.0, 0.0], duration: 2500 }
    ]

    this.start(data)
  }
  public set tension(value: number) {
    this._tension = value
  }

  public set curveType(type: CurveType) {
    this._curveType = type
  }
  public onFocusObject(mesh: THREE.Mesh, distance: number = 2.5) {
    if (this.focusAnimationId !== null) {
      cancelAnimationFrame(this.focusAnimationId)
      this.focusAnimationId = null
    }

    const camera = this.camera
    const controls = this.controls
    const bbox = new THREE.Box3().setFromObject(mesh)
    const center = new THREE.Vector3()
    const size = new THREE.Vector3()

    bbox.getCenter(center)
    bbox.getSize(size)

    const maxDim = Math.max(size.x, size.y, size.z)
    const fov = camera.fov * (Math.PI / 180)
    const cameraDistance = Math.abs(maxDim / Math.sin(fov / 2)) * distance

    const direction = new THREE.Vector3()
    camera.getWorldDirection(direction)
    const newPosition = center
      .clone()
      .sub(direction.multiplyScalar(cameraDistance))

    const startPosition = camera.position.clone()
    const startTarget = controls ? controls.target.clone() : new THREE.Vector3()
    const duration = 1500
    const startTime = Date.now()

    const animate = () => {
      const elapsed = Date.now() - startTime
      const progress = Math.min(elapsed / duration, 1)

      const eased =
        progress < 0.5
          ? 4 * progress * progress * progress
          : 1 - Math.pow(-2 * progress + 2, 3) / 2

      camera.position.lerpVectors(startPosition, newPosition, eased)

      if (controls) {
        controls.target.lerpVectors(startTarget, center, eased)
        controls.update()
      }

      if (progress < 1) {
        this.focusAnimationId = requestAnimationFrame(animate)
      } else {
        this.focusAnimationId = null
      }
    }

    this.focusAnimationId = requestAnimationFrame(animate)
  }

  public start(
    data: Array<{ camera: number[]; target: number[]; duration: number }>
  ) {
    const newStates = data.map((d) => ({
      position: new THREE.Vector3(d.camera[0], d.camera[1], d.camera[2]),
      target: new THREE.Vector3(d.target[0], d.target[1], d.target[2]),
      duration: d.duration
    }))

    if (newStates.length === 0) return

    this.states = newStates

    const startState = {
      position: this.camera.position.clone(),
      target: this.controls.target.clone(),
      duration: 0
    }

    const allStates = [startState, ...this.states]

    const positions = allStates.map((s) => s.position)
    const targets = allStates.map((s) => s.target)

    this.positionCurve = new THREE.CatmullRomCurve3(
      positions,
      false,
      this._curveType,
      this._tension
    )

    this.targetCurve = new THREE.CatmullRomCurve3(
      targets,
      false,
      this._curveType,
      this._tension
    )

    this.totalDuration = 0
    this.durationSegments = []

    for (let i = 0; i < this.states.length; i++) {
      this.totalDuration += this.states[i].duration
      this.durationSegments.push(this.totalDuration)
    }

    this.isAnimating = true
    this.clock.start()
    this.controls.enabled = false
  }
  public update() {
    // console.log(!this.isSceneReady, this.cameraWrapper.core.ready)
    // debugger
    // console.log(this.cameraWrapper.core.environment)
    if (!this.isSceneReady && this.cameraWrapper.core.ready) {
      if (
        this.cameraWrapper.core.environment === ENVIRONMENT_TYPE.SimulationViz
      ) {
        this.initCameraAnimationSimulation()
      } else if (
        this.cameraWrapper.core.environment ===
          ENVIRONMENT_TYPE.MissionControl ||
        this.cameraWrapper.core.environment === ENVIRONMENT_TYPE.Globe ||
        this.cameraWrapper.core.environment === ENVIRONMENT_TYPE.Configurator
      ) {
        this.initCameraAnimation()
        // console.log(this.cameraWrapper.core.environment)
      }
    }
    if (!this.isAnimating || !this.positionCurve || !this.targetCurve) {
      return !this.isAnimating
    }

    const elapsed = this.clock.getElapsedTime() * 1000

    if (elapsed >= this.totalDuration) {
      const finalPos = this.positionCurve.getPoint(1)
      const finalTarget = this.targetCurve.getPoint(1)

      this.camera.position.copy(finalPos)
      this.controls.target.copy(finalTarget)
      this.controls.update()

      this.finish()
      return !this.isAnimating
    }

    let t = elapsed / this.totalDuration

    t = easeInOutCubic(t)

    const newPos = this.positionCurve.getPoint(t)
    const newTarget = this.targetCurve.getPoint(t)

    this.camera.position.copy(newPos)
    this.controls.target.copy(newTarget)
    this.controls.update()

    return this.isAnimating
  }

  public stop() {
    this.finish()
  }

  private finish() {
    this.isAnimating = false
    this.controls.enabled = true
    this.positionCurve = null
    this.targetCurve = null
  }

  public dispose() {
    if (this.focusAnimationId !== null) {
      cancelAnimationFrame(this.focusAnimationId)
      this.focusAnimationId = null
    }
  }
}
