import * as THREE from 'three'

import { SceneWrapper } from '..'

export class Particle {
  sceneWrapper: SceneWrapper

  particles: THREE.Points
  particleVelocities = []

  domain: number[] = [-5, 5]

  constructor(sceneWrapper: SceneWrapper) {
    this.sceneWrapper = sceneWrapper

    const boxGeo = new THREE.BoxGeometry(4, 4, 4)
    const boxMat = new THREE.MeshStandardMaterial({ color: 0x4444ff })
    const box = new THREE.Mesh(boxGeo, boxMat)
    this.sceneWrapper.scene.add(box)

    box.visible = false

    const particleCount = 2000
    const positions = []
    this.particleVelocities = []

    for (let i = 0; i < particleCount; i++) {
      const x = this.domain[1] + Math.random() * 5
      const y = (Math.random() - 0.5) * 5
      const z = (Math.random() - 0.5) * 5
      positions.push(x, y, z)

      this.particleVelocities.push(
        new THREE.Vector3(-0.05 - Math.random() * 0.05, 0, 0)
      )
    }

    const particleGeo = new THREE.BufferGeometry()
    particleGeo.setAttribute(
      'position',
      new THREE.Float32BufferAttribute(positions, 3)
    )

    const particleMat = new THREE.PointsMaterial({
      color: 0xcc7722,
      size: 0.0375
    })

    this.particles = new THREE.Points(particleGeo, particleMat)
    this.sceneWrapper.scene.add(this.particles)
  }
  public update() {
    if (this.particles) {
      const positions = this.particles.geometry.attributes.position.array

      for (let i = 0; i < positions.length; i += 3) {
        const vx = this.particleVelocities[i / 3].x
        const vy = this.particleVelocities[i / 3].y
        const vz = this.particleVelocities[i / 3].z

        positions[i] += vx
        positions[i + 1] += vy
        positions[i + 2] += vz

        if (
          Math.abs(positions[i]) < 2 &&
          Math.abs(positions[i + 1]) < 2 &&
          Math.abs(positions[i + 2]) < 2
        ) {
          this.particleVelocities[i / 3].x = (Math.random() - 0.5) * 0.3
          this.particleVelocities[i / 3].y = (Math.random() - 0.5) * 0.8
          this.particleVelocities[i / 3].z = (Math.random() - 0.5) * 0.3
        }

        if (
          positions[i] < this.domain[0] ||
          Math.abs(positions[i + 1]) > this.domain[1] ||
          Math.abs(positions[i + 2]) > this.domain[1]
        ) {
          positions[i] = this.domain[1] + Math.random() * 5
          positions[i + 1] = (Math.random() - 0.5) * 5
          positions[i + 2] = (Math.random() - 0.5) * 5
          this.particleVelocities[i / 3].set(-0.05 - Math.random() * 0.05, 0, 0)
        }
      }

      this.particles.geometry.attributes.position.needsUpdate = true
    }
  }
}
