import * as THREE from 'three'

import { AppCore } from '..'
import { MeshWrapperCommon } from './base/MeshWrapperCommon'
import { Configurator } from './Configurator'
import { Development } from './Development'
import { Playground } from './Development/Playground'
import { Environment } from './Environment'
import { Globe } from './Globe'
import { Hypercube } from './Hypercube'
import { HypercubeArranger } from './HypercubeArranger'
import { HypercubeSimulationViz } from './HypercubeSimulationViz'
import { StudioEnv } from './StudioEnv'
import { VREnv } from './VREnv'
import { ENVIRONMENT_TYPE } from '../../utils/const'

export class SceneWrapper {
  public appCore: AppCore

  public hypercubeSimulationViz: HypercubeSimulationViz

  public configurator: Configurator
  public environment: Environment

  public vrEnv: VREnv

  public hypercubeArranger: HypercubeArranger

  public globe!: Globe
  public studioEnv!: StudioEnv
  public hyperCube!: Hypercube

  public development: Development | undefined = undefined
  public playground: Playground | undefined = undefined

  public scene: THREE.Scene
  public activateGlobe = true

  private _objects: MeshWrapperCommon[] = []
  private _init = false
  private _needShadow = true
  private _hasAnimation = false

  public environmentType: ENVIRONMENT_TYPE
  public BASE_URL =
    'https://raw.githubusercontent.com/NamjuLee/data/master/map/'

  public groundY = -18

  constructor(appCore: AppCore, environmentType: ENVIRONMENT_TYPE) {
    this.appCore = appCore
    this.scene = appCore.rendererCore.scene
    this.environmentType = environmentType

    // NOTE: for development env
    // this.environmentType = ENVIRONMENT_TYPE.Development
  }
  public async init() {
    // console.log('init', this.environmentType)

    if (this.environmentType === ENVIRONMENT_TYPE.Development) {
      // this.playground = new Playground(this)
      this.development = new Development(this)
      return
    }

    if (this.environmentType === ENVIRONMENT_TYPE.MissionControl) {
      this.appCore.rendererCore.lightWrapper.initDirectionalLight()
      this.configurator = new Configurator(this)

      this.studioEnv = new StudioEnv(this)
      this.environment = new Environment(this)

      return
    } else if (this.environmentType === ENVIRONMENT_TYPE.Arranger) {
      this.appCore.rendererCore.lightWrapper.initDirectionalLight()
      this.hypercubeArranger = new HypercubeArranger(this)
      this.studioEnv = new StudioEnv(this)
      // this.environment = new Environment(this)
      return
    } else if (this.environmentType === ENVIRONMENT_TYPE.Configurator) {
      this.appCore.rendererCore.lightWrapper.initDirectionalLight()
      this.studioEnv = new StudioEnv(this)
      this.configurator = new Configurator(this)
      // this.environment = new Environment(this)
      return
    } else if (this.environmentType === ENVIRONMENT_TYPE.SimulationViz) {
      this.hypercubeSimulationViz = new HypercubeSimulationViz(this)
      return
    } else if (this.environmentType === ENVIRONMENT_TYPE.View) {
      this.appCore.rendererCore.lightWrapper.initDirectionalLight()
      this.hyperCube = new Hypercube(this)
      this.environment = new Environment(this)
      return
    } else if (this.environmentType === ENVIRONMENT_TYPE.VR) {
      // this.configurator = new Configurator(this)
      this.vrEnv = new VREnv(this)

      return
    } else if (this.environmentType === ENVIRONMENT_TYPE.SubstationDiorama) {
      this.appCore.rendererCore.lightWrapper.initDirectionalLight()
      this.hyperCube = new Hypercube(this)
      this.environment = new Environment(this)
      // this.substation = new Substation(this)
      return
    } else if (this.environmentType === ENVIRONMENT_TYPE.Globe) {
      this.appCore.rendererCore.lightWrapper.initDirectionalLight()
      this.globe = new Globe(this)
      return
    }
    this.appCore.rendererCore.lightWrapper.initDirectionalLight()

    this.globe = new Globe(this)
    this.studioEnv = new StudioEnv(this)
    this.hyperCube = new Hypercube(this)

    this.environment = new Environment(this)
  }
  public initPost() {
    // console.log('start post init')
    // console.trace()

    if (this.environmentType === ENVIRONMENT_TYPE.Development) {
      return
    }

    this.hideAll()
    this.appCore.rendererCore.rendererWrapper.resizeHandler()
    if (this.environmentType === ENVIRONMENT_TYPE.MissionControl) {
      this.configurator.initPost()
      this.environment.substation?.show(false)
      this.studioEnv?.show(true)

      return
    }

    if (this.environmentType === ENVIRONMENT_TYPE.Arranger) {
      this.studioEnv?.show(true)
      return
    }

    if (this.environmentType === ENVIRONMENT_TYPE.Configurator) {
      // this.environment.substation?.show(false)
      this.configurator.showNubbin(false)
      this.configurator.showServer(false)
      this.configurator.showFoundation(false)
      this.studioEnv?.show(true)
      return
    }

    if (this.environmentType === ENVIRONMENT_TYPE.View) {
      this.hyperCube?.show(true)
      this.environment.substation?.show(true)
      this.environment.pebblesGround?.show(true)
      return
    }

    if (this.environmentType === ENVIRONMENT_TYPE.SimulationViz) {
      this.hypercubeSimulationViz.initPost()
      return
    }

    if (this.environmentType === ENVIRONMENT_TYPE.SubstationDiorama) {
      this.hyperCube?.show(true)
      this.environment.substation?.show(true)
      // this.studioEnv?.show(true);
      return
    }

    if (this.environmentType === ENVIRONMENT_TYPE.Globe) {
      this.globe?.show(true)
      return
    }

    if (this.activateGlobe) {
      this.globe?.show(true)
    } else {
      this.hyperCube?.show(true)
      this.studioEnv?.show(true)
    }
    if (this.appCore.isPerformanceMode) {
      this.toggleShadow()
    }
  }
  public get deltaTime(): number {
    return this.appCore.rendererCore.rendererWrapper.deltaTime
  }
  public renderForce() {
    this.appCore.common.renderForce()
  }
  public hideAll() {
    this._objects.forEach((obj) => obj.show(false))
  }
  public destroy() {
    this._objects.forEach((obj) => obj.destroy())
  }
  public add(object: MeshWrapperCommon) {
    // this.scene.add(object.mesh);
    this._objects.push(object)
  }
  public remove(object: MeshWrapperCommon) {
    // this.scene.remove(object.mesh);
    this._objects.indexOf(object) !== -1 &&
      this._objects.splice(this._objects.indexOf(object), 1)
  }
  public get ready() {
    if (!this._objects.every((obj) => obj.ready)) return false

    if (!this._init) {
      this.initPost()
      this._init = true
    }
    return true
  }
  public update() {
    const results = this._objects.map((obj) => obj?.update() ?? false)
    this._hasAnimation = results.some(Boolean)
    return this._hasAnimation
  }

  public showGlobe() {
    this.hyperCube?.show(false)
    this.environment.substation?.show(false)
    this.studioEnv?.show(false)
    this.globe?.show(true)
    this.activateGlobe = true
  }
  public showStudioEnv() {
    this.globe?.show(false)
    this.environment.substation?.show(false)
    this.hyperCube?.show(true)
    this.studioEnv?.show(true)
    this.activateGlobe = false
  }
  public toggleShadow() {
    this._needShadow = !this._needShadow
  }
}
