import * as THREE from 'three'

import { Configurator } from '..'

interface AxisConstraints {
  x: { min: number; max: number }
  y: { min: number; max: number }
  z: { min: number; max: number }
}

export class GizmoController {
  public configurator: Configurator

  public constraints: AxisConstraints = {
    x: { min: 15, max: 50 },
    y: { min: 15, max: 50 },
    z: { min: 15, max: 50 }
  }
  public meshCube: THREE.Mesh
  public edgeLines: THREE.LineSegments
  public renderForce: () => void = () => {}
  public offset = 0.75

  private tempMatrix = new THREE.Matrix4()
  private tempVector = new THREE.Vector3()
  private baseGeometry: THREE.BoxGeometry

  private raycaster = new THREE.Raycaster()
  private mouse = new THREE.Vector2()
  private selectedFaceNormal: THREE.Vector3 | null = null
  private isDragging = false
  private startMouseX = 0
  private startMouseY = 0
  private startScale = new THREE.Vector3()
  private hoveredFaceIndex: number | null = null
  private startPosition = new THREE.Vector3()
  private baseMaterial = new THREE.MeshBasicMaterial({
    color: 0x000000,
    opacity: 0.0,
    transparent: true,
    wireframe: true
  })
  private highlightMaterial = new THREE.MeshBasicMaterial({
    color: 0xff0000,
    opacity: 0.5,
    transparent: true
  })
  private materials = []
  private _isActivated: boolean = true

  constructor(configurator: Configurator, constraints?: AxisConstraints) {
    this.configurator = configurator
    if (constraints) {
      this.constraints = constraints
    }

    this.materials = Array(6).fill(this.baseMaterial)

    this.baseGeometry = new THREE.BoxGeometry(1, 1, 1)
    this.baseGeometry.groups = [
      { start: 0, count: 6, materialIndex: 0 }, // +X (right)
      { start: 6, count: 6, materialIndex: 1 }, // -X (left)
      { start: 12, count: 6, materialIndex: 2 }, // +Y (top)
      { start: 18, count: 6, materialIndex: 3 }, // -Y (bottom)
      { start: 24, count: 6, materialIndex: 4 }, // +Z (front)
      { start: 30, count: 6, materialIndex: 5 } // -Z (back)
    ]

    this.meshCube = new THREE.Mesh(this.baseGeometry, this.materials)

    this.meshCube.scale.set(
      this.configurator.hypercubeParametric.params.width + this.offset,
      this.configurator.hypercubeParametric.params.height + this.offset,
      this.configurator.hypercubeParametric.params.length + this.offset
    )

    this.meshCube.updateMatrix()
    this.configurator.sceneWrapper.scene.add(this.meshCube)

    this.createEdgeLines()
  }
  public updateEdgeLinesGeometry() {
    if (!this.edgeLines) return
    this.edgeLines.geometry.dispose()

    this.tempMatrix.makeScale(
      this.meshCube.scale.x,
      this.meshCube.scale.y,
      this.meshCube.scale.z
    )

    const scaledGeometry = this.baseGeometry.clone()
    scaledGeometry.applyMatrix4(this.tempMatrix)

    const edgeGeometry = new THREE.EdgesGeometry(scaledGeometry)
    this.edgeLines.geometry = edgeGeometry
    this.edgeLines.position.copy(this.meshCube.position)
    scaledGeometry.dispose()
  }
  private createEdgeLines() {
    if (this.edgeLines) {
      this.configurator.sceneWrapper.scene.remove(this.edgeLines)
      this.edgeLines.geometry.dispose()
    }

    const scaledGeometry = this.baseGeometry.clone()
    this.tempMatrix.makeScale(
      this.meshCube.scale.x,
      this.meshCube.scale.y,
      this.meshCube.scale.z
    )
    scaledGeometry.applyMatrix4(this.tempMatrix)

    const edgeGeometry = new THREE.EdgesGeometry(scaledGeometry)
    this.edgeLines = new THREE.LineSegments(
      edgeGeometry,
      new THREE.LineBasicMaterial({ color: 0x000000 })
    )

    this.edgeLines.position.copy(this.meshCube.position)
    this.configurator.sceneWrapper.scene.add(this.edgeLines)

    scaledGeometry.dispose()
  }
  private resetHighlight() {
    if (this.hoveredFaceIndex !== null) {
      ;(this.meshCube.material as THREE.Material[])[this.hoveredFaceIndex] =
        this.baseMaterial
      ;(this.meshCube.material as THREE.Material[]).needsUpdate = true
      this.hoveredFaceIndex = null
    }
  }
  private getIntersects(event: PointerEvent) {
    const rect =
      this.configurator.sceneWrapper.appCore.rendererCore.rendererWrapper.renderer.domElement.getBoundingClientRect()
    this.mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
    this.mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1
    this.raycaster.setFromCamera(
      this.mouse,
      this.configurator.sceneWrapper.appCore.rendererCore.cameraWrapper.camera
    )
    return this.raycaster.intersectObject(this.meshCube, false)
  }
  public onPointerDown(event: PointerEvent) {
    if (!this.isActivated) return

    const intersects = this.getIntersects(event)
    if (intersects.length > 0) {
      const face = intersects[0].face
      if (!face) return
      this.isDragging = true
      const rect =
        this.configurator.sceneWrapper.appCore.rendererCore.rendererWrapper.renderer.domElement.getBoundingClientRect()
      this.startMouseX = event.clientX - rect.left
      this.startMouseY = event.clientY - rect.top
      this.startScale.copy(this.meshCube.scale)
      this.startPosition.copy(this.meshCube.position)

      this.selectedFaceNormal = face.normal
        .clone()
        .transformDirection(this.meshCube.matrixWorld)
        .normalize()

      this.configurator.sceneWrapper.appCore.rendererCore.cameraWrapper.controls.enabled =
        false
    }
  }
  public get isActivated() {
    return this._isActivated
  }
  public set isActivated(value) {
    this._isActivated = value
    this.meshCube.visible = value
    this.edgeLines.visible = value
  }
  public onPointerUp() {
    if (!this.isActivated) return
    this.isDragging = false
    this.selectedFaceNormal = null
    this.configurator.sceneWrapper.appCore.rendererCore.cameraWrapper.controls.enabled =
      true
  }

  public updateGizmo(x: number, z: number, y: number) {
    this.meshCube.scale.set(x + this.offset, y + this.offset, z + this.offset)
    this.updateEdgeLinesGeometry()
    this.renderForce()
  }
  public onPointerMove(event: PointerEvent) {
    if (!this.isActivated) return

    const intersects = this.getIntersects(event)

    if (!this.isDragging) {
      this.resetHighlight()
      if (intersects.length > 0) {
        const face = intersects[0].face!
        const materialIndex = face.materialIndex!

        if (this.hoveredFaceIndex !== materialIndex) {
          this.hoveredFaceIndex = materialIndex
          ;(this.meshCube.material as THREE.Material[])[materialIndex] =
            this.highlightMaterial
          ;(this.meshCube.material as THREE.Material[]).needsUpdate = true
        }
      }
    } else if (this.selectedFaceNormal) {
      const rect =
        this.configurator.sceneWrapper.appCore.rendererCore.rendererWrapper.renderer.domElement.getBoundingClientRect()
      const currentMouseX = event.clientX - rect.left
      const currentMouseY = event.clientY - rect.top
      const dx = (currentMouseX - this.startMouseX) / rect.width
      const dy = (currentMouseY - this.startMouseY) / rect.height

      const scaleFactor =
        2 *
        this.configurator.sceneWrapper.appCore.rendererCore.cameraWrapper.camera.position.distanceTo(
          this.meshCube.position
        )
      let dragAmount = (dx - dy) * scaleFactor

      this.tempVector.copy(this.selectedFaceNormal).normalize()
      const newScale = this.startScale.clone()
      const newPosition = this.startPosition.clone()

      if (Math.abs(this.tempVector.y) > 0.9) {
        if (this.tempVector.y > 0) {
          this.tempVector.y *= 0.5
          newScale.y = Math.max(
            this.constraints.y.min,
            Math.min(this.constraints.y.max, this.startScale.y + dragAmount)
          )
          newPosition.y =
            this.startPosition.y + (newScale.y - this.startScale.y) / 2
        } else {
          newScale.y = Math.max(
            this.constraints.y.min,
            Math.min(this.constraints.y.max, this.startScale.y - dragAmount)
          )
          newPosition.y =
            this.startPosition.y - (newScale.y - this.startScale.y) / 2
        }
      } else {
        if (Math.abs(this.tempVector.z) > 0.9) {
          dragAmount = -dragAmount
        }
        newScale.add(this.tempVector.multiplyScalar(dragAmount))
        newScale.x = Math.max(
          this.constraints.x.min,
          Math.min(this.constraints.x.max, newScale.x)
        )
        newScale.y = Math.max(
          this.constraints.y.min,
          Math.min(this.constraints.y.max, newScale.y)
        )
        newScale.z = Math.max(
          this.constraints.z.min,
          Math.min(this.constraints.z.max, newScale.z)
        )
      }

      this.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.setSize(
        newScale.x - this.offset,
        newScale.y - this.offset,
        newScale.z - this.offset
      )

      this.meshCube.scale.copy(newScale)
      this.meshCube.position.copy(newPosition)

      this.updateEdgeLinesGeometry()
    }

    this.renderForce()
  }
  public dispose() {
    if (this.edgeLines) {
      this.configurator.sceneWrapper.scene.remove(this.edgeLines)
      this.edgeLines.geometry.dispose()
    }

    this.baseGeometry.dispose()
    this.baseMaterial.dispose()
    this.highlightMaterial.dispose()
  }
}
