import * as THREE from 'three'

import { Nubbin } from '..'

export abstract class NubbinBase {
  public nubbin!: Nubbin
  public mesh!: THREE.Group
  constructor(nubbin: Nubbin) {
    this.nubbin = nubbin
  }
  public abstract onClick(): void
  public abstract syncSizes(): void
  public abstract update(): boolean
  public show(show: boolean): boolean {
    this.mesh.visible = show
    return this.mesh.visible
  }
}
