import * as THREE from 'three'

import { Nubbin } from './'
import { NubbinBase } from './Base/NubbinBase'
import { loadFBXWithMat } from '../../../../../utils/ThreeUtils'

export class LaserDevice extends NubbinBase {
  public mesh: THREE.Group
  private laserDevices: LaserDeviceItem[] = []

  constructor(nubbin: Nubbin) {
    super(nubbin)
    this.mesh = new THREE.Group()
    this.mesh.name = 'LaserDevice'
    this.mesh.userData = { obj: this }

    this.loadSolarPanel(
      [nubbin.hypercubeParametric.configurator.BASE_URL + 'LaserDevice.fbx'],
      0.25
    )
  }
  private loadSolarPanel = async (files, scale) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBXWithMat(
          file,
          scale,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .rendererCore.useWebGPU,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .isPerformanceMode,
          this.nubbin.hypercubeParametric.configurator.materials.clippingPlanes,
          this.nubbin.hypercubeParametric.configurator.materials.MaterialClass,
          this.nubbin.hypercubeParametric.configurator.materials.nubbinMaterial
        )
      )

      const fbxModels = await Promise.all(loadPromises)
      fbxModels[0].rotation.z = -Math.PI * 0.5
      fbxModels[0].position.y = -0.3

      for (let i = 0; i < 3; ++i) {
        const LaserItem = new LaserDeviceItem(this, i, fbxModels[0].clone(true))
        LaserItem.mesh.position.x = i * 10
        this.laserDevices.push(LaserItem)
        this.mesh.add(LaserItem.mesh)
      }

      // const clonedMesh = fbxModels[0].clone(true);
      // clonedMesh.position.x += 12;
      // this.mesh.add(clonedMesh);

      // this.appendLaser();

      this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.add(
        this.mesh
      )
      this.syncSizes()
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  public syncSizes() {
    this.laserDevices.forEach((item: LaserDeviceItem) => {
      item.syncSizes()
    })
  }
  public toggleVisibility() {
    this.laserDevices.forEach((item: LaserDeviceItem) => {
      item.toggleVisibility()
    })
  }
  public update(): boolean {
    // console.log(this.laserDevices)
    if (this.laserDevices.length === 0) return false

    const results = [...this.laserDevices].map((obj) => obj?.update() ?? false)
    return results.some(Boolean)
  }
  public onClick(): void {
    throw new Error('Method not implemented.')
  }
}

export class LaserDeviceItem {
  public host: LaserDevice

  public mesh: THREE.Group
  private meshLaser: THREE.Mesh | undefined = undefined

  public id = 0

  private hasAnimation = false

  private baseY = 0
  private animationProgress = 0 // 0 ~ 1
  private animationSpeed = 0.02

  constructor(host: LaserDevice, id: number, model: THREE.Group) {
    this.id = id
    this.host = host
    this.mesh = new THREE.Group()
    this.mesh.userData = { obj: this }

    this.loadSolarPanel(model)
  }
  private loadSolarPanel = async (model: THREE.Group) => {
    model.rotation.z = -Math.PI * 0.5
    model.position.y = -0.3
    this.mesh.add(model)

    // const clonedMesh = fbxModels[0].clone(true);
    // clonedMesh.position.x += 12;
    // this.mesh.add(clonedMesh);

    this.appendLaser()

    // this.host.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(
    //   this.mesh
    // )
    this.syncSizes()

    // const fbxModels = await Promise.all(loadPromises);
    // fbxModels[0].rotation.z = -Math.PI * 0.5;
    // fbxModels[0].position.y = -0.3;

    // this.mesh.add(fbxModels[0]);
    // this.appendLaser();

    // this.host.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh);
    // this.syncSizes();
  }
  private appendLaser() {
    const radius = 0.5
    const height = 3.5
    const geometry = new THREE.CylinderGeometry(radius, radius, height, 32)

    geometry.translate(0.0, height * 0.25, 0.0)
    const material =
      this.host.nubbin.hypercubeParametric.configurator.materials
        .laserBarrelMaterial

    const laserOffsetZ = 1.0
    const laserOffsetY = 2.4
    this.meshLaser = new THREE.Mesh(geometry, material)
    this.meshLaser.position.z = laserOffsetZ
    this.meshLaser.position.y = laserOffsetY
    // this.host.addon.hypercubeParametric.configurator.sceneWrapper.scene.add(this.meshLaser);

    this.updateAngle()
    this.mesh.add(this.meshLaser)
    this.mesh.userData.onClick = () => this.onClick()
  }
  public syncSizes() {
    if (this.mesh) {
      if (this.id === 0) {
        this.mesh.position.x =
          this.host.nubbin.hypercubeParametric.params.width * 0.5 -
          this.host.nubbin.hypercubeParametric.params.thickness * 0.5
        this.mesh.position.z =
          this.host.nubbin.hypercubeParametric.params.length * 0.5 -
          this.host.nubbin.hypercubeParametric.params.thickness * 0.5
      } else if (this.id === 1) {
        this.mesh.position.x =
          -this.host.nubbin.hypercubeParametric.params.width * 0.5 +
          this.host.nubbin.hypercubeParametric.params.thickness * 0.5
        this.mesh.position.z =
          -this.host.nubbin.hypercubeParametric.params.length * 0.5 +
          this.host.nubbin.hypercubeParametric.params.thickness * 0.5
      } else if (this.id === 2) {
        this.mesh.position.x =
          this.host.nubbin.hypercubeParametric.params.width * 0.5 -
          this.host.nubbin.hypercubeParametric.params.thickness * 0.5
        this.mesh.position.z =
          -this.host.nubbin.hypercubeParametric.params.length * 0.5 +
          this.host.nubbin.hypercubeParametric.params.thickness * 0.5
      }

      this.mesh.position.y =
        this.host.nubbin.hypercubeParametric.params.height +
        this.host.nubbin.hypercubeParametric.params.groundY

      this.baseY = this.mesh.position.y
    }
  }
  public updateRotation(degree: number = 1.4) {
    this.mesh.rotation.y = degree
  }
  public updateAngle(degree: number = 1.4) {
    const clampedDegree = THREE.MathUtils.clamp(degree, 1, 2)
    this.meshLaser.rotation.x = clampedDegree // THREE.MathUtils.degToRad(clampedDegree);
  }
  public toggleVisibility() {
    this.mesh.visible = !this.mesh.visible
    this.hasAnimation = true
    this.animationProgress = 0
  }
  // public update(): boolean {
  //   if (!this.hasAnimation) return false
  //   this.mesh.position.y += 0.1
  //   console.log(this.mesh)
  //   // this.mesh.material.opacity += 0.05

  //   this.mesh.traverse((child) => {
  //     if ((child as THREE.Mesh).isMesh) {
  //       const mesh = child as THREE.Mesh
  //       const material = mesh.material

  //       if (Array.isArray(material)) {
  //         material.forEach((mat) => {
  //           mat.transparent = true
  //           mat.opacity -= 0.01
  //           mat.needsUpdate = true
  //         })
  //       } else {
  //         material.transparent = true
  //         material.opacity -= 0.01
  //         material.needsUpdate = true
  //       }
  //     }
  //   })

  //   return true
  // }

  public update(): boolean {
    if (!this.hasAnimation) return false

    this.animationProgress += this.animationSpeed
    const t = Math.min(this.animationProgress, 1)
    const isShowing = this.mesh.visible

    const offsetY = 10
    this.mesh.position.y = isShowing
      ? THREE.MathUtils.lerp(this.baseY + offsetY, this.baseY, t)
      : THREE.MathUtils.lerp(this.baseY, this.baseY + offsetY, t)

    const opacity = isShowing
      ? THREE.MathUtils.lerp(0, 1, t)
      : THREE.MathUtils.lerp(1, 0, t)

    this.mesh.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh
        const materials = Array.isArray(mesh.material)
          ? mesh.material
          : [mesh.material]

        materials.forEach((mat) => {
          mat.transparent = true
          mat.opacity = opacity
          mat.needsUpdate = true
        })
      }
    })

    if (t >= 1) {
      this.hasAnimation = false
      return false
    }

    return true
  }
  public onClick() {
    this.host.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      this.mesh
    )
    this.host.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.actionStateProcessor.emitAction(
      'LaserDevice@'
    )
  }
  public disappearLaser() {
    this.hasAnimation = true
    this.meshLaser!.visible = false
  }
}
