import * as THREE from 'three'

import { SceneWrapper } from '..'
import { HypercubeMaterials } from './Materials'
import { DoorInner } from './parts/DoorInner'
import { DoorOuter } from './parts/DoorOuter'
import { DroneDevice } from './parts/DroneDevice'
import { HypercubeStatic } from './parts/HypercubeStatic'
import { SolarPanel } from './parts/SolarPanel'
import { DIRECTION } from '../../../utils/const'
import { loadFBX, getDeepCloneGroup } from '../../../utils/ThreeUtils'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'

export class Hypercube extends MeshWrapperCommon {
  public mesh!: THREE.Mesh

  public hypercubeStatic!: HypercubeStatic
  public droneDevices: DroneDevice[] = []
  public solarPanel!: SolarPanel

  public doorOuter!: DoorOuter
  public doorInnerA!: DoorInner
  public doorInnerB!: DoorInner

  public materials!: HypercubeMaterials

  private _runningDroneDevices = false
  private _hasAnimation = false
  private _visible = true

  private _BASE_URL =
    'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/cube/'
  private _BASE_URL_SUB =
    'https://raw.githubusercontent.com/NamjuLee/data/master/geometry/fbx/'

  public clippingPlanes: THREE.Plane[] = []
  public section: THREE.Mesh

  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)

    this.clippingPlanes = [
      new THREE.Plane(new THREE.Vector3(0, -1, 0), 25)
      // new THREE.Plane(new THREE.Vector3(-1, 0, 0), 0)
    ]

    this.init()
  }
  public init() {
    this.initMaterial()
    this.initPart()
  }
  updateClipingPlane(val: number) {
    this.clippingPlanes[0].constant = val
    this.section.lookAt(this.clippingPlanes[0].normal)
    this.section.position.copy(
      this.clippingPlanes[0].normal
        .clone()
        .multiplyScalar(this.clippingPlanes[0].constant - 0.01)
    )

    // this.section.lookAt(target);

    this.section.position.add(
      this.clippingPlanes[0].normal.clone().multiplyScalar(0.001)
    )
  }
  public initMaterial() {
    this.materials = new HypercubeMaterials(this)
  }
  async initPart() {
    const files = [
      'onlyaCube-clean-static-small.fbx'
      // 'onlyaCube-clean-static.fbx',
      // 'onlyaCube-clean-static-noSkin.fbx',
      // "solarPanel.fbx",
      // "door-B-1.fbx",
      // "door-B-2.fbx",
    ]
    const scale = 0.01
    // console.log("1");
    await this.loadAllModels(files, scale)
    // // console.log("2");
    await this.loadDroneDevice(['top-1-reposition.fbx'], 0.25)
    // // console.log("3");
    await this.loadSolarPanel(['solarPanel.fbx'], scale)

    await this.loadDoorInner(['door-B-1.fbx', 'door-B-2.fbx'], scale)

    await this.loadDoorOuter(['door-A-small.fbx'], scale)

    await this.loadDoorOuterSubstation(['substation-A.fbx'], scale)

    if (!this._visible) {
      this.show(this._visible)
    }
    this.ready = true
  }
  public get BASE_URL() {
    return this._BASE_URL
  }
  public get visible() {
    return this._visible
  }
  public set visible(v) {
    this._visible = v
  }
  public get runningDroneDevices() {
    return this._runningDroneDevices
  }
  public set runningDroneDevices(v: boolean) {
    this._runningDroneDevices = v
  }
  public set angleSolarPanel(v: number) {
    // console.log(v * 0.01);
    this.solarPanel.rotate(v * 0.01)
  }
  public showCamera() {
    this.sceneWrapper.appCore.app.view.showCamera()
  }
  public showGraph() {
    this.sceneWrapper.appCore.app.view.showGraph()
  }
  public showGraphDrone() {
    this.sceneWrapper.appCore.app.view.showGraphDrone()
  }
  public decompose() {
    this.doorOuter.meshGroup.visible = !this.doorOuter.meshGroup.visible
    this.doorInnerA.meshGroup.visible = !this.doorInnerA.meshGroup.visible
    this.doorInnerB.meshGroup.visible = !this.doorInnerB.meshGroup.visible
    this.solarPanel.meshGroup.visible = !this.solarPanel.meshGroup.visible
    this.droneDevices.forEach((device) => {
      device.meshGroup.visible = !device.meshGroup.visible
    })
    this.hypercubeStatic.decompose()
  }
  private loadAllModels = async (files: string[], scale: number) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBX(
          this.BASE_URL + file,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.sceneWrapper.appCore.isPerformanceMode,
          this.clippingPlanes
        )
      )
      const fbxModels = await Promise.all(loadPromises)
      this.hypercubeStatic = new HypercubeStatic(this, fbxModels[0])
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  private loadDroneDevice = async (files, scale) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBX(
          this.BASE_URL + file,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.sceneWrapper.appCore.isPerformanceMode,
          this.clippingPlanes
        )
      )

      const fbxModels = await Promise.all(loadPromises)
      this.droneDevices.push(
        new DroneDevice(this, getDeepCloneGroup(fbxModels[0]), 16.3, 1, -16.4)
      )
      this.droneDevices.push(
        new DroneDevice(this, getDeepCloneGroup(fbxModels[0]), -16.73, 1, -16.4)
      )
      this.droneDevices.push(
        new DroneDevice(this, getDeepCloneGroup(fbxModels[0]), -16.73, 1, 16.5)
      )
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  private loadSolarPanel = async (files, scale) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBX(
          this.BASE_URL + file,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.sceneWrapper.appCore.isPerformanceMode,
          this.clippingPlanes
        )
      )

      const fbxModels = await Promise.all(loadPromises)
      this.solarPanel = new SolarPanel(this, fbxModels[0])
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  private loadDoorInner = async (files, scale) => {
    try {
      const [fbxA, fbxB] = await Promise.all([
        loadFBX(
          `${this.BASE_URL}${files[0]}`,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.sceneWrapper.appCore.isPerformanceMode,
          this.clippingPlanes
        ),
        loadFBX(
          `${this.BASE_URL}${files[1]}`,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.sceneWrapper.appCore.isPerformanceMode,
          this.clippingPlanes
        )
      ])

      this.doorInnerA = new DoorInner(this, fbxA, DIRECTION.Left)
      this.doorInnerB = new DoorInner(this, fbxB, DIRECTION.Right)
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  private loadDoorOuter = async (files, scale) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBX(
          this.BASE_URL + file,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.sceneWrapper.appCore.isPerformanceMode,
          this.clippingPlanes
        )
      )

      const fbxModels = await Promise.all(loadPromises)

      this.doorOuter = new DoorOuter(this, fbxModels[0])
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  private loadDoorOuterSubstation = async (files, scale) => {
    try {
      const loadPromises = files.map((file) =>
        loadFBX(
          this._BASE_URL_SUB + file,
          scale,
          this.sceneWrapper.appCore.rendererCore.useWebGPU,
          this.sceneWrapper.appCore.isPerformanceMode,
          this.clippingPlanes
        )
      )

      const fbxModels = await Promise.all(loadPromises)

      this.doorOuter = new DoorOuter(this, fbxModels[0])
    } catch (error) {
      console.error('fail to load :', error)
    }
  }
  public update() {
    const delta =
      this.sceneWrapper.appCore.rendererCore.rendererWrapper.deltaTime

    const results = [
      ...this.droneDevices.map((d) => d.update()),
      this.solarPanel?.update() ?? false,
      this.doorInnerA?.update() ?? false,
      this.doorInnerB?.update() ?? false,
      this.doorOuter?.update() ?? false,
      this.hypercubeStatic?.update(delta) ?? false
    ]

    this._hasAnimation = results.some((r) => r === true)
    return this._hasAnimation
  }
  public clickDoorInner() {
    this.doorInnerA?.onClick()
    this.doorInnerB?.onClick()
  }
  public clickDoorOuter() {
    this.doorOuter.onClick()
  }
  public show(value: boolean) {
    if (this.hypercubeStatic) this.hypercubeStatic.visible = value
    if (this.solarPanel) this.solarPanel.visible = value
    if (this.doorOuter) this.doorOuter.visible = value
    if (this.doorInnerA) this.doorInnerA.visible = value
    if (this.doorInnerB) this.doorInnerB.visible = value
    this.droneDevices.forEach((device: DroneDevice) => {
      if (device) device.visible = value
    })
    this._visible = value
  }
}
