import * as THREE from 'three'

import { Configurator } from '..'

enum AniState {
  Assembled = 'assembled',
  Decomposed = 'decomposed'
}

type MeshState = {
  mesh: THREE.Mesh | THREE.Group
  startPos: THREE.Vector3
  startRotation: THREE.Euler
  direction: THREE.Vector3
  material: any
  index: number
  isGroup?: boolean
  children?: any[]
  rotationAngle?: number
  rotationAxis?: THREE.Vector3
  hasOpacity?: boolean
}

type MeshGroupOptions = {
  rotation?: number
  direction?: 0 | 1
  hasOpacity?: boolean
}

type MeshGroup = {
  name: string
  meshes: (THREE.Mesh | THREE.Group)[]
  states?: MeshState[]
  offset: number
  options?: MeshGroupOptions
}

type AnimationConfig = {
  duration: number
  interval: number
  distance: number
  fadeInDuration: number
  fadeOutStart: number
}

export class AnimationAssembly {
  private configurator: Configurator
  private meshGroups: MeshGroup[] = []
  private rafId?: number
  private startTime = 0
  private targetState: AniState = AniState.Assembled

  private renderForceIntervalId?: number
  private renderForceCount = 0

  private config: AnimationConfig = {
    duration: 1000,
    interval: 200,
    distance: 30,
    fadeInDuration: 0.5,
    fadeOutStart: 0.5
  }
  constructor(configurator: Configurator) {
    this.configurator = configurator
  }
  public initPost() {
    const hc = this.configurator.hypercubeParametric
    const nubbin = hc.nubbin

    this.addMeshGroup('paPanel', [nubbin.panel?.mesh], 0, { rotation: 90 })
    this.addMeshGroup('drone', [nubbin.droneReadyNet?.mesh], 500)
    this.addMeshGroup(
      'cantileverStarlink',
      [...nubbin.cantileverStarlink?.starLink.map((starlink) => starlink.mesh)],
      700,
      { rotation: 90, direction: 1 }
    )
    this.addMeshGroup('droneNest', [nubbin.cantileverDrone?.mesh], 800)
    this.addMeshGroup('cellular', [nubbin.cellular?.mesh], 900)
    this.addMeshGroup('disco', [nubbin.disco?.mesh], 1000)
    this.addMeshGroup('droneNest', [nubbin.droneDevice?.mesh], 1100)
    this.addMeshGroup(
      'laserDevice',
      [...nubbin.laserDevice?.mesh.children],
      1200,
      {
        direction: 1,
        rotation: 90
      }
    )
    this.addMeshGroup('starlink', [nubbin.cantileverStarlink?.mesh], 1500)

    this.addMeshGroup('bars', hc.exoSkeletonMeshes.bars, 2000)
    this.addMeshGroup('corners', hc.exoSkeletonMeshes.corners, 2500, {
      rotation: 180,
      direction: 1
    })
    this.addMeshGroup('columns', hc.exoSkeletonMeshes.columns, 3000, {
      rotation: 90,
      direction: 1
    })
    this.addMeshGroup('camera', hc.exoSkeletonMeshes.cameras, 4200)
    this.addMeshGroup('rollingDoors', hc.rollingDoors.mesh, 4500)
    this.addMeshGroup('walls', hc.wall.mesh, 5000, { rotation: 90 })

    this.addMeshGroup('server', [...hc.server.mesh.children], 6000, {
      rotation: 90,
      direction: 1,
      hasOpacity: false
    })
    this.addMeshGroup('floor', [hc.floorGrids.mesh], 7800)
    this.addMeshGroup('foundation', [...hc.foundationBase.mesh?.children], 8500)
  }
  public addMeshGroup(
    name: string,
    meshes: (THREE.Mesh | THREE.Group)[] | undefined,
    offset = 0,
    options?: MeshGroupOptions
  ) {
    if (!meshes?.length) return
    this.meshGroups.push({ name, meshes, offset, options })
  }
  public toggleAssemblyDisassemblyHC() {
    this.targetState =
      this.targetState === AniState.Assembled
        ? AniState.Decomposed
        : AniState.Assembled
    this.start()
  }
  public decompose() {
    if (this.targetState === AniState.Assembled) {
      this.targetState = AniState.Decomposed
      this.start()
    }
  }
  public assemble() {
    if (this.targetState === AniState.Decomposed) {
      this.targetState = AniState.Assembled
      this.start()
    }
  }
  public getState(): AniState {
    return this.targetState
  }
  public updateConfig(config: Partial<AnimationConfig>) {
    this.config = { ...this.config, ...config }
  }
  private start() {
    this.clearRenderForceInterval()
    this.configurator.hypercubeParametric.rollingDoors.toggleDoorAll()

    this.renderForceCount = 0
    this.renderForceIntervalId = window.setInterval(() => {
      this.configurator.sceneWrapper.renderForce()
      this.renderForceCount++

      if (this.renderForceCount >= 4) {
        this.clearRenderForceInterval()
      }
    }, 2000)

    this.meshGroups.forEach((group) => {
      if (!group.states) {
        this.initMeshGroup(group)
      }
    })
    this.startTime = performance.now()

    if (!this.rafId) {
      this.rafId = requestAnimationFrame(this.animate)
    }
  }
  private stop() {
    if (this.rafId) {
      cancelAnimationFrame(this.rafId)
      this.rafId = undefined
    }
  }
  private clearRenderForceInterval() {
    if (this.renderForceIntervalId !== undefined) {
      clearInterval(this.renderForceIntervalId)
      this.renderForceIntervalId = undefined
    }
    this.renderForceCount = 0
  }
  private initMeshGroup(group: MeshGroup) {
    if (!group.meshes?.length) return

    const center = this.calculateGroupCenter(group.meshes)

    group.states = group.meshes.map((mesh, index) => {
      const isGroup = mesh instanceof THREE.Group
      const { material, children } = this.extractMaterials(mesh, isGroup)

      this.initializeMaterial(material)

      const startPos = mesh.position.clone()
      const startRotation = mesh.rotation.clone()
      const direction = this.calculateDirection(group.options, startPos, center)
      const { rotationAngle, rotationAxis } = this.calculateRotation(
        group.options,
        mesh,
        isGroup
      )

      return {
        mesh,
        startPos,
        startRotation,
        direction,
        material,
        index,
        isGroup,
        children: isGroup ? children : undefined,
        rotationAngle,
        rotationAxis,
        hasOpacity: group.options?.hasOpacity ?? true
      }
    })
  }
  private calculateGroupCenter(
    meshes: (THREE.Mesh | THREE.Group)[]
  ): THREE.Vector3 {
    const center = new THREE.Vector3()
    meshes.forEach((mesh) => center.add(mesh.position))
    center.divideScalar(meshes.length)
    return center
  }
  private extractMaterials(mesh: THREE.Mesh | THREE.Group, isGroup: boolean) {
    let material: any
    const children: any[] = []

    if (isGroup) {
      mesh.traverse((child: any) => {
        if (child.material) {
          if (Array.isArray(child.material)) {
            children.push(...child.material)
          } else {
            children.push(child.material)
          }
        }
      })
      material = children[0] || {}
    } else {
      material = Array.isArray(mesh.material) ? mesh.material[0] : mesh.material
    }

    return { material, children }
  }
  private initializeMaterial(material: any) {
    material.opacity ??= 1
    material.transparent ??= false
    material.depthWrite = true
  }
  private calculateDirection(
    options: MeshGroupOptions | undefined,
    startPos: THREE.Vector3,
    center: THREE.Vector3
  ): THREE.Vector3 {
    if (options?.direction === 0) {
      return new THREE.Vector3(0, 1, 0)
    }

    if (options?.direction === 1) {
      return new THREE.Vector3(
        startPos.x - center.x,
        0,
        startPos.z - center.z
      ).normalize()
    }

    return startPos.y < center.y
      ? new THREE.Vector3(
          startPos.x - center.x,
          0,
          startPos.z - center.z
        ).normalize()
      : new THREE.Vector3(0, 1, 0)
  }
  private calculateRotation(
    options: MeshGroupOptions | undefined,
    mesh: THREE.Mesh | THREE.Group,
    isGroup: boolean
  ): { rotationAngle?: number; rotationAxis?: THREE.Vector3 } {
    if (options?.rotation === undefined) {
      return {}
    }

    const rotationAngle = THREE.MathUtils.degToRad(options.rotation)
    let rotationAxis: THREE.Vector3 | undefined

    if (mesh.geometry) {
      rotationAxis = this.getRotationAxisFromGeometry(
        mesh.geometry as THREE.BufferGeometry
      )
    } else if (isGroup) {
      rotationAxis = this.getRotationAxisFromGroup(mesh)
    }

    return {
      rotationAngle,
      rotationAxis: rotationAxis || new THREE.Vector3(0, 1, 0)
    }
  }
  private getRotationAxisFromGeometry(
    geometry: THREE.BufferGeometry
  ): THREE.Vector3 | undefined {
    geometry.computeBoundingBox()
    const bbox = geometry.boundingBox

    if (!bbox) return undefined

    const sizeX = Math.abs(bbox.max.x - bbox.min.x)
    const sizeY = Math.abs(bbox.max.y - bbox.min.y)
    const sizeZ = Math.abs(bbox.max.z - bbox.min.z)

    if (sizeX >= sizeY && sizeX >= sizeZ) {
      return new THREE.Vector3(1, 0, 0)
    } else if (sizeY >= sizeX && sizeY >= sizeZ) {
      return new THREE.Vector3(0, 1, 0)
    } else {
      return new THREE.Vector3(0, 0, 1)
    }
  }
  private getRotationAxisFromGroup(
    mesh: THREE.Group
  ): THREE.Vector3 | undefined {
    let rotationAxis: THREE.Vector3 | undefined

    mesh.traverse((child: any) => {
      if (!rotationAxis && child.geometry) {
        const geometry = child.geometry as THREE.BufferGeometry
        geometry.computeBoundingBox()
        const bbox = geometry.boundingBox

        if (bbox) {
          const sizeX = Math.abs(bbox.max.x - bbox.min.x)
          const sizeY = Math.abs(bbox.max.y - bbox.min.y)
          const sizeZ = Math.abs(bbox.max.z - bbox.min.z)

          if (sizeX >= sizeY && sizeX >= sizeZ) {
            rotationAxis = new THREE.Vector3(0, 0, 1)
          } else if (sizeY >= sizeX && sizeY >= sizeZ) {
            rotationAxis = new THREE.Vector3(0, 1, 0)
          } else {
            rotationAxis = new THREE.Vector3(1, 0, 0)
          }
        }
      }
    })

    return rotationAxis
  }
  private easeInOut(t: number): number {
    return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2
  }
  private updateMeshState(
    state: MeshState,
    progress: number,
    isDecomposing: boolean
  ) {
    const {
      mesh,
      startPos,
      startRotation,
      direction,
      material,
      isGroup,
      children,
      rotationAngle,
      rotationAxis,
      hasOpacity
    } = state
    const { distance, fadeInDuration, fadeOutStart } = this.config

    this.updatePosition(
      mesh,
      startPos,
      direction,
      progress,
      distance,
      isDecomposing
    )
    this.updateRotation(
      mesh,
      startRotation,
      rotationAngle,
      rotationAxis,
      progress,
      isDecomposing
    )

    if (hasOpacity) {
      const targetOpacity = this.calculateOpacity(
        progress,
        isDecomposing,
        fadeInDuration,
        fadeOutStart
      )
      this.updateMaterials(material, mesh, isGroup, children, targetOpacity)
      this.updateShadows(mesh, isGroup, targetOpacity >= 0.99)
    }
  }
  private updatePosition(
    mesh: THREE.Mesh | THREE.Group,
    startPos: THREE.Vector3,
    direction: THREE.Vector3,
    progress: number,
    distance: number,
    isDecomposing: boolean
  ) {
    const moveProgress = isDecomposing ? progress : 1 - progress
    mesh.position
      .copy(startPos)
      .addScaledVector(direction, moveProgress * distance)
  }
  private updateRotation(
    mesh: THREE.Mesh | THREE.Group,
    startRotation: THREE.Euler,
    rotationAngle: number | undefined,
    rotationAxis: THREE.Vector3 | undefined,
    progress: number,
    isDecomposing: boolean
  ) {
    if (rotationAngle !== undefined && rotationAxis) {
      const rotProgress = isDecomposing ? progress : 1 - progress
      const currentAngle = rotProgress * rotationAngle

      mesh.rotation.copy(startRotation)
      mesh.rotateOnAxis(rotationAxis, currentAngle)
    }
  }

  private calculateOpacity(
    progress: number,
    isDecomposing: boolean,
    fadeInDuration: number,
    fadeOutStart: number
  ): number {
    if (isDecomposing) {
      return progress < fadeOutStart
        ? 1
        : 1 - (progress - fadeOutStart) / (1 - fadeOutStart)
    } else {
      return progress < fadeInDuration ? progress / fadeInDuration : 1
    }
  }
  private updateMaterials(
    material: any,
    mesh: THREE.Mesh | THREE.Group,
    isGroup: boolean | undefined,
    children: any[] | undefined,
    targetOpacity: number
  ) {
    const isOpaque = targetOpacity >= 0.99

    material.opacity = targetOpacity
    material.transparent = !isOpaque
    material.depthWrite = isOpaque

    const materialsToUpdate =
      isGroup && children
        ? children
        : Array.isArray(mesh.material)
          ? mesh.material
          : [material]

    materialsToUpdate.forEach((mat: any) => {
      mat.opacity = targetOpacity
      mat.transparent = !isOpaque
      mat.depthWrite = isOpaque
      mat.needsUpdate = true
    })
  }
  private updateShadows(
    mesh: THREE.Mesh | THREE.Group,
    isGroup: boolean | undefined,
    isOpaque: boolean
  ) {
    if (isGroup) {
      mesh.traverse((child: any) => {
        if (child.isMesh) {
          child.castShadow = isOpaque
          child.receiveShadow = isOpaque
        }
      })
    } else {
      mesh.castShadow = isOpaque
      mesh.receiveShadow = isOpaque
    }
  }
  private finalizeMeshState(state: MeshState) {
    const { material, mesh, isGroup, children, startRotation, hasOpacity } =
      state

    if (this.targetState === AniState.Assembled) {
      mesh.rotation.copy(startRotation)

      if (hasOpacity) {
        this.resetMaterial(material)

        const materialsToUpdate =
          isGroup && children
            ? children
            : Array.isArray(mesh.material)
              ? mesh.material
              : []

        materialsToUpdate.forEach((mat: any) => this.resetMaterial(mat))

        this.resetShadows(mesh, isGroup)
      }

      mesh.visible = true
    } else {
      if (hasOpacity) {
        material.needsUpdate = true
      } else {
        mesh.visible = false
      }
    }
  }
  private resetMaterial(material: any) {
    material.opacity = 1
    material.transparent = false
    material.depthWrite = true
    material.needsUpdate = true
  }
  private resetShadows(
    mesh: THREE.Mesh | THREE.Group,
    isGroup: boolean | undefined
  ) {
    if (isGroup) {
      mesh.traverse((child: any) => {
        if (child.isMesh) {
          child.castShadow = true
          child.receiveShadow = true
        }
      })
    } else {
      mesh.castShadow = true
      mesh.receiveShadow = true
    }
  }
  private animate = (now: number) => {
    const isDecomposing = this.targetState === AniState.Decomposed
    const stillAnimating = this.animateGroups(now, isDecomposing)

    if (stillAnimating) {
      this.rafId = requestAnimationFrame(this.animate)
      return
    }

    this.meshGroups.forEach((group) => {
      group.states?.forEach((state) => this.finalizeMeshState(state))
    })

    this.rafId = undefined
  }

  private animateGroups(now: number, isDecomposing: boolean): boolean {
    let stillAnimating = false
    const maxOffset = Math.max(...this.meshGroups.map((g) => g.offset))

    this.meshGroups.forEach((group) => {
      if (!group.states) return

      group.states.forEach((state) => {
        const groupDelay = isDecomposing
          ? group.offset
          : maxOffset - group.offset
        const delay = groupDelay + state.index * this.config.interval
        const localTime = now - this.startTime - delay

        if (localTime < 0) {
          stillAnimating = true
          return
        }

        if (!isDecomposing && !state.hasOpacity && localTime < 16) {
          state.mesh.visible = true
        }

        const t = THREE.MathUtils.clamp(localTime / this.config.duration, 0, 1)
        const eased = this.easeInOut(t)

        this.updateMeshState(state, eased, isDecomposing)

        if (isDecomposing && !state.hasOpacity && t >= 1) {
          state.mesh.visible = false
        }

        if (t < 1) stillAnimating = true
      })
    })

    return stillAnimating
  }
  public dispose() {
    this.clearRenderForceInterval()
    this.stop()

    this.meshGroups.forEach((group) => {
      if (group.states) {
        group.states.forEach((state) => {
          state.startPos = null as any
          state.startRotation = null as any
          state.direction = null as any
          state.material = null
          state.children = undefined
          state.rotationAxis = undefined
        })
        group.states = undefined
      }
    })
    this.meshGroups = []
  }
}
