import { Mesh } from 'three'

import { AppCommon } from '.'
import { DownloadJSON } from '../../utils'
import { Configurator } from '../SceneWrapper/Configurator'

export class CommonHypercubeParametric {
  public appCommon: AppCommon
  private configurator: Configurator
  constructor(appCommon: AppCommon) {
    this.appCommon = appCommon
    this.configurator = this.appCommon.appCore.sceneWrapper.configurator
  }

  public updateLogParameters() {
    const hypercubeParametric = this.configurator.hypercubeParametric
    if (this.appCommon.appCore.app.view && hypercubeParametric) {
      this.appCommon.appCore.app.view.metadataPosition.textContent =
        hypercubeParametric.params.getLog(2)
    }
  }
  public onFocus(mesh: Mesh, distance = 2.5) {
    this.appCommon.appCore.rendererCore.cameraWrapper.cameraAnimator.onFocusObject(
      mesh,
      distance
    )
  }
  public setSize(x: number, y: number, z: number) {
    this.configurator.hypercubeParametric?.setSize(x, y, z)
    this.updatePost()
  }
  public setWidthParametricHC(value: number) {
    this.configurator.hypercubeParametric?.setWidth(value)
    this.updatePost()
  }
  public setLengthParametricHC(value: number) {
    this.configurator.hypercubeParametric?.setLength(value)
    this.updatePost()
  }
  public setHeightParametricHC(value: number) {
    this.configurator.hypercubeParametric?.setHeight(value)
    this.updatePost()
  }
  public setSizeSkeletonParametricHC(value: number) {
    this.configurator.hypercubeParametric?.setThickness(value)
    this.updatePost()
  }
  public setSizeCameraHC(value: number) {
    this.configurator.hypercubeParametric?.setCameraSize(value)
    this.updatePost()
  }
  public setSizeRollingPanel(value: number) {
    // console.log('setSizeRollingPanel', value)
    this.configurator.hypercubeParametric?.setHeightRollingPanel(value)

    this.updatePost()
  }
  public setSizeGapRollingPanel(value: number) {
    this.configurator.hypercubeParametric?.setGapRollingPanel(value)
  }
  public setSizeGridFloor(value: number) {
    this.configurator.hypercubeParametric?.setSizeGridFloor(value)

    this.updatePost()
  }
  public toggleClippingMode(value: boolean) {
    this.configurator.toggleClippingMode(value)
    this.appCommon.renderForce()
  }
  public toggleXrayParametricModel(value: boolean) {
    this.configurator.toggleXrayParametricModel(value)
    this.appCommon.renderForce()
  }
  public rotateDroneDoor(v: number) {
    this.configurator.hypercubeParametric.nubbin.cantileverDrone?.rotationDoor(
      v
    )
    this.appCommon.renderForce()
  }
  public updateXrayParametricModel() {
    this.configurator.updateXrayView()
    this.appCommon.renderForce()
  }
  public setClippingYParametricHC(value: number) {
    this.configurator.clippingController.updateYClipping(value)
    this.appCommon.renderForce()
  }
  public setClippingXParametricHC(value: number) {
    this.configurator.clippingController.updateXClipping(value)
    this.appCommon.renderForce()
  }
  public setClippingZParametricHC(value: number) {
    this.configurator.clippingController.updateZClipping(value)
    this.appCommon.renderForce()
  }
  public downloadParameter() {
    const param = this.configurator.getParameter()
    DownloadJSON(param)
  }
  public openSlidingDoor() {
    this.configurator.hypercubeParametric.wall.openDoorSliding()
    this.appCommon.renderForce()
  }
  public toggleGizmo() {
    this.configurator.toggleGizmo()
    this.appCommon.renderForce()
  }
  public runOptimization() {
    const result = this.configurator.hypercubeParametric.runOptimization()
    this.setWidthParametricHC(result.width)
    this.setLengthParametricHC(result.length)
    this.setHeightParametricHC(result.height)
  }
  public setVolumeOptimization(volumeTarge: number) {
    this.configurator.hypercubeParametric.params.volumeTarget = volumeTarge
    this.runOptimization()
  }
  public openOuter() {
    this.configurator.hypercubeParametric.rollingDoors.toggleRollingDoorByID(
      'wall-rolling-front'
    )
    this.appCommon.renderForce()
  }
  public openDoorSliding(isOpen: boolean) {
    this.configurator.hypercubeParametric.rollingDoors.openDoorSliding(isOpen)
    this.appCommon.renderForce()
  }
  public toggleAddon() {
    this.configurator.hypercubeParametric.toggleAddon()
    this.appCommon.renderForce()
  }
  public toggleLaser() {
    this.configurator.hypercubeParametric.toggleLaser()
    this.appCommon.renderForce()
  }
  public openSelectedRollingDoor(name: string) {
    this.configurator.hypercubeParametric.rollingDoors.toggleRollingDoorByID(
      name
    )
  }
  public openSelectedSlidingDoor(name: string) {
    this.configurator.hypercubeParametric.wall.toggleSlidingDoorByID(name)
  }
  private updatePost() {
    this.appCommon.renderForce()
    this.updateXrayParametricModel()
    this.updateLogParameters()
  }
}
