import * as THREE from 'three'

import { HypercubeParametric } from '..'
import { getGridFloor } from '../../../../../utils/ThreeUtils'
import { Parameters } from '../Parameters/Parameters'

export class FloorGrids {
  public hypercubeParametric: HypercubeParametric
  public mesh: THREE.Group

  public scale: number = 1
  private dimension: Parameters

  constructor(hypercubeParametric: HypercubeParametric) {
    this.hypercubeParametric = hypercubeParametric
    this.dimension = this.hypercubeParametric.params
    this.init()
  }
  public init(): void {
    const majorThickness = 0.5
    this.mesh = getGridFloor({
      xSize: this.dimension.width - this.dimension.thickness * 2,
      zSize: this.dimension.length - this.dimension.thickness * 2,
      yHight: this.dimension.thickness,
      ground: this.dimension.groundY,
      xOff: 0.8 * this.scale,
      zOff: 1.5 * this.scale,
      baseThickness: majorThickness / 3,
      majorThickness: majorThickness,
      majorInterval: 9,
      baseMaterial:
        this.hypercubeParametric.configurator.materials.gridFloorMaterial
    })
    this.hypercubeParametric.configurator.sceneWrapper.scene.add(this.mesh)
  }

  public syncSizes(): void {
    this.rebuild()
  }
  public rebuild(): void {
    this.cleanup()
    this.init()
  }
  private cleanup(): void {
    this.hypercubeParametric.configurator.sceneWrapper.scene.remove(this.mesh)
  }
}
