import * as THREE from 'three'

import { SceneWrapper } from '..'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'

export class PebblesGround extends MeshWrapperCommon {
  public mesh!: THREE.Group

  private x = -0.5
  private z = -9.5
  private zGround = -18
  private width = 270
  private length = 210
  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)
    this.mesh = new THREE.Group()
    this.mesh.name = 'mesh-ground-pebble-environment'
    this.sceneWrapper.scene.add(this.mesh)
    this.init()
  }
  public async init() {
    await this.initMap()

    if (!this.sceneWrapper.appCore.isPerformanceMode) {
      this.initPebbleMesh()
    }

    this.ready = true
  }
  public async initMap() {
    try {
      const loader = new THREE.TextureLoader()
      const baseURL = '/hypercube-asset/model/texture/'

      const [diffuseMap, normalMap, roughnessMap, aoMap, heightMap] =
        await Promise.all([
          loader.loadAsync(baseURL + 'Pebbles-01-map.jpg'),
          loader.loadAsync(baseURL + 'Pebbles-01-normal.jpg'),
          loader.loadAsync(baseURL + 'Pebbles-01-roughness.jpg'),
          loader.loadAsync(baseURL + 'Pebbles-01-ao.jpg'),
          loader.loadAsync(baseURL + 'Pebbles-01-height.jpg')
        ])

      const repeatScale = 15
      ;[diffuseMap, normalMap, roughnessMap, aoMap, heightMap].forEach(
        (tex) => {
          tex.wrapS = THREE.RepeatWrapping
          tex.wrapT = THREE.RepeatWrapping
          tex.repeat.set(repeatScale, repeatScale)
        }
      )
      diffuseMap.colorSpace = THREE.SRGBColorSpace
      normalMap.colorSpace = THREE.NoColorSpace

      const geoSegs = 500
      const geometry = new THREE.PlaneGeometry(
        this.width,
        this.length,
        geoSegs,
        geoSegs
      )

      geometry.setAttribute('uv2', geometry.attributes.uv)

      const material = new THREE.MeshStandardMaterial({
        map: diffuseMap,
        normalMap,
        normalScale: new THREE.Vector2(0.5, 0.5),

        roughnessMap,
        roughness: 0.5,

        aoMap,
        aoMapIntensity: 9.5,

        displacementMap: heightMap,
        displacementScale: 0.85,
        displacementBias: -0.1,

        metalness: 0.0
      })

      const floor = new THREE.Mesh(geometry, material)
      floor.receiveShadow = true
      floor.castShadow = false
      floor.rotation.x = -Math.PI * 0.5
      floor.position.set(this.x, this.zGround, this.z)

      this.mesh.add(floor)
    } catch (error) {
      console.error('Failed to initialize floor:', error)
      this.createFallbackFloor()
    }
  }
  private createFallbackFloor() {
    const geometry = new THREE.PlaneGeometry(this.width, this.length)
    const material = new THREE.MeshStandardMaterial({
      color: 0x808080,
      roughness: 0.8,
      metalness: 0.0
    })

    const floor = new THREE.Mesh(geometry, material)
    floor.receiveShadow = true
    floor.rotation.x = -Math.PI * 0.5
    floor.position.y = this.zGround
    // console.log('Fallback floor created')
  }

  initPebbleMesh() {
    const pebbleGeo = new THREE.DodecahedronGeometry(0.3, 0)
    // const highDetailGeo = new THREE.DodecahedronGeometry(0.1, 1)
    // const mediumDetailGeo = new THREE.DodecahedronGeometry(0.1, 0)
    // const pebbleGeo = new THREE.TetrahedronGeometry(0.5)

    // Pebble colors
    const colors = [
      // light gray
      0xe0e0e0, 0xd5d5d5, 0xcccccc, 0xdadada,
      // mid light gray
      0xb8b8b8, 0xaaaaaa, 0xbfbfbf, 0xb0b0b0,
      // mid gray
      0x9d9d9d, 0x929292, 0xa3a3a3, 0x989898,
      // mid dark gray
      0x7f7f7f, 0x757575, 0x858585, 0x7a7a7a,
      // dark gray
      // 0x606060, 0x5a5a5a, 0x666666, 0x5e5e5e,
      // cool gray
      0xa8b0b8, 0x9ca4ac, 0xb0b8c0, 0xa0a8b0,
      // warm gray
      0xc0bcb8, 0xb5b1ad, 0xc5c1bd, 0xbab6b2
    ]

    const pebbleCount = 5000
    const material = new THREE.MeshStandardMaterial({
      roughness: 0.7,
      metalness: 0.1,
      flatShading: true,
      dithering: false
    })

    const instancedMesh = new THREE.InstancedMesh(
      pebbleGeo,
      material,
      pebbleCount
    )
    // instancedMesh.castShadow = true
    instancedMesh.receiveShadow = true
    instancedMesh.frustumCulled = true
    instancedMesh.matrixAutoUpdate = false
    instancedMesh.layers.set(1)
    instancedMesh.raycast = () => {}

    const dummy = new THREE.Object3D()
    const color = new THREE.Color()

    for (let i = 0; i < pebbleCount; i++) {
      const x = (Math.random() - 0.5) * this.width + this.x
      const z = (Math.random() - 0.5) * this.length + this.z
      const y = this.zGround + 0.1

      dummy.position.set(x, y, z)
      dummy.rotation.set(
        Math.random() * Math.PI,
        Math.random() * Math.PI,
        Math.random() * Math.PI
      )

      const scale = 0.5 + Math.random() * 1.5
      dummy.scale.set(
        scale * (0.8 + Math.random() * 0.4),
        scale * (0.6 + Math.random() * 0.4),
        scale * (0.8 + Math.random() * 0.4)
      )

      dummy.updateMatrix()
      instancedMesh.setMatrixAt(i, dummy.matrix)

      color.setHex(colors[Math.floor(Math.random() * colors.length)])
      instancedMesh.setColorAt(i, color)
    }

    instancedMesh.instanceMatrix.needsUpdate = true
    if (instancedMesh.instanceColor) {
      instancedMesh.instanceColor.needsUpdate = true
    }

    // this.sceneWrapper.scene.add(instancedMesh)
    this.mesh.add(instancedMesh)
  }
  public show(value: boolean) {
    if (this.mesh) {
      this.mesh.visible = value
    }
  }
}
