import * as THREE from 'three'
// import { RGBELoader } from 'three/addons/loaders/RGBELoader.js'
import { GroundedSkybox } from 'three/addons/objects/GroundedSkybox.js'
import { HDRLoader } from 'three/examples/jsm/loaders/HDRLoader.js'

import { SceneWrapper } from '..'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'

export class SkyPanorama extends MeshWrapperCommon {
  public mesh!: THREE.Group

  public skyboxDome: GroundedSkybox

  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)
    this.mesh = new THREE.Group()
    this.init()
  }
  async init() {
    const hdrLoader = new HDRLoader()
    const pathHDRI =
      'https://raw.githubusercontent.com/NamjuLee/data/master/map/outsiteSmall.hdr'
    // process.env.PUBLIC_URL + '/static/data/model/map/VizPeople_non_commercial_hdr_v1_03.hdr'

    const envMap = await hdrLoader.loadAsync(pathHDRI)
    envMap.mapping = THREE.EquirectangularReflectionMapping

    this.skyboxDome = new GroundedSkybox(envMap, 28, 600)
    this.skyboxDome.receiveShadow = false
    this.skyboxDome.castShadow = false
    this.skyboxDome.position.y += 10
    // console.log(this.skyboxDome)

    this.mesh.add(this.skyboxDome)
    this.sceneWrapper.scene.add(this.mesh)

    // const sphereGeometry = new THREE.SphereGeometry(500, 64, 64)
    // const sphereMaterial = new THREE.MeshBasicMaterial({
    //   color: 0xffffff,
    //   side: THREE.BackSide,
    //   transparent: true,
    //   opacity: 1.0
    // })
    // this.whitebackgroundDome = new THREE.Mesh(sphereGeometry, sphereMaterial)
    // this.whitebackgroundDome.receiveShadow = false
    // this.whitebackgroundDome.castShadow = false
    // this.sceneWrapper.scene.add(this.whitebackgroundDome)
    this.ready = true
  }
  public toggleHDRIBackground(value: boolean) {
    this.sceneWrapper.appCore.rendererCore.toggleHDRIBackground(value)
  }
  public show(value: boolean) {
    if (!this.skyboxDome) return
    this.skyboxDome.visible = value
  }
}
