import * as THREE from 'three'

import { SceneWrapper } from '..'
import {
  getGroundBasic,
  createStudioEnvironment,
  createStudioEnvironmentWebGPU,
  easeInOut
} from '../../../utils/ThreeUtils'
import { MeshWrapperCommon } from '../base/MeshWrapperCommon'

export class StudioEnv extends MeshWrapperCommon {
  public meshSphere!: THREE.Mesh
  public meshFloor!: THREE.Mesh

  public mode = {
    light: { bg: 0xf4f4f4, floor: 0xffffff, tuningValue: 1 },
    dark: { bg: 0x8f8f8f, floor: 0x333333, tuningValue: 2.2 },
    purple: { bg: 0x9695a1, floor: 0x464555, tuningValue: 1.76 }
  }

  private modeKeys: Array<keyof typeof this.mode> = ['light', 'dark'] // , 'purple']
  private currentModeIndex = 0
  private floorAnimationId: number | null = null

  constructor(sceneWrapper: SceneWrapper) {
    super(sceneWrapper)

    this.init()
  }
  public init() {
    const colorsTheme = this.mode.light

    this.getStudioEnvironment(colorsTheme)

    this.meshFloor = getGroundBasic(
      this.sceneWrapper.groundY,
      colorsTheme.floor
    )

    this.meshFloor.castShadow = false
    this.meshFloor.receiveShadow = true
    this.meshFloor.name = 'mesh-ground-studio-environment'
    this.meshFloor.position.y -= 0.001
    this.sceneWrapper.scene.add(this.meshFloor)

    // this.sceneWrapper.configurator.xrayViewController.push(this.meshFloor)

    this.ready = true
  }
  public getStudioEnvironment(colors: {
    bg: number
    floor: number
    tuningValue: number
  }) {
    if (this.sceneWrapper.appCore.rendererCore.useWebGPU) {
      this.meshSphere = createStudioEnvironmentWebGPU(
        colors.floor,
        colors.tuningValue
      )
    } else {
      this.meshSphere = createStudioEnvironment(colors.bg)
    }

    this.meshSphere.castShadow = false
    this.meshSphere.receiveShadow = false
    this.sceneWrapper.scene.add(this.meshSphere)
    // }
  }
  public toggleTheme() {
    this.currentModeIndex = (this.currentModeIndex + 1) % this.modeKeys.length

    const currentMode = this.modeKeys[this.currentModeIndex]
    const colors = this.mode[currentMode]

    this.updateColor(colors)
    return currentMode
  }
  public updateColor(colors: { bg: number; floor: number }) {
    if (this.meshSphere) {
      this.sceneWrapper.scene.remove(this.meshSphere)

      this.getStudioEnvironment(colors)
    }

    if (this.meshFloor?.material) {
      ;(this.meshFloor.material as THREE.MeshBasicMaterial).color =
        new THREE.Color(colors.floor)
    }
  }
  public showFloorAnimation(target: number, duration = 1000) {
    if (!this.meshFloor) return

    const material = this.meshFloor.material as THREE.Material & {
      opacity: number
      transparent: boolean
    }

    material.transparent = true
    material.needsUpdate = true

    if (this.floorAnimationId !== null) {
      cancelAnimationFrame(this.floorAnimationId)
    }

    const startOpacity = material.opacity
    const startTime = performance.now()

    const animate = (now: number) => {
      const elapsed = now - startTime
      const t = Math.min(elapsed / duration, 1)

      material.opacity = startOpacity + (target - startOpacity) * easeInOut(t)

      if (material.opacity < 0.02) this.showFloor(false)
      if (material.opacity > 0.95) this.showFloor(true)
      material.needsUpdate = true
      this.floorAnimationId = t < 1 ? requestAnimationFrame(animate) : null
    }

    this.floorAnimationId = requestAnimationFrame(animate)
  }
  public show(value: boolean) {
    this.showSky(value)
    this.showFloor(value)
  }
  public showFloor(value: boolean) {
    if (this.meshFloor) {
      this.meshFloor.visible = value
    }
  }
  public showSky(value: boolean) {
    if (this.meshSphere) {
      this.meshSphere.visible = value
    }
  }
  public destroy() {
    if (this.floorAnimationId !== null) {
      cancelAnimationFrame(this.floorAnimationId)
      this.floorAnimationId = null
    }
  }
}
