import { APIInterface } from './APIInterface'
import { AppCore } from './AppCore'
import { RendererCore } from './RendererCore'
import { CLICK_TYPE, ENVIRONMENT_TYPE, COLOR_MAP_TYPE } from './utils/const'
import { View } from './View'

export { CLICK_TYPE, ENVIRONMENT_TYPE, COLOR_MAP_TYPE } from './utils/const'

export interface AppHypercube3dInitParams {
  divID: string

  environmentType?: ENVIRONMENT_TYPE
  ui?: boolean

  colorMap?: COLOR_MAP_TYPE

  fov?: number
  vrMode?: boolean
  webGPU?: boolean
  performanceMode?: boolean
  debuggerMode?: boolean
  productionMode?: boolean
}

export class AppHypercube3d extends APIInterface {
  static async init({
    divID,
    ui = false,
    webGPU = false,
    performanceMode = false,
    debuggerMode = false,
    productionMode = true,
    vrMode = true,
    fov,
    environmentType
  }: AppHypercube3dInitParams) {
    const app = new AppHypercube3d({
      divID,
      ui,
      webGPU,
      vrMode,
      performanceMode,
      debuggerMode,
      environmentType,
      productionMode
    })
    await app.init()
    if (fov) app.appCore.common.setFOV(fov)
    return app
  }

  public RendererCore!: RendererCore
  public appCore!: AppCore
  public view: View | undefined = undefined
  public id: string

  public navigationScene: boolean
  public isPerformanceMode: boolean
  public webGPU: boolean = false
  public debuggerMode: boolean = false
  public productionMode: boolean = true
  public debuggerUI: boolean = false
  public vrMode: boolean = false
  public environmentType: ENVIRONMENT_TYPE

  private _isProduction = false

  constructor({
    divID = 'main',
    ui = false,
    webGPU = false,
    vrMode = true,
    performanceMode = false,
    debuggerMode = false,
    productionMode = true,
    environmentType
  }: AppHypercube3dInitParams) {
    super()
    const params = new URLSearchParams(window.location.search)

    this.navigationScene = params.get('sc') === '1'
    // params.get('performance') === 'true' || performanceMode

    this._isProduction = productionMode
    this.isPerformanceMode = performanceMode
    this.id = divID
    this.webGPU = webGPU
    this.debuggerMode = debuggerMode
    this.vrMode = vrMode
    this.debuggerUI = ui
    this.environmentType = environmentType as ENVIRONMENT_TYPE

    // console.log(this.environmentType)
    if (!this._isProduction) {
      // console.log(this.isPerformanceMode ? 'PerformanceMode' : 'QualityMode')
    }
    // console.log('app starting...')
  }
  public emitAction = (val: string) => {}
  public get isProduction() {
    return this._isProduction
  }
  public async init() {
    // console.log('app init - start')
    await this.initRenderer()
    await this.initApp()

    if (this.debuggerMode && this.debuggerUI) await this.initView()
    this.bindEvent()
    this.bindRenderer()
    // console.log('app init - end')
  }
  private async initRenderer() {
    this.RendererCore = new RendererCore(
      this.id,
      this.isPerformanceMode,
      this._isProduction,
      this.environmentType
    )
    this.RendererCore.useWebGPU = this.webGPU
    this.RendererCore.vrMode = this.vrMode
    this.RendererCore.debuggerMode = this.debuggerMode
    await this.RendererCore.init()
  }
  private async initView() {
    this.view = new View(this)
    await this.view.init()
  }
  private async initApp() {
    this.appCore = new AppCore(
      this,
      this.isPerformanceMode,
      this.navigationScene
    )
    await this.appCore.init()
  }
  // EX: toggleEnvColor@PARAM
  public pushAction(action: string) {
    // console.log('action from HC3D:', action)
    return this.appCore.pushAction(action)
  }
  public bindEvent() {
    this.RendererCore.onMouseEventListener = (
      e: MouseEvent,
      type: CLICK_TYPE
    ) => this.appCore.onMouseEventListener(e, type)
  }
  public bindRenderer() {
    this.RendererCore.update = () => this.appCore.update()
  }
  public destroy() {
    this.RendererCore?.destroy()
    this.view?.destroy()
    this.appCore?.destroy()
    // console.log('destroy Hypercube 3D lib...')
  }
}
