import * as THREE from 'three'

import { Hypercube } from '..'
import { DIRECTION } from '../../../../utils/const'

export class DoorInner {
  public hypercube: Hypercube
  public meshGroup: THREE.Group
  public open = false

  private direction: DIRECTION

  private closedX = 0
  private openX = 0
  private targetX = 0
  private speed = 0.02

  constructor(
    hypercube: Hypercube,
    meshGroup: THREE.Group,
    direction: DIRECTION
  ) {
    this.hypercube = hypercube
    this.meshGroup = meshGroup
    this.direction = direction

    this.closedX = meshGroup.position.x

    const offset = 5.5
    this.openX =
      direction === DIRECTION.Left
        ? this.closedX - offset
        : this.closedX + offset

    this.targetX = this.closedX

    this.hypercube.sceneWrapper.scene.add(this.meshGroup)
  }

  public update() {
    if (Math.abs(this.targetX - this.meshGroup.position.x) < 0.05) {
      this.meshGroup.position.x = this.targetX
      return false
    }

    this.meshGroup.position.x +=
      (this.targetX - this.meshGroup.position.x) * this.speed // * this.hypercube.core.threeCore.rendererWrapper.deltaTime;
    return true
  }
  public set visible(v: boolean) {
    this.meshGroup.children.forEach((mesh) => {
      mesh.visible = v
    })
  }
  public onClick() {
    this.open = !this.open
    this.targetX = this.open ? this.openX : this.closedX
    // console.log(`Door is now ${this.open ? "open" : "closed"}`);
  }
}
