import * as THREE from 'three'

import { getSlider } from '../../../utils'

export class VRProjector {
  public mesh: THREE.Mesh
  public meshBox: THREE.Mesh
  public scene: THREE.Scene
  public size: number = 10

  private renderer: THREE.WebGLRenderer
  private scale = 1
  private fov = 90
  private divHost: HTMLDivElement
  private divContainer: HTMLDivElement
  private vrMode: boolean = false
  private meshTest: THREE.Mesh

  private arrowHelpers: THREE.ArrowHelper[] = []
  private cameras: THREE.PerspectiveCamera[] = []
  private cameraHelpers: THREE.CameraHelper[] = []
  private markers: THREE.Mesh[] = []
  private cones: THREE.Mesh[] = []
  private sprites: THREE.Sprite[] = []

  private renderTargets: THREE.WebGLRenderTarget[] = []
  private equirectMaterial: THREE.ShaderMaterial
  private equirectRT: THREE.WebGLRenderTarget

  private canvasPreviewRef: HTMLCanvasElement
  private equirectPreviewRef: HTMLCanvasElement
  private quadScene: THREE.Scene
  private quadCamera: THREE.OrthographicCamera
  private renderSize = 512
  private blendWidth = 1

  public importMode: () => void
  private updatePanorama: () => void
  private downloadEquirectangular: () => void

  constructor(
    scene: THREE.Scene,
    renderer: THREE.WebGLRenderer,
    divHost: HTMLDivElement
  ) {
    this.scene = scene
    this.renderer = renderer
    this.divHost = divHost
    this.init()
  }

  public show(value: boolean) {
    return value
  }

  private init() {
    this.initScene()
    this.initUI()
  }

  public initUI() {
    const uiContainer = document.createElement('div')
    this.divContainer.appendChild(uiContainer)

    const btn = document.createElement('Button')
    btn.textContent = 'toggle'
    btn.onclick = () => {
      this.vrMode = !this.vrMode
      this.mesh.visible = this.vrMode
      this.arrowHelpers.forEach((arrow) => (arrow.visible = !this.vrMode))
      this.meshBox.visible = !this.vrMode
    }
    uiContainer.appendChild(btn)

    const btnDownload = document.createElement('Button')
    btnDownload.textContent = 'download'
    btnDownload.onclick = () => this.downloadEquirectangular()
    uiContainer.appendChild(btnDownload)

    const btnImportHypercube = document.createElement('Button')
    btnImportHypercube.textContent = 'Import model'
    btnImportHypercube.onclick = () => this.importMode()
    uiContainer.appendChild(btnImportHypercube)

    const slider = getSlider('fov', 50, 150, 1, this.fov)
    slider.slider.oninput = () => {
      this.fov = parseFloat(slider.slider.value)
    }
    uiContainer.appendChild(slider.div)

    const sliderScale = getSlider('size', 1, 500, 5, this.size * 10)
    sliderScale.slider.oninput = () => {
      this.size = parseFloat(sliderScale.slider.value) * 0.1
      this.updateSize()
    }
    uiContainer.appendChild(sliderScale.div)
  }

  private getCameraConfigs() {
    const scale = this.size * 0.5
    return [
      {
        pos: new THREE.Vector3(scale, scale, -scale),
        lookAt: new THREE.Vector3(scale + 10, scale, -scale)
      },
      {
        pos: new THREE.Vector3(scale, scale, scale),
        lookAt: new THREE.Vector3(scale + 10, scale, scale)
      },
      {
        pos: new THREE.Vector3(-scale, scale, scale),
        lookAt: new THREE.Vector3(-scale - 10, scale, scale)
      },
      {
        pos: new THREE.Vector3(-scale, scale, -scale),
        lookAt: new THREE.Vector3(-scale - 10, scale, -scale)
      },
      {
        pos: new THREE.Vector3(-scale, scale, scale),
        lookAt: new THREE.Vector3(-scale, scale, scale + 10)
      },
      {
        pos: new THREE.Vector3(scale, scale, scale),
        lookAt: new THREE.Vector3(scale, scale, scale + 10)
      },
      {
        pos: new THREE.Vector3(scale, scale, -scale),
        lookAt: new THREE.Vector3(scale, scale, -scale - 10)
      },
      {
        pos: new THREE.Vector3(-scale, scale, -scale),
        lookAt: new THREE.Vector3(-scale, scale, -scale - 10)
      }
    ]
  }

  private updateSize() {
    this.meshBox.scale.setScalar(this.size)

    const configs = this.getCameraConfigs()
    configs.forEach((config, i) => {
      const direction = new THREE.Vector3()
        .subVectors(config.lookAt, config.pos)
        .normalize()

      this.cameras[i].position.copy(config.pos)
      this.cameras[i].lookAt(config.lookAt)
      this.cameraHelpers[i].update()

      this.markers[i].position.copy(config.pos)
      this.markers[i].scale.setScalar(this.size * 0.02)

      this.arrowHelpers[i].position.copy(config.pos)
      this.arrowHelpers[i].setDirection(direction)
      this.arrowHelpers[i].setLength(
        this.size * 0.3,
        this.size * 0.05,
        this.size * 0.03
      )

      // this.cones[i].position.copy(config.pos)
      // this.cones[i].quaternion.setFromUnitVectors(
      //   new THREE.Vector3(0, 1, 0),
      //   direction
      // )
      // this.cones[i].scale.setScalar(this.size * 0.15)

      this.sprites[i].position
        .copy(config.pos)
        .add(direction.clone().multiplyScalar(-this.size * 0.08))
      this.sprites[i].scale.setScalar(this.size * 0.1)
    })
  }

  private initScene() {
    this.divContainer = document.createElement('div')
    this.divContainer.style.position = 'absolute'
    this.divContainer.style.marginLeft = '60px'
    this.divHost.prepend(this.divContainer)

    const geometry = new THREE.BoxGeometry(1, 1, 1)
    const material = new THREE.MeshStandardMaterial({
      color: 0xcdcdcd,
      wireframe: true
    })
    this.meshBox = new THREE.Mesh(geometry, material)
    this.meshBox.scale.setScalar(this.size)
    this.scene.add(this.meshBox)

    const geometryTest = new THREE.BoxGeometry(8, 18, 8)
    geometryTest.translate(100, 0, 0)
    const materialTest = new THREE.MeshStandardMaterial({ color: 0xff0000 })
    this.meshTest = new THREE.Mesh(geometryTest, materialTest)
    this.scene.add(this.meshTest)

    const configs = this.getCameraConfigs()

    configs.forEach((config, i) => {
      const camera = new THREE.PerspectiveCamera(this.fov, 1, 0.1, 1000)
      camera.position.copy(config.pos)
      camera.lookAt(config.lookAt)
      this.cameras.push(camera)

      const renderTarget = new THREE.WebGLRenderTarget(
        this.renderSize,
        this.renderSize
      )
      this.renderTargets.push(renderTarget)

      const helper = new THREE.CameraHelper(camera)
      this.scene.add(helper)
      this.cameraHelpers.push(helper)

      const markerGeo = new THREE.SphereGeometry(1)
      const markerMat = new THREE.MeshBasicMaterial({
        color: 0xff0000,
        transparent: true,
        opacity: 0.8
      })
      const marker = new THREE.Mesh(markerGeo, markerMat)
      marker.position.copy(config.pos)
      marker.scale.setScalar(this.size * 0.02)
      this.scene.add(marker)
      this.markers.push(marker)

      const direction = new THREE.Vector3()
        .subVectors(config.lookAt, config.pos)
        .normalize()
      const arrowHelper = new THREE.ArrowHelper(
        direction,
        config.pos,
        this.size * 0.3,
        0xffff00,
        this.size * 0.05,
        this.size * 0.03
      )
      this.arrowHelpers.push(arrowHelper)
      this.scene.add(arrowHelper)

      const fovRad = THREE.MathUtils.degToRad(this.fov)
      const coneHeight = 1
      const coneRadius = Math.tan(fovRad / 2) * coneHeight
      const coneGeo = new THREE.ConeGeometry(coneRadius, coneHeight, 8, 1, true)
      const coneMat = new THREE.MeshBasicMaterial({
        color: 0x00ffff,
        wireframe: true,
        transparent: true,
        opacity: 0.3
      })

      const cone = new THREE.Mesh(coneGeo, coneMat)
      cone.position.copy(config.pos)
      cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), direction)
      cone.scale.setScalar(this.size * 0.15)
      // this.scene.add(cone)
      // this.cones.push(cone)

      const labelCanvas = document.createElement('canvas')
      labelCanvas.width = 256
      labelCanvas.height = 128
      const ctx = labelCanvas.getContext('2d') as CanvasRenderingContext2D
      ctx.fillStyle = 'rgba(0, 0, 0, 0.8)'
      ctx.fillRect(0, 0, 256, 128)
      ctx.fillStyle = '#ffffff'
      ctx.font = 'bold 48px Arial'
      ctx.textAlign = 'center'
      ctx.fillText(`Cam ${i + 1}`, 128, 80)

      const texture = new THREE.CanvasTexture(labelCanvas)
      const spriteMat = new THREE.SpriteMaterial({ map: texture })
      const sprite = new THREE.Sprite(spriteMat)
      sprite.position
        .copy(config.pos)
        .add(direction.clone().multiplyScalar(-this.size * 0.08))
      sprite.scale.setScalar(this.size * 0.1)
      this.scene.add(sprite)
      this.sprites.push(sprite)
    })

    const equirectShader = {
      uniforms: {
        cam0: { value: null },
        cam1: { value: null },
        cam2: { value: null },
        cam3: { value: null },
        cam4: { value: null },
        cam5: { value: null },
        cam6: { value: null },
        cam7: { value: null },
        cameraPositions: { value: configs.map((c) => c.pos) },
        cameraLookAts: { value: configs.map((c) => c.lookAt) },
        blendWidth: { value: this.blendWidth },
        fov: { value: THREE.MathUtils.degToRad(this.fov) }
      },
      vertexShader: vertexShader,
      fragmentShader: fragmentShader
    }

    this.equirectRT = new THREE.WebGLRenderTarget(
      2048 * this.scale,
      1024 * this.scale
    )
    const tex = this.equirectRT.texture
    tex.center.set(0.5, 0.5)
    tex.rotation = Math.PI
    tex.flipY = false
    tex.wrapS = THREE.RepeatWrapping
    tex.repeat.x = -1
    tex.offset.x = 1

    this.equirectMaterial = new THREE.ShaderMaterial(equirectShader)
    const quadGeo = new THREE.PlaneGeometry(2, 2)
    const quadMesh = new THREE.Mesh(quadGeo, this.equirectMaterial)
    this.quadScene = new THREE.Scene()
    this.quadScene.add(quadMesh)
    this.quadCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1)

    const panoramaSphere = new THREE.SphereGeometry(500, 60, 40)
    const panoramaMaterial = new THREE.MeshBasicMaterial({
      map: tex,
      side: THREE.BackSide
    })
    this.mesh = new THREE.Mesh(panoramaSphere, panoramaMaterial)
    this.mesh.rotation.y = Math.PI / 2
    this.mesh.visible = false

    this.canvasPreviewRef = document.createElement('canvas')
    this.canvasPreviewRef.style.width = '600px'
    this.divContainer.appendChild(this.canvasPreviewRef)

    this.equirectPreviewRef = document.createElement('canvas')
    this.equirectPreviewRef.style.marginLeft = '10px'
    this.equirectPreviewRef.style.width = '600px'
    this.divContainer.appendChild(this.equirectPreviewRef)

    this.updatePanorama = () => {
      const configs = this.getCameraConfigs()

      this.cameras.forEach((cam, i) => {
        cam.fov = this.fov
        cam.updateProjectionMatrix()
        this.cameraHelpers[i].update()
        this.cameraHelpers[i].visible = !this.vrMode
      })

      this.scene.remove(this.mesh)
      this.cameras.forEach((camera, i) => {
        this.renderer.setRenderTarget(this.renderTargets[i])
        this.renderer.render(this.scene, camera)
      })
      this.renderer.setRenderTarget(null)
      this.scene.add(this.mesh)

      for (let i = 0; i < 8; i++) {
        this.equirectMaterial.uniforms[`cam${i}`].value =
          this.renderTargets[i].texture
      }
      this.equirectMaterial.uniforms.blendWidth.value = this.blendWidth
      this.equirectMaterial.uniforms.fov.value = THREE.MathUtils.degToRad(
        this.fov
      )
      this.equirectMaterial.uniforms.cameraPositions.value = configs.map(
        (c) => c.pos
      )
      this.equirectMaterial.uniforms.cameraLookAts.value = configs.map(
        (c) => c.lookAt
      )

      this.renderer.setRenderTarget(this.equirectRT)
      this.renderer.render(this.quadScene, this.quadCamera)
      this.renderer.setRenderTarget(null)

      const w = 2048 * this.scale
      const h = 1024 * this.scale

      const ctx = this.canvasPreviewRef.getContext(
        '2d'
      ) as CanvasRenderingContext2D
      this.canvasPreviewRef.width = w
      this.canvasPreviewRef.height = h
      ctx.fillStyle = '#0a0a0a'
      ctx.fillRect(0, 0, w, h)

      for (let i = 0; i < 8; i++) {
        const x = (i % 4) * (w / 4)
        const y = Math.floor(i / 4) * (h / 2)
        const tempCanvas = document.createElement('canvas')
        tempCanvas.width = this.renderSize
        tempCanvas.height = this.renderSize
        const tempCtx = tempCanvas.getContext('2d') as CanvasRenderingContext2D
        const pixels = new Uint8Array(this.renderSize * this.renderSize * 4)
        this.renderer.readRenderTargetPixels(
          this.renderTargets[i],
          0,
          0,
          this.renderSize,
          this.renderSize,
          pixels
        )
        const imageData = new ImageData(
          new Uint8ClampedArray(pixels),
          this.renderSize,
          this.renderSize
        )
        tempCtx.putImageData(imageData, 0, 0)
        ctx.save()
        ctx.translate(x, y + h / 2)
        ctx.scale(1, -1)
        ctx.drawImage(tempCanvas, 0, 0, w / 4, h / 2)
        ctx.restore()
        ctx.strokeStyle = '#ffffff'
        ctx.lineWidth = 3
        ctx.strokeRect(x, y, w / 4, h / 2)
        ctx.fillStyle = 'rgba(0, 0, 0, 0.8)'
        ctx.fillRect(x + 10, y + 10, 140, 40)
        ctx.fillStyle = '#ffffff'
        ctx.font = 'bold 20px Arial'
        ctx.fillText(`Cam ${i + 1}`, x + 20, y + 38)
      }

      const ctx2 = this.equirectPreviewRef.getContext(
        '2d'
      ) as CanvasRenderingContext2D
      this.equirectPreviewRef.width = w
      this.equirectPreviewRef.height = h
      const pixels = new Uint8Array(w * h * 4)
      this.renderer.readRenderTargetPixels(this.equirectRT, 0, 0, w, h, pixels)
      const imageData = new ImageData(new Uint8ClampedArray(pixels), w, h)
      ctx2.putImageData(imageData, 0, 0)
      ctx2.strokeStyle = 'rgba(255, 255, 255, 0.1)'
      ctx2.lineWidth = 1
      for (let i = 0; i <= 8; i++) {
        const gx = (i / 8) * w
        ctx2.beginPath()
        ctx2.moveTo(gx, 0)
        ctx2.lineTo(gx, h)
        ctx2.stroke()
      }
      for (let i = 0; i <= 4; i++) {
        const gy = (i / 4) * h
        ctx2.beginPath()
        ctx2.moveTo(0, gy)
        ctx2.lineTo(w, gy)
        ctx2.stroke()
      }
      ctx2.fillStyle = 'rgba(0, 0, 0, 0.8)'
      ctx2.fillRect(10, 10, 350, 45)
      ctx2.fillStyle = '#ffffff'
      ctx2.font = 'bold 24px Arial'
      ctx2.fillText(`360° Blended (FOV: ${this.fov}°)`, 20, 42)
    }

    this.downloadEquirectangular = () => {
      const w = 2048 * this.scale
      const h = 1024 * this.scale
      const downloadCanvas = document.createElement('canvas')
      downloadCanvas.width = w
      downloadCanvas.height = h
      const ctx = downloadCanvas.getContext('2d') as CanvasRenderingContext2D
      const pixels = new Uint8Array(w * h * 4)
      this.renderer.readRenderTargetPixels(this.equirectRT, 0, 0, w, h, pixels)
      const imageData = new ImageData(new Uint8ClampedArray(pixels), w, h)
      ctx.putImageData(imageData, 0, 0)
      const link = document.createElement('a')
      link.download = `panorama_fov${this.fov}_blend${this.blendWidth.toFixed(2)}.png`
      link.href = downloadCanvas.toDataURL('image/png')
      link.click()
    }
  }

  public update() {
    this.meshTest.rotation.y += 0.01
    this.updatePanorama()
    return true
  }
}

const vertexShader = `
  varying vec2 vUv;
  void main() {
      vUv = uv;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
  }
`

const fragmentShader = `
  uniform sampler2D cam0, cam1, cam2, cam3, cam4, cam5, cam6, cam7;
  uniform vec3 cameraPositions[8];
  uniform vec3 cameraLookAts[8];
  uniform float blendWidth;
  uniform float fov;
  varying vec2 vUv;
  const float PI = 3.14159265359;

  vec3 equirectToDirection(vec2 uv) {
      float theta = uv.x * 2.0 * PI;
      float phi = uv.y * PI;
      return vec3(sin(phi) * sin(theta), cos(phi), sin(phi) * cos(theta));
  }

  vec4 sampleCamera(sampler2D cam, vec3 dir, vec3 camPos, vec3 camLookAt) {
      vec3 camForward = normalize(camLookAt - camPos);
      vec3 worldUp = vec3(0.0, 1.0, 0.0);
      vec3 camRight = normalize(cross(camForward, worldUp));
      vec3 camUp = normalize(cross(camRight, camForward));
      float dotForward = dot(dir, camForward);
      if (dotForward <= 0.0) return vec4(0.0);
      float dotRight = dot(dir, camRight);
      float dotUp = dot(dir, camUp);
      float fovScale = tan(fov / 2.0);
      float scale = fovScale / dotForward;
      vec2 uv = vec2(dotRight * scale, dotUp * scale);
      uv = uv * 0.5 + 0.5;
      if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
          return vec4(0.0);
      }
      return texture2D(cam, uv);
  }

  void main() {
      vec3 dir = equirectToDirection(vUv);
      float dots[8];
      float maxDot = -1.0;
      for (int i = 0; i < 8; i++) {
          vec3 camForward = normalize(cameraLookAts[i] - cameraPositions[i]);
          dots[i] = dot(dir, camForward);
          maxDot = max(maxDot, dots[i]);
      }
      vec4 finalColor = vec4(0.0);
      float totalWeight = 0.0;
      vec4 colors[8];
      colors[0] = sampleCamera(cam0, dir, cameraPositions[0], cameraLookAts[0]);
      colors[1] = sampleCamera(cam1, dir, cameraPositions[1], cameraLookAts[1]);
      colors[2] = sampleCamera(cam2, dir, cameraPositions[2], cameraLookAts[2]);
      colors[3] = sampleCamera(cam3, dir, cameraPositions[3], cameraLookAts[3]);
      colors[4] = sampleCamera(cam4, dir, cameraPositions[4], cameraLookAts[4]);
      colors[5] = sampleCamera(cam5, dir, cameraPositions[5], cameraLookAts[5]);
      colors[6] = sampleCamera(cam6, dir, cameraPositions[6], cameraLookAts[6]);
      colors[7] = sampleCamera(cam7, dir, cameraPositions[7], cameraLookAts[7]);
      for (int i = 0; i < 8; i++) {
          if (colors[i].a > 0.0 && dots[i] > 0.0) {
              float weight = smoothstep(maxDot - blendWidth, maxDot, dots[i]);
              finalColor += colors[i] * weight;
              totalWeight += weight;
          }
      }
      if (totalWeight > 0.0) finalColor /= totalWeight;
      gl_FragColor = finalColor;
  }
`
