import * as THREE from 'three'

import { Nubbin } from '.'
import { NubbinBase } from './Base/NubbinBase'
import { loadFBXWithMat, subtractMeshs } from '../../../../../utils/ThreeUtils'

export class CantileverDrone extends NubbinBase {
  public meshDoor: THREE.Mesh[] = []

  private radius: number = 6.5
  private count = 18

  private maxDoor = 1.7
  private minDoor = 0.75
  private valueDoor = this.maxDoor

  private hasAnimation: boolean = false
  private needOpen: boolean = true

  constructor(addon: Nubbin) {
    super(addon)

    this.buildMesh()
  }
  public buildMesh() {
    if (this.mesh) {
      this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.remove(
        this.mesh
      )
    }

    this.mesh = new THREE.Group()
    this.mesh.name = 'CantileverDrone'
    const width = 15
    const length = width
    const height = 3.5
    const geometry = new THREE.BoxGeometry(width, height, length)
    geometry.translate(0, -height * 0.5, 0)
    // const material = new THREE.MeshStandardMaterial({ color: 0x808080 })
    const box1 = new THREE.Mesh(
      geometry,
      this.nubbin.hypercubeParametric.configurator.materials.skeletonMaterial
    )
    box1.castShadow = true
    box1.receiveShadow = true

    const radius = this.radius - 1.5
    const geometry2 = new THREE.CylinderGeometry(
      radius,
      radius,
      height,
      length,
      this.count
    )
    geometry2.translate(0, -1, 0)
    const box2 = new THREE.Mesh(
      geometry2,
      this.nubbin.hypercubeParametric.configurator.materials.skeletonMaterial
    )

    const meshDroneNest = subtractMeshs(
      box1,
      [box2],
      this.nubbin.hypercubeParametric.configurator.materials.skeletonMaterial
    )
    meshDroneNest.castShadow = true
    meshDroneNest.receiveShadow = true
    meshDroneNest.userData.onClick = () => this.onClick()
    this.mesh.add(meshDroneNest)

    this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.add(
      this.mesh
    )
    this.syncSizes()

    this.loadModel(
      [
        // addon.hypercubeParametric.configurator.BASE_URL + 'Cellular.fbx',
        '/hypercube-asset/model/drone-circle-door-element.fbx'
      ],
      0.015
    )

    // this.starLink = new StarLink(this)
    // this.starLink.init()
  }
  private loadModel = async (files: string[], scale: number) => {
    // console.log(files, scale);

    try {
      this.meshDoor = []
      const loadPromises = files.map((file) =>
        loadFBXWithMat(
          file,
          scale,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .rendererCore.useWebGPU,
          this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore
            .isPerformanceMode,
          this.nubbin.hypercubeParametric.configurator.materials.clippingPlanes,
          this.nubbin.hypercubeParametric.configurator.materials.MaterialClass,
          this.nubbin.hypercubeParametric.configurator.materials
            .skeletonMaterial
        )
      )
      // console.log('=====!!!===================')
      const fbxModels = await Promise.all(loadPromises)
      fbxModels[0].rotation.y = -Math.PI * 0.5

      // this.mesh?.add(fbxModels[0])

      const points: THREE.Vector3[] = []

      const zOff = -0.3
      for (let i = 0; i < this.count; i++) {
        const theta = (Math.PI * 2 * i) / this.count

        const x = Math.cos(theta) * this.radius
        const z = Math.sin(theta) * this.radius

        points.push(new THREE.Vector3(x, 0, z))

        const doorElement = fbxModels[0].clone(true)
        doorElement.position.set(x, i % 2 === 0 ? zOff : zOff + 0.15, z)
        doorElement.children[0].material =
          this.nubbin.hypercubeParametric.configurator.materials.skeletonMaterial

        doorElement.castShadow = true
        doorElement.receiveShadow = true
        doorElement.userData.onClick = () => this.onClick()
        // console.log('doorElement', doorElement)
        // const theta = Math.atan2(door.position.x, door.position.z)
        // doorElement.rotation.y += 1
        // doorElement.lookAt(new THREE.Vector3(0, 0, 0))
        this.mesh?.add(doorElement)
        // this.meshDoor.add(doorElement)
        this.meshDoor.push(doorElement)
      }
      this.rotationDoor(1.7)
      // this.mesh.children[1].visible = false
      //   this.mesh.children[1].material =
      //     this.addon.hypercubeParametric.configurator.materials.aluminumMaterial

      //   this.mesh.children[0].material.color = new THREE.Color(0xd9d9d9)
      //   this.mesh.children[2].material.color = new THREE.Color(0xd9d9d9)

      this.nubbin.hypercubeParametric.configurator.sceneWrapper.scene.add(
        this.mesh
      )

      // this.mesh.position.y = this.addon.hypercubeParametric.params.height - 2
      // this.mesh.position.x = -10
      // this.mesh.position.z = -10
      this.syncSizes()

      // console.log(this.mesh)
    } catch (error) {
      console.error('fail to load :', error)
    }
  }

  public syncSizes() {
    if (this.mesh) {
      this.mesh.position.x =
        -this.nubbin.hypercubeParametric.params.width * 0.5 -
        this.nubbin.hypercubeParametric.params.thickness

      this.mesh.position.y = this.nubbin.hypercubeParametric.params.height * 0.5
      // this.addon.hypercubeParametric.params.groundY

      this.mesh.position.z =
        -this.nubbin.hypercubeParametric.params.length * 0.5 -
        this.nubbin.hypercubeParametric.params.thickness
    }
  }
  public toggleVisibility() {
    this.mesh.visible = !this.mesh.visible
  }
  public rotationDoor(v: number) {
    // const value = v
    // const max = 1.7
    // const min = 0.75
    const value =
      v < this.minDoor ? this.minDoor : v > this.maxDoor ? this.maxDoor : v
    // console.log('rotationDoor v', v)
    this.meshDoor.forEach((door) => {
      const theta = Math.atan2(door.position.x, door.position.z)
      door.rotation.y = theta + value
    })
  }
  public openNest() {
    this.needOpen = true
    this.hasAnimation = true
  }
  public closeNest() {
    this.needOpen = false
    this.hasAnimation = true
  }
  public onClick() {
    this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.common.commandHypercubeParametric.onFocus(
      this.mesh
    )
    this.nubbin.hypercubeParametric.configurator.sceneWrapper.appCore.actionStateProcessor.emitAction(
      'CantileverDrone@'
    )
    this.hasAnimation = true
  }
  public updateDoorAnimation() {
    const step = 0.02
    const targetValue = this.needOpen ? this.minDoor : this.maxDoor
    const direction = this.needOpen ? -1 : 1

    this.valueDoor += step * direction

    const hasReachedTarget = this.needOpen
      ? this.valueDoor <= targetValue
      : this.valueDoor >= targetValue

    if (hasReachedTarget) {
      this.valueDoor = targetValue
      this.hasAnimation = false
      this.needOpen = !this.needOpen
    }

    this.rotationDoor(this.valueDoor)
    return true
  }
  public update(): boolean {
    if (!this.hasAnimation) return false

    this.updateDoorAnimation()

    return true
  }
}
