import { AppHypercube3d } from '..'
import { RendererCore } from '../RendererCore'
import { ActionStateProcessor } from './ActionStateProcessor'
import { ActiveCommand } from './ActiveCommand'
import { AppCommon } from './AppCommon'
import { Asset } from './Asset'
import { SceneWrapper } from './SceneWrapper'
import { CLICK_TYPE } from '../utils/const'

export class AppCore {
  public app: AppHypercube3d
  public rendererCore: RendererCore

  public activeCommand!: ActiveCommand
  public actionStateProcessor!: ActionStateProcessor

  public common!: AppCommon
  public asset!: Asset

  public sceneWrapper!: SceneWrapper

  public navigationScene = true
  public isPerformanceMode = true

  constructor(
    app: AppHypercube3d,
    isPerformanceMode = false,
    navigationScene = false
  ) {
    this.app = app
    this.rendererCore = app.RendererCore

    this.isPerformanceMode = isPerformanceMode
    this.navigationScene = navigationScene

    this.activeCommand = new ActiveCommand(this)
    this.app.RendererCore.readyBinding = () => {
      return this.ready
    }
  }
  public async init() {
    this.asset = new Asset(this)
    await this.asset.init()

    this.sceneWrapper = new SceneWrapper(this, this.app.environmentType)

    await this.sceneWrapper.init()
    this.sceneWrapper.activateGlobe = this.navigationScene

    this.common = new AppCommon(this)
    this.actionStateProcessor = new ActionStateProcessor(this)
  }
  public initPost() {
    this.sceneWrapper.initPost()
  }
  public get ready() {
    return this.sceneWrapper.ready
  }
  public update(): boolean {
    return this.sceneWrapper.update()
  }
  public onMouseEventListener(e: MouseEvent, type: CLICK_TYPE) {
    this.activeCommand.onMouseEventListener(e, type)
  }
  public pushAction(action: string) {
    return this.actionStateProcessor.pushAction(action)
  }
  public destroy() {
    this.common?.destroy()
    this.sceneWrapper?.destroy()
  }
}
