import * as THREE from 'three'

import { Hypercube } from '..'

export class DoorOuter {
  public hypercube: Hypercube
  public meshGroup: THREE.Group

  private open = false

  private closedY = 0
  private openY = 0
  private targetY = 0
  private speed = 0.05

  private clippingPlane = new THREE.Plane(new THREE.Vector3(0, -1, 0), 17)

  constructor(hypercube: Hypercube, meshGroup: THREE.Group) {
    this.hypercube = hypercube
    this.meshGroup = meshGroup

    this.meshGroup.children.forEach((element: THREE.Mesh) => {
      element.material = this.hypercube.materials.skinMaterial
      // console.log(element.material);
      // element.material.needsUpdate = true;
    })

    this.closedY = meshGroup.position.y

    const offset = 25
    this.openY = this.closedY + offset
    this.targetY = this.closedY

    this.applyClipping(this.meshGroup)

    this.hypercube.sceneWrapper.scene.add(this.meshGroup)
  }

  public update() {
    if (Math.abs(this.targetY - this.meshGroup.position.y) < 0.1) {
      return false
    }

    this.meshGroup.position.y +=
      (this.targetY - this.meshGroup.position.y) * this.speed // * this.hypercube.sceneWrapper.deltaTime;
    return true
  }

  public onClick() {
    this.open = !this.open
    this.targetY = this.open ? this.openY : this.closedY

    if (!this.open && this.hypercube.doorInnerA.open) {
      this.hypercube.doorInnerA.onClick()
      this.hypercube.doorInnerB.onClick()
    }

    // console.log(this.targetY, this.openY, this.closedY);
  }
  public set visible(v: boolean) {
    this.meshGroup.children.forEach((mesh) => {
      mesh.visible = v
    })
  }
  private applyClipping(group: THREE.Group) {
    // group.traverse((child) => {
    // 	if ((child as THREE.Mesh).isMesh) {
    // 		const mesh = child as THREE.Mesh;
    // 		const material = mesh.material;

    // 		if ((material as THREE.Material).clippingPlanes !== undefined) {
    // 			const m = material as THREE.MeshStandardMaterial;
    // 			m.clippingPlanes = [this.clippingPlane];
    // 			m.clipShadows = true;
    // 		}
    // 	}
    // });

    group.traverse((child) => {
      if ((child as THREE.Mesh).isMesh) {
        const mesh = child as THREE.Mesh
        const materials = Array.isArray(mesh.material)
          ? mesh.material
          : [mesh.material]

        for (const material of materials) {
          if (
            !this.hypercube.sceneWrapper.appCore.rendererCore.useWebGPU &&
            'clippingPlanes' in material
          ) {
            ;(material as THREE.MeshStandardMaterial).clippingPlanes = [
              this.clippingPlane
            ]
            ;(material as THREE.MeshStandardMaterial).clipShadows = true
          }
        }
      }
    })
  }
}
